export interface InventoryItem {
  id: string;
  name: string;
  category: string;
  quantity: number;
  costPrice: number;
  salesPrice: number;
  lowStockThreshold: number;
  lastUpdated: string;
}

export interface SaleItem {
  itemId: string;
  name: string;
  quantity: number;
  priceAtSale: number;
  costAtSale: number;
  discount?: number;
}

export interface SaleRecord {
  id: string;
  items: SaleItem[];
  totalAmount: number;
  totalProfit: number;
  timestamp: string;
}

export interface ExpenseRecord {
  id: string;
  description: string;
  amount: number;
  category: string;
  date: string;
  recordedAt: string;
}

export interface PurchaseOrderItem {
  itemId: string;
  name: string;
  quantity: number;
  unitCost: number;
}

export interface PurchaseOrder {
  id: string;
  supplier: string;
  date: string;
  status: 'ordered' | 'received' | 'cancelled';
  items: PurchaseOrderItem[];
  totalCost: number;
  notes?: string;
}

export type ViewState = 'dashboard' | 'inventory' | 'pos' | 'history' | 'expenses' | 'financials' | 'insights' | 'purchases';

export type UserRole = 'admin' | 'cashier';

export interface DashboardMetrics {
  totalRevenue: number;
  totalProfit: number;
  lowStockCount: number;
  totalInventoryValue: number;
}

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, ShoppingCart, BrainCircuit, Menu, X, History, Wifi, WifiOff, Loader2, DollarSign, PieChart, Truck, LogOut, Shield } from 'lucide-react';
import { InventoryManager } from './components/InventoryManager';
import { SalesTerminal } from './components/SalesTerminal';
import { Dashboard } from './components/Dashboard';
import { AIInsights } from './components/AIInsights';
import { SalesHistory } from './components/SalesHistory';
import { ExpensesManager } from './components/ExpensesManager';
import { FinancialReport } from './components/FinancialReport';
import { PurchaseOrdersManager } from './components/PurchaseOrdersManager';
import { Auth } from './components/Auth';
import { InventoryItem, SaleRecord, SaleItem, ViewState, ExpenseRecord, PurchaseOrder, UserRole } from './types';
import { supabase } from './services/supabaseClient';
import { Session } from '@supabase/supabase-js';

const App: React.FC = () => {
  // Auth State
  const [session, setSession] = useState<Session | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // State Management
  const [activeView, setActiveView] = useState<ViewState>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Data State
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [expenses, setExpenses] = useState<ExpenseRecord[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);

  // Connectivity Listeners
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Auth Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      // Reset view to dashboard on login
      if (session) setActiveView('dashboard');
    });

    return () => subscription.unsubscribe();
  }, []);

  // Fetch Data from Supabase
  const fetchData = async () => {
    if (!session) return; // Don't fetch if not logged in

    setLoading(true);
    try {
      // Fetch Inventory
      const { data: invData, error: invError } = await supabase
        .from('inventory')
        .select('*');

      if (invError) throw invError;
      if (invData) setInventory(invData);

      // Fetch Sales
      const { data: salesData, error: salesError } = await supabase
        .from('sales')
        .select('*')
        .order('timestamp', { ascending: false });

      if (salesError) throw salesError;
      if (salesData) setSales(salesData);

      // Fetch Expenses
      const { data: expData, error: expError } = await supabase
        .from('expenses')
        .select('*')
        .order('date', { ascending: false });

      if (expError) throw expError;
      if (expData) setExpenses(expData);

      // Fetch Purchase Orders
      const { data: poData, error: poError } = await supabase
        .from('purchase_orders')
        .select('*')
        .order('date', { ascending: false });

      if (poError) {
         console.warn("Could not fetch purchase orders. Table might not exist yet.");
      } else if (poData) {
         setPurchaseOrders(poData);
      }

    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch data when session becomes available
  useEffect(() => {
    if (session) {
      fetchData();
    }
  }, [session]);

  // Handlers
  const handleAddItem = async (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const newItem: InventoryItem = {
      ...item,
      id: crypto.randomUUID(), // Generate UUID
      lastUpdated: new Date().toISOString()
    };

    // Optimistic Update
    setInventory(prev => [...prev, newItem]);

    try {
      const { error } = await supabase.from('inventory').insert([newItem]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding item:", err);
      alert("Failed to save item to database.");
      fetchData(); // Revert on error
    }
  };

  const handleUpdateItem = async (id: string, updates: Partial<InventoryItem>) => {
    const updatedTimestamp = new Date().toISOString();
    const finalUpdates = { ...updates, lastUpdated: updatedTimestamp };

    // Optimistic Update
    setInventory(prev => prev.map(item => item.id === id ? { ...item, ...finalUpdates } : item));

    try {
      const { error } = await supabase
        .from('inventory')
        .update(finalUpdates)
        .eq('id', id);

      if (error) throw error;
    } catch (err) {
      console.error("Error updating item:", err);
      alert("Failed to update item in database.");
      fetchData(); // Revert
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      // Optimistic Update
      setInventory(prev => prev.filter(item => item.id !== id));

      try {
        const { error } = await supabase.from('inventory').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting item:", err);
        alert("Failed to delete item from database.");
        fetchData(); // Revert
      }
    }
  };

  const handleCompleteSale = async (items: SaleItem[]) => {
    // Calculate total amount considering discounts
    const totalAmount = items.reduce((sum, item) => 
      sum + ((item.quantity * item.priceAtSale) - (item.discount || 0)), 0
    );

    // Total cost is purely COGS
    const totalCost = items.reduce((sum, item) => sum + (item.quantity * item.costAtSale), 0);

    const newSale: SaleRecord = {
      id: crypto.randomUUID(),
      items,
      totalAmount,
      totalProfit: totalAmount - totalCost,
      timestamp: new Date().toISOString()
    };

    // Optimistic Update for UI
    const newInventory = [...inventory];
    items.forEach(saleItem => {
      const productIndex = newInventory.findIndex(p => p.id === saleItem.itemId);
      if (productIndex > -1) {
        newInventory[productIndex] = {
            ...newInventory[productIndex],
            quantity: newInventory[productIndex].quantity - saleItem.quantity,
            lastUpdated: new Date().toISOString()
        };
      }
    });

    setInventory(newInventory);
    setSales(prev => [newSale, ...prev]);

    try {
        // 1. Record Sale
        const { error: saleError } = await supabase.from('sales').insert([newSale]);
        if (saleError) throw saleError;

        // 2. Update Inventory Quantities
        for (const item of items) {
             const currentItem = inventory.find(i => i.id === item.itemId);
             if (currentItem) {
                 const newQty = currentItem.quantity - item.quantity;
                 await supabase
                    .from('inventory')
                    .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
                    .eq('id', item.itemId);
             }
        }
    } catch (err) {
        console.error("Error processing sale:", err);
        alert("Error saving sale to database. Please check connection.");
        fetchData(); // Revert to server state
    }
  };

  const handleAddExpense = async (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => {
    const newExpense: ExpenseRecord = {
      ...expense,
      id: crypto.randomUUID(),
      recordedAt: new Date().toISOString()
    };

    setExpenses(prev => [newExpense, ...prev]);

    try {
      const { error } = await supabase.from('expenses').insert([newExpense]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding expense:", err);
      alert("Failed to save expense.");
      fetchData();
    }
  };

  const handleDeleteExpense = async (id: string) => {
    if (window.confirm('Delete this expense record?')) {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting expense:", err);
        fetchData();
      }
    }
  };

  const handleCreatePO = async (po: Omit<PurchaseOrder, 'id'>) => {
    const newPO: PurchaseOrder = {
      ...po,
      id: crypto.randomUUID(),
    };

    setPurchaseOrders(prev => [newPO, ...prev]);

    try {
      const { error } = await supabase.from('purchase_orders').insert([newPO]);
      if (error) throw error;
    } catch (err) {
      console.error("Error creating PO:", err);
      alert("Failed to save Purchase Order.");
      fetchData();
    }
  };

  const handleUpdatePOStatus = async (id: string, status: 'received' | 'cancelled') => {
    const po = purchaseOrders.find(p => p.id === id);
    if (!po) return;

    // Optimistic Update
    setPurchaseOrders(prev => prev.map(p => p.id === id ? { ...p, status } : p));

    try {
      const { error } = await supabase
        .from('purchase_orders')
        .update({ status })
        .eq('id', id);

      if (error) throw error;

      // Logic: If marking as RECEIVED, update inventory stock
      if (status === 'received' && po.status !== 'received') {
        const updatedInventory = [...inventory];

        for (const item of po.items) {
           const invIndex = updatedInventory.findIndex(i => i.id === item.itemId);
           if (invIndex > -1) {
             const currentInv = updatedInventory[invIndex];
             const newQty = currentInv.quantity + item.quantity;

             // Update local state
             updatedInventory[invIndex] = {
               ...currentInv,
               quantity: newQty,
               lastUpdated: new Date().toISOString()
             };

             // Update Database
             await supabase
               .from('inventory')
               .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
               .eq('id', item.itemId);
           }
        }
        setInventory(updatedInventory);
      }

    } catch (err) {
      console.error("Error updating PO status:", err);
      alert("Failed to update order status.");
      fetchData();
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState, icon: any, label: string }) => (
    <button
      onClick={() => { setActiveView(view); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center space-x-3 px-6 py-4 transition-colors ${
        activeView === view 
          ? 'bg-blue-900 border-l-4 border-secondary text-white' 
          : 'text-blue-200 hover:bg-blue-800 hover:text-white'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  // 1. Initial Loading State
  if (authLoading) {
      return (
          <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center text-primary">
              <Loader2 className="w-12 h-12 animate-spin mb-4" />
              <h2 className="text-xl font-bold">Raha Soldi System</h2>
              <p className="text-slate-500 mt-2">Checking secure session...</p>
          </div>
      );
  }

  // 2. Auth Guard
  if (!session) {
    return <Auth />;
  }

  // Extract Role
  // In a real app we might fetch this from a 'profiles' table, but for this prototype we rely on metadata
  const userRole = (session.user.user_metadata?.role as UserRole) || 'cashier';

  // 3. Main Application
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 bg-primary text-white fixed h-full shadow-xl z-20">
        <div className="p-8">
          <h1 className="text-2xl font-bold tracking-tight text-white">Raha Soldi <span className="text-secondary">Ent.</span></h1>
          <p className="text-xs text-blue-300 mt-1 uppercase tracking-wider">Inventory System</p>
        </div>
        <nav className="flex-1 mt-6 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {/* Admin Only Links */}
          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={DollarSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}
        </nav>
        <div className="p-6 border-t border-blue-800">
             <div className="mb-4">
                 <div className="flex items-center space-x-2 mb-1">
                   <Shield className="w-3 h-3 text-secondary" />
                   <p className="text-xs text-blue-300 uppercase">{userRole}</p>
                 </div>
                 <p className="text-sm font-medium truncate" title={session.user.email}>{session.user.email}</p>
             </div>
            <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 hover:bg-blue-800 text-white py-2 rounded-lg transition-colors text-sm"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
            <div className={`mt-4 flex items-center justify-center text-xs px-3 py-2 rounded-lg ${isOnline ? 'bg-blue-800 text-blue-200' : 'bg-red-800 text-red-100'}`}>
                {isOnline ? <Wifi className="w-3 h-3 mr-2" /> : <WifiOff className="w-3 h-3 mr-2" />}
                {isOnline ? 'Online' : 'Offline Mode'}
            </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="lg:hidden fixed top-0 w-full bg-primary text-white z-30 flex items-center justify-between p-4 shadow-md">
        <h1 className="text-lg font-bold">Raha Soldi Ent.</h1>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 bg-primary z-20 pt-20 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={DollarSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}

          <div className="p-4 border-t border-blue-800 mt-4">
             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 text-white py-3 rounded-lg"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 lg:ml-64 p-4 lg:p-8 pt-20 lg:pt-8 transition-all duration-300">
        <div className="max-w-7xl mx-auto">
          <header className="mb-8 flex justify-between items-end">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">
                {activeView === 'dashboard' && 'Business Overview'}
                {activeView === 'inventory' && 'Inventory Management'}
                {activeView === 'pos' && 'New Sale'}
                {activeView === 'history' && 'Transaction History'}
                {activeView === 'expenses' && 'Expense Management'}
                {activeView === 'financials' && 'Financial Health'}
                {activeView === 'insights' && 'Business Intelligence'}
                {activeView === 'purchases' && 'Supplier Purchase Orders'}
              </h2>
              <p className="text-slate-500 text-sm mt-1">
                {activeView === 'dashboard' && 'Welcome back.'}
                {activeView === 'inventory' && 'Manage your stock and pricing.'}
                {activeView === 'pos' && 'Process transactions quickly.'}
                {activeView === 'history' && 'Review past sales and performance.'}
                {activeView === 'expenses' && 'Track operational costs.'}
                {activeView === 'financials' && 'Analyze Profit & Loss and Balance Sheet.'}
                {activeView === 'insights' && 'AI-powered recommendations.'}
                {activeView === 'purchases' && 'Create orders and restock inventory.'}
              </p>
            </div>
            <div className="text-right hidden sm:block">
               <div className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>
            </div>
          </header>

          <div className="fade-in">
             {loading ? (
                 <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                     <Loader2 className="w-10 h-10 animate-spin mb-4" />
                     <p>Loading data...</p>
                 </div>
             ) : (
                <>
                    {activeView === 'dashboard' && <Dashboard inventory={inventory} sales={sales} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'inventory' && <InventoryManager inventory={inventory} onAdd={handleAddItem} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'pos' && <SalesTerminal inventory={inventory} onCompleteSale={handleCompleteSale} currencySymbol="GH₵" />}
                    {activeView === 'history' && <SalesHistory sales={sales} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'expenses' && <ExpensesManager expenses={expenses} onAdd={handleAddExpense} onDelete={handleDeleteExpense} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'financials' && <FinancialReport inventory={inventory} sales={sales} expenses={expenses} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'insights' && <AIInsights inventory={inventory} sales={sales} />}
                    {userRole === 'admin' && activeView === 'purchases' && (
                    <PurchaseOrdersManager 
                        inventory={inventory} 
                        purchaseOrders={purchaseOrders} 
                        onCreateOrder={handleCreatePO} 
                        onUpdateStatus={handleUpdatePOStatus} 
                        currencySymbol="GH₵" 
                    />
                    )}
                </>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { InventoryItem, SaleItem } from '../types';
import { ShoppingCart, Plus, Trash2, CheckCircle, Search, Tag } from 'lucide-react';

interface SalesTerminalProps {
  inventory: InventoryItem[];
  onCompleteSale: (items: SaleItem[]) => void;
  currencySymbol: string;
}

export const SalesTerminal: React.FC<SalesTerminalProps> = ({ inventory, onCompleteSale, currencySymbol }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<InventoryItem | null>(null);
  const [qtyInput, setQtyInput] = useState<number>(1);
  const [successMsg, setSuccessMsg] = useState('');

  // Auto-clear success message
  useEffect(() => {
    if (successMsg) {
      const timer = setTimeout(() => setSuccessMsg(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [successMsg]);

  const filteredInventory = inventory.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const addToCart = () => {
    if (!selectedProduct) return;

    if (qtyInput <= 0) {
      alert("Quantity must be greater than 0");
      return;
    }

    if (qtyInput > selectedProduct.quantity) {
      alert(`Not enough stock. Only ${selectedProduct.quantity} available.`);
      return;
    }

    const existingItemIndex = cart.findIndex(item => item.itemId === selectedProduct.id);

    if (existingItemIndex > -1) {
        // Check if total new quantity exceeds stock
        if (cart[existingItemIndex].quantity + qtyInput > selectedProduct.quantity) {
             alert(`Cannot add more. Total in cart would exceed stock (${selectedProduct.quantity}).`);
             return;
        }

        const newCart = [...cart];
        newCart[existingItemIndex].quantity += qtyInput;
        setCart(newCart);
    } else {
        const newItem: SaleItem = {
            itemId: selectedProduct.id,
            name: selectedProduct.name,
            quantity: qtyInput,
            priceAtSale: selectedProduct.salesPrice,
            costAtSale: selectedProduct.costPrice,
            discount: 0
        };
        setCart([...cart, newItem]);
    }

    // Reset selection
    setSelectedProduct(null);
    setQtyInput(1);
    setSearchTerm('');
  };

  const removeFromCart = (index: number) => {
    const newCart = [...cart];
    newCart.splice(index, 1);
    setCart(newCart);
  };

  const updateDiscount = (index: number, discount: number) => {
    const newCart = [...cart];
    const item = newCart[index];
    const maxDiscount = item.quantity * item.priceAtSale;

    // Validate discount is positive and doesn't exceed total price
    if (discount < 0) discount = 0;
    if (discount > maxDiscount) discount = maxDiscount;

    newCart[index].discount = discount;
    setCart(newCart);
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;
    onCompleteSale(cart);
    setCart([]);
    setSuccessMsg('Sale recorded successfully!');
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.quantity * item.priceAtSale) - (item.discount || 0), 0);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 h-[calc(100vh-140px)]">
      {/* Left: Product Selection */}
      <div className="lg:col-span-2 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="p-4 border-b border-slate-100 bg-slate-50">
          <div className="relative">
             <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="h-5 w-5 text-slate-400" />
              </div>
            <input
              type="text"
              className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary transition duration-150 ease-in-out"
              placeholder="Search product to add..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {filteredInventory.map(item => (
              <div 
                key={item.id}
                onClick={() => setSelectedProduct(item)}
                className={`cursor-pointer p-4 rounded-xl border transition-all ${
                  selectedProduct?.id === item.id 
                    ? 'border-primary ring-2 ring-primary ring-opacity-50 bg-indigo-50' 
                    : 'border-slate-200 hover:border-primary hover:shadow-md bg-white'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                   <div className="font-bold text-slate-800 truncate">{item.name}</div>
                   <div className={`text-xs font-bold px-2 py-1 rounded-full ${item.quantity > item.lowStockThreshold ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                     Qty: {item.quantity}
                   </div>
                </div>
                <div className="text-sm text-slate-500 mb-1">{item.category}</div>
                <div className="text-lg font-bold text-primary">{currencySymbol}{item.salesPrice.toFixed(2)}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Selected Product Action Area */}
        <div className="p-4 bg-slate-50 border-t border-slate-200">
           {selectedProduct ? (
             <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
               <div className="flex items-center gap-4 w-full sm:w-auto">
                 <span className="font-medium text-slate-700 hidden sm:inline">Add {selectedProduct.name}:</span>
                 <div className="flex items-center border border-slate-300 rounded-lg bg-white">
                   <button 
                    onClick={() => setQtyInput(Math.max(1, qtyInput - 1))}
                    className="px-3 py-2 text-slate-600 hover:bg-slate-100 rounded-l-lg border-r border-slate-300"
                   >-</button>
                   <input 
                    type="number" 
                    className="w-16 text-center py-2 focus:outline-none"
                    value={qtyInput}
                    onChange={(e) => setQtyInput(parseInt(e.target.value) || 0)}
                   />
                    <button 
                    onClick={() => setQtyInput(qtyInput + 1)}
                    className="px-3 py-2 text-slate-600 hover:bg-slate-100 rounded-r-lg border-l border-slate-300"
                   >+</button>
                 </div>
               </div>
               <button 
                onClick={addToCart}
                disabled={itemInCartTotal(cart, selectedProduct.id) + qtyInput > selectedProduct.quantity}
                className="w-full sm:w-auto px-6 py-3 bg-primary text-white font-medium rounded-lg hover:bg-blue-800 shadow-md transition-colors flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
               >
                 <Plus className="w-5 h-5 mr-2" />
                 Add to Cart
               </button>
             </div>
           ) : (
             <div className="text-center text-slate-500 py-3">Select a product above to start adding to cart</div>
           )}
        </div>
      </div>

      {/* Right: Cart & Checkout */}
      <div className="bg-white rounded-xl shadow-xl border border-slate-200 flex flex-col h-full">
        <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center">
          <h2 className="font-bold text-slate-800 flex items-center">
            <ShoppingCart className="w-5 h-5 mr-2" />
            Current Sale
          </h2>
          <span className="bg-primary text-white text-xs font-bold px-2 py-1 rounded-full">{cart.length} items</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400">
              <ShoppingCart className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={index} className="p-3 bg-slate-50 rounded-lg border border-slate-100">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <div className="font-medium text-slate-800">{item.name}</div>
                    <div className="text-sm text-slate-500">{item.quantity} x {currencySymbol}{item.priceAtSale.toFixed(2)}</div>
                  </div>
                  <button onClick={() => removeFromCart(index)} className="text-red-400 hover:text-red-600 transition-colors">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>

                <div className="flex items-center justify-between mt-2 pt-2 border-t border-slate-200">
                    {/* Discount Input */}
                    <div className="flex items-center space-x-2">
                         <Tag className="w-3 h-3 text-slate-400" />
                         <input 
                            type="number"
                            min="0"
                            placeholder="Discount"
                            className="w-20 text-xs p-1 border border-slate-300 rounded focus:ring-1 focus:ring-primary focus:outline-none"
                            value={item.discount || ''}
                            onChange={(e) => updateDiscount(index, parseFloat(e.target.value) || 0)}
                         />
                         {item.discount ? <span className="text-xs text-red-500">-{currencySymbol}{item.discount}</span> : null}
                    </div>

                    <div className="font-bold text-slate-800">
                        {currencySymbol}{((item.quantity * item.priceAtSale) - (item.discount || 0)).toFixed(2)}
                    </div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-200">
          <div className="flex justify-between items-center mb-6">
            <span className="text-slate-500 font-medium">Total Amount</span>
            <span className="text-3xl font-bold text-slate-900">{currencySymbol}{cartTotal.toFixed(2)}</span>
          </div>

          <button 
            onClick={handleCheckout}
            disabled={cart.length === 0}
            className="w-full py-4 bg-green-600 text-white font-bold rounded-xl shadow-lg hover:bg-green-700 transition-transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
          >
            <CheckCircle className="w-6 h-6 mr-2" />
            Complete Sale
          </button>

          {successMsg && (
             <div className="mt-4 p-3 bg-green-100 text-green-800 text-center rounded-lg text-sm font-medium animate-pulse">
               {successMsg}
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Helper to calculate total quantity of an item already in cart
const itemInCartTotal = (cart: SaleItem[], itemId: string): number => {
    return cart.filter(i => i.itemId === itemId).reduce((acc, i) => acc + i.quantity, 0);
};

import React, { useState, useMemo } from 'react';
import { SaleRecord } from '../types';
import { Search, Eye, FileText, X, ArrowUpCircle } from 'lucide-react';

interface SalesHistoryProps {
  sales: SaleRecord[];
  currencySymbol: string;
}

export const SalesHistory: React.FC<SalesHistoryProps> = ({ sales, currencySymbol }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedSale, setSelectedSale] = useState<SaleRecord | null>(null);

  const filteredSales = useMemo(() => {
    return sales.filter(sale => {
      // Search term filter (check if any item name matches)
      const matchesSearch = searchTerm === '' || sale.items.some(item => 
        item.name.toLowerCase().includes(searchTerm.toLowerCase())
      );

      // Date range filter
      let matchesDate = true;
      if (startDate) {
        // Reset time to start of day for accurate comparison
        const start = new Date(startDate);
        start.setHours(0, 0, 0, 0);
        matchesDate = matchesDate && new Date(sale.timestamp) >= start;
      }
      if (endDate) {
        // Set end date to end of day
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        matchesDate = matchesDate && new Date(sale.timestamp) <= end;
      }

      return matchesSearch && matchesDate;
    }).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()); // Newest first
  }, [sales, searchTerm, startDate, endDate]);

  const totalRevenue = filteredSales.reduce((acc, sale) => acc + sale.totalAmount, 0);
  const totalProfit = filteredSales.reduce((acc, sale) => acc + sale.totalProfit, 0);

  // Helper to format date
  const formatDate = (isoString: string) => {
    return new Date(isoString).toLocaleString('en-GB', {
      day: '2-digit',
      month: 'short',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {/* Filters & Stats Header */}
      <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
        <div className="lg:col-span-3 bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col md:flex-row gap-4 items-end md:items-center">
            <div className="w-full md:w-1/3 relative">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search className="h-4 w-4 text-slate-400" />
                </div>
                <input
                    type="text"
                    className="block w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-primary focus:border-primary"
                    placeholder="Search item name..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>

            <div className="flex items-center gap-2 w-full md:w-auto">
                <div className="relative flex-1">
                    <label className="text-xs text-slate-500 mb-1 block">Start Date</label>
                    <input
                        type="date"
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-primary focus:border-primary"
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                    />
                </div>
                <div className="relative flex-1">
                    <label className="text-xs text-slate-500 mb-1 block">End Date</label>
                    <input
                        type="date"
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-primary focus:border-primary"
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                    />
                </div>
            </div>

            {(searchTerm || startDate || endDate) && (
                <button 
                    onClick={() => { setSearchTerm(''); setStartDate(''); setEndDate(''); }}
                    className="text-sm text-red-500 hover:text-red-700 font-medium whitespace-nowrap mb-1"
                >
                    Clear Filters
                </button>
            )}
        </div>

        <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col justify-center">
            <div className="text-xs text-slate-500 uppercase font-semibold">Revenue (Filtered)</div>
            <div className="text-xl font-bold text-slate-800">{currencySymbol}{totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}</div>
             <div className="text-xs text-green-600 flex items-center mt-1">
                <ArrowUpCircle className="w-3 h-3 mr-1" />
                Profit: {currencySymbol}{totalProfit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
            </div>
        </div>
      </div>

      {/* Sales Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Date & Time</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Items Summary</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Total</th>
                <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
                {filteredSales.map((sale) => (
                    <tr key={sale.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                            {formatDate(sale.timestamp)}
                        </td>
                        <td className="px-6 py-4 text-sm text-slate-800">
                            <div className="font-medium">{sale.items[0]?.name} {sale.items.length > 1 && `+ ${sale.items.length - 1} others`}</div>
                            <div className="text-xs text-slate-500">{sale.items.reduce((sum, i) => sum + i.quantity, 0)} items total</div>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-800">
                            {currencySymbol}{sale.totalAmount.toFixed(2)}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm">
                            <button 
                                onClick={() => setSelectedSale(sale)}
                                className="text-primary hover:text-blue-800 inline-flex items-center font-medium"
                            >
                                <Eye className="w-4 h-4 mr-1" /> View
                            </button>
                        </td>
                    </tr>
                ))}
                {filteredSales.length === 0 && (
                    <tr>
                        <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                            No sales records found matching your filters.
                        </td>
                    </tr>
                )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Detail Modal */}
      {selectedSale && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden animate-fade-in">
                <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center">
                        <FileText className="w-5 h-5 mr-2 text-primary" />
                        Sale Details
                    </h3>
                    <button onClick={() => setSelectedSale(null)} className="text-slate-400 hover:text-slate-600">
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-6">
                    <div className="flex justify-between items-start mb-6 text-sm">
                        <div>
                            <span className="text-slate-500 block">Date</span>
                            <span className="font-medium text-slate-800">{formatDate(selectedSale.timestamp)}</span>
                        </div>
                        <div className="text-right">
                             <span className="text-slate-500 block">Transaction ID</span>
                             <span className="font-mono text-xs text-slate-600 bg-slate-100 px-2 py-1 rounded">{selectedSale.id.slice(-8)}</span>
                        </div>
                    </div>

                    <div className="border border-slate-200 rounded-lg overflow-hidden mb-6">
                        <table className="min-w-full divide-y divide-slate-200">
                            <thead className="bg-slate-50">
                                <tr>
                                    <th className="px-4 py-2 text-left text-xs font-bold text-slate-500">Item</th>
                                    <th className="px-4 py-2 text-right text-xs font-bold text-slate-500">Qty</th>
                                    <th className="px-4 py-2 text-right text-xs font-bold text-slate-500">Discount</th>
                                    <th className="px-4 py-2 text-right text-xs font-bold text-slate-500">Total</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-200 bg-white">
                                {selectedSale.items.map((item, idx) => (
                                    <tr key={idx}>
                                        <td className="px-4 py-2 text-sm text-slate-800">{item.name}</td>
                                        <td className="px-4 py-2 text-sm text-slate-600 text-right">{item.quantity}</td>
                                        <td className="px-4 py-2 text-sm text-red-500 text-right">
                                            {item.discount ? `-${currencySymbol}${item.discount}` : '-'}
                                        </td>
                                        <td className="px-4 py-2 text-sm text-slate-800 font-medium text-right">
                                            {currencySymbol}{((item.quantity * item.priceAtSale) - (item.discount || 0)).toFixed(2)}
                                        </td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>

                    <div className="space-y-2 border-t border-slate-100 pt-4">
                        <div className="flex justify-between items-center">
                            <span className="text-slate-500 text-sm">Total Amount</span>
                            <span className="text-xl font-bold text-slate-800">{currencySymbol}{selectedSale.totalAmount.toFixed(2)}</span>
                        </div>
                         <div className="flex justify-between items-center text-sm">
                            <span className="text-slate-500">Net Profit</span>
                            <span className="text-green-600 font-medium">{currencySymbol}{selectedSale.totalProfit.toFixed(2)}</span>
                        </div>
                    </div>
                </div>

                <div className="bg-slate-50 px-6 py-4 flex justify-end">
                    <button 
                        onClick={() => setSelectedSale(null)}
                        className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-50 text-sm font-medium shadow-sm transition-colors"
                    >
                        Close
                    </button>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { ExpenseRecord } from '../types';
import { Plus, Search, DollarSign, Calendar, Tag } from 'lucide-react';

interface ExpensesManagerProps {
  expenses: ExpenseRecord[];
  onAdd: (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => void;
  currencySymbol: string;
}

export const ExpensesManager: React.FC<ExpensesManagerProps> = ({ expenses, onAdd, currencySymbol }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [isFormOpen, setIsFormOpen] = useState(false);

  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    category: '',
    date: new Date().toISOString().split('T')[0]
  });

  const categories = ['Rent', 'Utilities', 'Salaries', 'Supplies', 'Maintenance', 'Marketing', 'Other'];

  const filteredExpenses = useMemo(() => {
    return expenses.filter(exp => 
      exp.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
      exp.category.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [expenses, searchTerm]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.description || !formData.amount || !formData.category) return;

    onAdd({
      description: formData.description,
      amount: parseFloat(formData.amount),
      category: formData.category,
      date: formData.date
    });

    setFormData({
      description: '',
      amount: '',
      category: '',
      date: new Date().toISOString().split('T')[0]
    });
    setIsFormOpen(false);
  };

  const totalExpenses = filteredExpenses.reduce((acc, exp) => acc + exp.amount, 0);

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Summary Card */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between md:col-span-1">
          <div>
            <p className="text-sm font-medium text-slate-500">Total Recorded Expenses</p>
            <h3 className="text-2xl font-bold text-slate-800 mt-1">{currencySymbol}{totalExpenses.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3>
          </div>
          <div className="p-3 bg-red-100 rounded-lg">
            <DollarSign className="w-6 h-6 text-red-600" />
          </div>
        </div>

        {/* Action Bar */}
        <div className="md:col-span-2 flex flex-col md:flex-row gap-4 items-center justify-end">
            <div className="relative w-full md:w-64">
                <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                    <Search className="h-5 w-5 text-slate-400" />
                </div>
                <input
                    type="text"
                    className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg bg-white focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary transition duration-150 ease-in-out"
                    placeholder="Search expenses..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                />
            </div>
            <button
                onClick={() => setIsFormOpen(!isFormOpen)}
                className="w-full md:w-auto flex items-center justify-center px-6 py-3 border border-transparent text-sm font-medium rounded-lg text-white bg-primary hover:bg-blue-800 focus:outline-none shadow-md transition-all"
            >
                {isFormOpen ? 'Close Form' : 'Record New Expense'}
                {!isFormOpen && <Plus className="h-5 w-5 ml-2" />}
            </button>
        </div>
      </div>

      {/* Add Expense Form */}
      {isFormOpen && (
        <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 animate-fade-in">
            <h3 className="text-lg font-bold text-slate-800 mb-4">New Expense Entry</h3>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
                <div className="lg:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <Tag className="h-4 w-4 text-slate-400" />
                        </div>
                        <input
                            type="text"
                            required
                            className="block w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            placeholder="e.g. Shop Rent for March"
                            value={formData.description}
                            onChange={(e) => setFormData({...formData, description: e.target.value})}
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Amount</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <span className="text-slate-400 font-bold">{currencySymbol}</span>
                        </div>
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            required
                            className="block w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            value={formData.amount}
                            onChange={(e) => setFormData({...formData, amount: e.target.value})}
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Category</label>
                    <select
                        required
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                        value={formData.category}
                        onChange={(e) => setFormData({...formData, category: e.target.value})}
                    >
                        <option value="">Select Category</option>
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                    <div className="relative">
                        <input
                            type="date"
                            required
                            className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            value={formData.date}
                            onChange={(e) => setFormData({...formData, date: e.target.value})}
                        />
                    </div>
                </div>
                <div className="lg:col-span-5 flex justify-end mt-2">
                    <button type="submit" className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700 shadow-sm">
                        Save Record
                    </button>
                </div>
            </form>
        </div>
      )}

      {/* Expenses Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
                <tr>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Date</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Description</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Category</th>
                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Amount</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
                {filteredExpenses.map((expense) => (
                    <tr key={expense.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                            {new Date(expense.date).toLocaleDateString()}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-800">
                            {expense.description}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <span className="px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full bg-slate-100 text-slate-600 border border-slate-200">
                                {expense.category}
                            </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-bold text-red-600">
                            -{currencySymbol}{expense.amount.toFixed(2)}
                        </td>
                    </tr>
                ))}
                {filteredExpenses.length === 0 && (
                    <tr>
                        <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                            No expenses found. Start tracking your business spending above.
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, ShoppingCart, BrainCircuit, Menu, X, History, Wifi, WifiOff, Loader2, DollarSign, PieChart, Truck, LogOut, Shield } from 'lucide-react';
import { InventoryManager } from './components/InventoryManager';
import { SalesTerminal } from './components/SalesTerminal';
import { Dashboard } from './components/Dashboard';
import { AIInsights } from './components/AIInsights';
import { SalesHistory } from './components/SalesHistory';
import { ExpensesManager } from './components/ExpensesManager';
import { FinancialReport } from './components/FinancialReport';
import { PurchaseOrdersManager } from './components/PurchaseOrdersManager';
import { Auth } from './components/Auth';
import { InventoryItem, SaleRecord, SaleItem, ViewState, ExpenseRecord, PurchaseOrder, UserRole } from './types';
import { supabase } from './services/supabaseClient';
import { Session } from '@supabase/supabase-js';

const App: React.FC = () => {
  // Auth State
  const [session, setSession] = useState<Session | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // State Management
  const [activeView, setActiveView] = useState<ViewState>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Data State
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [expenses, setExpenses] = useState<ExpenseRecord[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);

  // Connectivity Listeners
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Auth Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      // Reset view to dashboard on login
      if (session) setActiveView('dashboard');
    });

    return () => subscription.unsubscribe();
  }, []);

  // Fetch Data from Supabase
  const fetchData = async () => {
    if (!session) return; // Don't fetch if not logged in

    setLoading(true);
    try {
      // Fetch Inventory
      const { data: invData, error: invError } = await supabase
        .from('inventory')
        .select('*');

      if (invError) throw invError;
      if (invData) setInventory(invData);

      // Fetch Sales
      const { data: salesData, error: salesError } = await supabase
        .from('sales')
        .select('*')
        .order('timestamp', { ascending: false });

      if (salesError) throw salesError;
      if (salesData) setSales(salesData);

      // Fetch Expenses
      const { data: expData, error: expError } = await supabase
        .from('expenses')
        .select('*')
        .order('date', { ascending: false });

      if (expError) throw expError;
      if (expData) setExpenses(expData);

      // Fetch Purchase Orders
      const { data: poData, error: poError } = await supabase
        .from('purchase_orders')
        .select('*')
        .order('date', { ascending: false });

      if (poError) {
         console.warn("Could not fetch purchase orders. Table might not exist yet.");
      } else if (poData) {
         setPurchaseOrders(poData);
      }

    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch data when session becomes available
  useEffect(() => {
    if (session) {
      fetchData();
    }
  }, [session]);

  // Handlers
  const handleAddItem = async (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const newItem: InventoryItem = {
      ...item,
      id: crypto.randomUUID(), // Generate UUID
      lastUpdated: new Date().toISOString()
    };

    // Optimistic Update
    setInventory(prev => [...prev, newItem]);

    try {
      const { error } = await supabase.from('inventory').insert([newItem]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding item:", err);
      alert("Failed to save item to database.");
      fetchData(); // Revert on error
    }
  };

  const handleUpdateItem = async (id: string, updates: Partial<InventoryItem>) => {
    const updatedTimestamp = new Date().toISOString();
    const finalUpdates = { ...updates, lastUpdated: updatedTimestamp };

    // Optimistic Update
    setInventory(prev => prev.map(item => item.id === id ? { ...item, ...finalUpdates } : item));

    try {
      const { error } = await supabase
        .from('inventory')
        .update(finalUpdates)
        .eq('id', id);

      if (error) throw error;
    } catch (err) {
      console.error("Error updating item:", err);
      alert("Failed to update item in database.");
      fetchData(); // Revert
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      // Optimistic Update
      setInventory(prev => prev.filter(item => item.id !== id));

      try {
        const { error } = await supabase.from('inventory').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting item:", err);
        alert("Failed to delete item from database.");
        fetchData(); // Revert
      }
    }
  };

  const handleCompleteSale = async (items: SaleItem[]) => {
    // Calculate total amount considering discounts
    const totalAmount = items.reduce((sum, item) => 
      sum + ((item.quantity * item.priceAtSale) - (item.discount || 0)), 0
    );

    // Total cost is purely COGS
    const totalCost = items.reduce((sum, item) => sum + (item.quantity * item.costAtSale), 0);

    const newSale: SaleRecord = {
      id: crypto.randomUUID(),
      items,
      totalAmount,
      totalProfit: totalAmount - totalCost,
      timestamp: new Date().toISOString()
    };

    // Optimistic Update for UI
    const newInventory = [...inventory];
    items.forEach(saleItem => {
      const productIndex = newInventory.findIndex(p => p.id === saleItem.itemId);
      if (productIndex > -1) {
        newInventory[productIndex] = {
            ...newInventory[productIndex],
            quantity: newInventory[productIndex].quantity - saleItem.quantity,
            lastUpdated: new Date().toISOString()
        };
      }
    });

    setInventory(newInventory);
    setSales(prev => [newSale, ...prev]);

    try {
        // 1. Record Sale
        const { error: saleError } = await supabase.from('sales').insert([newSale]);
        if (saleError) throw saleError;

        // 2. Update Inventory Quantities
        for (const item of items) {
             const currentItem = inventory.find(i => i.id === item.itemId);
             if (currentItem) {
                 const newQty = currentItem.quantity - item.quantity;
                 await supabase
                    .from('inventory')
                    .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
                    .eq('id', item.itemId);
             }
        }
    } catch (err) {
        console.error("Error processing sale:", err);
        alert("Error saving sale to database. Please check connection.");
        fetchData(); // Revert to server state
    }
  };

  const handleAddExpense = async (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => {
    const newExpense: ExpenseRecord = {
      ...expense,
      id: crypto.randomUUID(),
      recordedAt: new Date().toISOString()
    };

    setExpenses(prev => [newExpense, ...prev]);

    try {
      const { error } = await supabase.from('expenses').insert([newExpense]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding expense:", err);
      alert("Failed to save expense.");
      fetchData();
    }
  };

  const handleDeleteExpense = async (id: string) => {
    if (window.confirm('Delete this expense record?')) {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting expense:", err);
        fetchData();
      }
    }
  };

  const handleCreatePO = async (po: Omit<PurchaseOrder, 'id'>) => {
    const newPO: PurchaseOrder = {
      ...po,
      id: crypto.randomUUID(),
    };

    setPurchaseOrders(prev => [newPO, ...prev]);

    try {
      const { error } = await supabase.from('purchase_orders').insert([newPO]);
      if (error) throw error;
    } catch (err) {
      console.error("Error creating PO:", err);
      alert("Failed to save Purchase Order.");
      fetchData();
    }
  };

  const handleUpdatePOStatus = async (id: string, status: 'received' | 'cancelled') => {
    const po = purchaseOrders.find(p => p.id === id);
    if (!po) return;

    // Optimistic Update
    setPurchaseOrders(prev => prev.map(p => p.id === id ? { ...p, status } : p));

    try {
      const { error } = await supabase
        .from('purchase_orders')
        .update({ status })
        .eq('id', id);

      if (error) throw error;

      // Logic: If marking as RECEIVED, update inventory stock
      if (status === 'received' && po.status !== 'received') {
        const updatedInventory = [...inventory];

        for (const item of po.items) {
           const invIndex = updatedInventory.findIndex(i => i.id === item.itemId);
           if (invIndex > -1) {
             const currentInv = updatedInventory[invIndex];
             const newQty = currentInv.quantity + item.quantity;

             // Update local state
             updatedInventory[invIndex] = {
               ...currentInv,
               quantity: newQty,
               lastUpdated: new Date().toISOString()
             };

             // Update Database
             await supabase
               .from('inventory')
               .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
               .eq('id', item.itemId);
           }
        }
        setInventory(updatedInventory);
      }

    } catch (err) {
      console.error("Error updating PO status:", err);
      alert("Failed to update order status.");
      fetchData();
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState, icon: any, label: string }) => (
    <button
      onClick={() => { setActiveView(view); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center space-x-3 px-6 py-4 transition-colors ${
        activeView === view 
          ? 'bg-blue-900 border-l-4 border-secondary text-white' 
          : 'text-blue-200 hover:bg-blue-800 hover:text-white'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  // 1. Initial Loading State
  if (authLoading) {
      return (
          <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center text-primary">
              <Loader2 className="w-12 h-12 animate-spin mb-4" />
              <h2 className="text-xl font-bold">Raha Soldi System</h2>
              <p className="text-slate-500 mt-2">Checking secure session...</p>
          </div>
      );
  }

  // 2. Auth Guard
  if (!session) {
    return <Auth />;
  }

  // Extract Role
  // In a real app we might fetch this from a 'profiles' table, but for this prototype we rely on metadata
  const userRole = (session.user.user_metadata?.role as UserRole) || 'cashier';

  // 3. Main Application
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 bg-primary text-white fixed h-full shadow-xl z-20">
        <div className="p-8">
          <h1 className="text-2xl font-bold tracking-tight text-white">Raha Soldi <span className="text-secondary">Ent.</span></h1>
          <p className="text-xs text-blue-300 mt-1 uppercase tracking-wider">Inventory System</p>
        </div>
        <nav className="flex-1 mt-6 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {/* Admin Only Links */}
          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={DollarSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}
        </nav>
        <div className="p-6 border-t border-blue-800">
             <div className="mb-4">
                 <div className="flex items-center space-x-2 mb-1">
                   <Shield className="w-3 h-3 text-secondary" />
                   <p className="text-xs text-blue-300 uppercase">{userRole}</p>
                 </div>
                 <p className="text-sm font-medium truncate" title={session.user.email}>{session.user.email}</p>
             </div>
            <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 hover:bg-blue-800 text-white py-2 rounded-lg transition-colors text-sm"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
            <div className={`mt-4 flex items-center justify-center text-xs px-3 py-2 rounded-lg ${isOnline ? 'bg-blue-800 text-blue-200' : 'bg-red-800 text-red-100'}`}>
                {isOnline ? <Wifi className="w-3 h-3 mr-2" /> : <WifiOff className="w-3 h-3 mr-2" />}
                {isOnline ? 'Online' : 'Offline Mode'}
            </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="lg:hidden fixed top-0 w-full bg-primary text-white z-30 flex items-center justify-between p-4 shadow-md">
        <h1 className="text-lg font-bold">Raha Soldi Ent.</h1>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 bg-primary z-20 pt-20 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={DollarSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}

          <div className="p-4 border-t border-blue-800 mt-4">
             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 text-white py-3 rounded-lg"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 lg:ml-64 p-4 lg:p-8 pt-20 lg:pt-8 transition-all duration-300">
        <div className="max-w-7xl mx-auto">
          <header className="mb-8 flex justify-between items-end">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">
                {activeView === 'dashboard' && 'Business Overview'}
                {activeView === 'inventory' && 'Inventory Management'}
                {activeView === 'pos' && 'New Sale'}
                {activeView === 'history' && 'Transaction History'}
                {activeView === 'expenses' && 'Expense Management'}
                {activeView === 'financials' && 'Financial Health'}
                {activeView === 'insights' && 'Business Intelligence'}
                {activeView === 'purchases' && 'Supplier Purchase Orders'}
              </h2>
              <p className="text-slate-500 text-sm mt-1">
                {activeView === 'dashboard' && 'Welcome back.'}
                {activeView === 'inventory' && 'Manage your stock and pricing.'}
                {activeView === 'pos' && 'Process transactions quickly.'}
                {activeView === 'history' && 'Review past sales and performance.'}
                {activeView === 'expenses' && 'Track operational costs.'}
                {activeView === 'financials' && 'Analyze Profit & Loss and Balance Sheet.'}
                {activeView === 'insights' && 'AI-powered recommendations.'}
                {activeView === 'purchases' && 'Create orders and restock inventory.'}
              </p>
            </div>
            <div className="text-right hidden sm:block">
               <div className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>
            </div>
          </header>

          <div className="fade-in">
             {loading ? (
                 <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                     <Loader2 className="w-10 h-10 animate-spin mb-4" />
                     <p>Loading data...</p>
                 </div>
             ) : (
                <>
                    {activeView === 'dashboard' && <Dashboard inventory={inventory} sales={sales} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'inventory' && <InventoryManager inventory={inventory} onAdd={handleAddItem} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'pos' && <SalesTerminal inventory={inventory} onCompleteSale={handleCompleteSale} currencySymbol="GH₵" />}
                    {activeView === 'history' && <SalesHistory sales={sales} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'expenses' && <ExpensesManager expenses={expenses} onAdd={handleAddExpense} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'financials' && <FinancialReport inventory={inventory} sales={sales} expenses={expenses} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'insights' && <AIInsights inventory={inventory} sales={sales} />}
                    {userRole === 'admin' && activeView === 'purchases' && (
                    <PurchaseOrdersManager 
                        inventory={inventory} 
                        purchaseOrders={purchaseOrders} 
                        onCreateOrder={handleCreatePO} 
                        onUpdateStatus={handleUpdatePOStatus} 
                        currencySymbol="GH₵" 
                    />
                    )}
                </>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

