import React, { useMemo } from 'react';
import { InventoryItem, SaleRecord, UserRole } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, LineChart, Line } from 'recharts';
import { Package, TrendingUp, AlertTriangle } from 'lucide-react';

interface DashboardProps {
  inventory: InventoryItem[];
  sales: SaleRecord[];
  currencySymbol: string;
  userRole: UserRole;
}

// Custom Cedi Icon Component
const CediSign = ({ className }: { className?: string }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M16 7a6 6 0 1 0 0 10" />
    <path d="M10 3v18" />
  </svg>
);

export const Dashboard: React.FC<DashboardProps> = ({ inventory, sales, currencySymbol, userRole }) => {

  const metrics = useMemo(() => {
    const totalRevenue = sales.reduce((acc, sale) => acc + sale.totalAmount, 0);
    const totalProfit = sales.reduce((acc, sale) => acc + sale.totalProfit, 0);
    const lowStockCount = inventory.filter(i => i.quantity <= i.lowStockThreshold).length;
    const totalInventoryValue = inventory.reduce((acc, i) => acc + (i.costPrice * i.quantity), 0);
    const potentialSalesValue = inventory.reduce((acc, i) => acc + (i.salesPrice * i.quantity), 0);

    return { totalRevenue, totalProfit, lowStockCount, totalInventoryValue, potentialSalesValue };
  }, [inventory, sales]);

  // Prepare chart data (Last 7 days sales)
  const chartData = useMemo(() => {
    const last7Days = new Array(7).fill(0).map((_, i) => {
      const d = new Date();
      d.setDate(d.getDate() - i);
      return d.toISOString().split('T')[0];
    }).reverse();

    return last7Days.map(date => {
      const daySales = sales.filter(s => s.timestamp.startsWith(date));
      return {
        date: date.substring(5), // MM-DD for Axis label
        fullDate: date, // Full YYYY-MM-DD for tooltip
        sales: daySales.reduce((acc, s) => acc + s.totalAmount, 0),
        profit: daySales.reduce((acc, s) => acc + s.totalProfit, 0)
      };
    });
  }, [sales]);

  // Custom Tooltip Component
  const CustomTooltip = ({ active, payload }: any) => {
    if (active && payload && payload.length) {
      const data = payload[0].payload;
      const dateObj = new Date(data.fullDate);
      const formattedDate = dateObj.toLocaleDateString('en-GB', { 
        weekday: 'long', 
        year: 'numeric', 
        month: 'long', 
        day: 'numeric' 
      });

      return (
        <div className="bg-white p-4 rounded-xl shadow-lg border border-slate-100 min-w-[200px] z-50">
          <p className="text-sm font-bold text-slate-800 mb-3 pb-2 border-b border-slate-100">
            {formattedDate}
          </p>
          <div className="space-y-2">
            <div className="flex justify-between items-center text-sm">
              <span className="text-slate-500">Total Sales:</span>
              <span className="font-bold text-blue-600">
                {currencySymbol}{data.sales.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
              </span>
            </div>
            {userRole === 'admin' && (
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Net Profit:</span>
                <span className="font-bold text-green-600">
                  {currencySymbol}{data.profit.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
                </span>
              </div>
            )}
          </div>
        </div>
      );
    }
    return null;
  };

  const StatCard = ({ title, value, icon: Icon, color, subtext }: any) => (
    <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100 flex items-start justify-between hover:shadow-md transition-shadow">
      <div>
        <p className="text-sm font-medium text-slate-500">{title}</p>
        <h3 className="text-2xl font-bold text-slate-800 mt-1">{value}</h3>
        {subtext && <p className="text-xs text-slate-400 mt-1">{subtext}</p>}
      </div>
      <div className={`p-3 rounded-lg ${color}`}>
        <Icon className="w-6 h-6 text-white" />
      </div>
    </div>
  );

  return (
    <div className="space-y-6 animate-fade-in">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-6">
        <StatCard 
          title="Total Revenue" 
          value={`${currencySymbol}${metrics.totalRevenue.toLocaleString(undefined, { minimumFractionDigits: 2 })}`} 
          icon={CediSign} 
          color="bg-green-500" 
          subtext="Lifetime sales"
        />
        {userRole === 'admin' && (
          <StatCard 
            title="Total Profit" 
            value={`${currencySymbol}${metrics.totalProfit.toLocaleString(undefined, { minimumFractionDigits: 2 })}`} 
            icon={TrendingUp} 
            color="bg-blue-500" 
            subtext="Net earnings"
          />
        )}
        {userRole === 'admin' && (
          <StatCard 
            title="Inventory Cost Value" 
            value={`${currencySymbol}${metrics.totalInventoryValue.toLocaleString(undefined, { minimumFractionDigits: 2 })}`} 
            icon={Package} 
            color="bg-indigo-500" 
            subtext={`Potential: ${currencySymbol}${metrics.potentialSalesValue.toLocaleString()}`}
          />
        )}
        <StatCard 
          title="Low Stock Alerts" 
          value={metrics.lowStockCount} 
          icon={AlertTriangle} 
          color="bg-red-600" 
          subtext="Items below threshold"
        />
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
          <h3 className="text-lg font-bold text-slate-800 mb-4">Sales Overview (Last 7 Days)</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                <XAxis dataKey="date" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} />
                <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} tickFormatter={(value) => `${value}`} />
                <Tooltip 
                  content={<CustomTooltip />}
                  cursor={{ fill: '#f8fafc' }}
                />
                <Bar dataKey="sales" fill="#3b82f6" radius={[4, 4, 0, 0]} name="Sales" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {userRole === 'admin' && (
          <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-100">
            <h3 className="text-lg font-bold text-slate-800 mb-4">Profit Trend</h3>
             <div className="h-64">
              <ResponsiveContainer width="100%" height="100%">
                <LineChart data={chartData}>
                  <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                  <XAxis dataKey="date" stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} />
                  <YAxis stroke="#64748b" fontSize={12} tickLine={false} axisLine={false} />
                  <Tooltip content={<CustomTooltip />} />
                  <Line type="monotone" dataKey="profit" stroke="#10b981" strokeWidth={2} dot={{ r: 4 }} activeDot={{ r: 6 }} name="Profit" />
                </LineChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { ExpenseRecord } from '../types';
import { Plus, Search, Calendar, Tag, Download, Filter, TrendingUp, PieChart as PieIcon } from 'lucide-react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RechartsTooltip, BarChart, Bar, XAxis, YAxis, CartesianGrid, Legend } from 'recharts';

interface ExpensesManagerProps {
  expenses: ExpenseRecord[];
  onAdd: (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => void;
  currencySymbol: string;
}

// Custom Cedi Icon Component
const CediSign = ({ className }: { className?: string }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M16 7a6 6 0 1 0 0 10" />
    <path d="M10 3v18" />
  </svg>
);

export const ExpensesManager: React.FC<ExpensesManagerProps> = ({ expenses, onAdd, currencySymbol }) => {
  const [isFormOpen, setIsFormOpen] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState('');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('All');

  // Form State
  const [formData, setFormData] = useState({
    description: '',
    amount: '',
    category: '',
    date: new Date().toISOString().split('T')[0]
  });

  const categories = ['Rent', 'Utilities', 'Salaries', 'Supplies', 'Maintenance', 'Marketing', 'Other'];
  const COLORS = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#6366f1'];

  // 1. Filter Logic
  const filteredExpenses = useMemo(() => {
    return expenses.filter(exp => {
      const matchesSearch = exp.description.toLowerCase().includes(searchTerm.toLowerCase()) || 
                            exp.category.toLowerCase().includes(searchTerm.toLowerCase());

      const matchesCategory = selectedCategory === 'All' || exp.category === selectedCategory;

      let matchesDate = true;
      if (startDate) {
         matchesDate = matchesDate && new Date(exp.date) >= new Date(startDate);
      }
      if (endDate) {
         matchesDate = matchesDate && new Date(exp.date) <= new Date(endDate);
      }

      return matchesSearch && matchesCategory && matchesDate;
    }).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [expenses, searchTerm, startDate, endDate, selectedCategory]);

  // 2. Aggregate Data for Charts
  const categoryData = useMemo(() => {
    const data: Record<string, number> = {};
    filteredExpenses.forEach(exp => {
      data[exp.category] = (data[exp.category] || 0) + exp.amount;
    });
    return Object.keys(data).map(key => ({ name: key, value: data[key] }));
  }, [filteredExpenses]);

  const dailyData = useMemo(() => {
    // Show last 7 entries or grouped by day if too many, simplified here to recent individual expenses for bar chart
    // A better approach for bar chart is aggregating by day
    const data: Record<string, number> = {};
    filteredExpenses.forEach(exp => {
        const dateKey = new Date(exp.date).toLocaleDateString('en-GB', { month: 'short', day: 'numeric' });
        data[dateKey] = (data[dateKey] || 0) + exp.amount;
    });
    // Take last 7 days present in data for cleanliness
    return Object.keys(data).slice(0, 7).map(key => ({ date: key, amount: data[key] }));
  }, [filteredExpenses]);

  // 3. Metrics
  const totalExpenses = filteredExpenses.reduce((acc, exp) => acc + exp.amount, 0);
  const avgExpense = filteredExpenses.length > 0 ? totalExpenses / filteredExpenses.length : 0;
  const topCategory = categoryData.length > 0 ? categoryData.reduce((prev, current) => (prev.value > current.value) ? prev : current).name : 'N/A';

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.description || !formData.amount || !formData.category) return;

    onAdd({
      description: formData.description,
      amount: parseFloat(formData.amount),
      category: formData.category,
      date: formData.date
    });

    setFormData({
      description: '',
      amount: '',
      category: '',
      date: new Date().toISOString().split('T')[0]
    });
    setIsFormOpen(false);
  };

  const handleExportCSV = () => {
    const headers = ['Date', 'Description', 'Category', 'Amount', 'ID'];
    const rows = filteredExpenses.map(e => [
        e.date,
        `"${e.description.replace(/"/g, '""')}"`, // Escape quotes
        e.category,
        e.amount.toFixed(2),
        e.id
    ]);

    const csvContent = [
        headers.join(','),
        ...rows.map(row => row.join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `expenses_report_${new Date().toISOString().split('T')[0]}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="space-y-6 animate-fade-in">

      {/* Top Metrics & Charts Section */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
        {/* Metrics Column */}
        <div className="space-y-4">
             <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-medium text-slate-500">Total Expenses</p>
                    <h3 className="text-2xl font-bold text-slate-800 mt-1">{currencySymbol}{totalExpenses.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3>
                </div>
                <div className="p-3 bg-red-100 rounded-lg">
                    <CediSign className="w-6 h-6 text-red-600" />
                </div>
            </div>

            <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-medium text-slate-500">Avg. Transaction</p>
                    <h3 className="text-xl font-bold text-slate-800 mt-1">{currencySymbol}{avgExpense.toLocaleString(undefined, { minimumFractionDigits: 2 })}</h3>
                </div>
                <div className="p-3 bg-blue-100 rounded-lg">
                    <TrendingUp className="w-6 h-6 text-blue-600" />
                </div>
            </div>

             <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 flex items-center justify-between">
                <div>
                    <p className="text-sm font-medium text-slate-500">Highest Category</p>
                    <h3 className="text-xl font-bold text-slate-800 mt-1 truncate max-w-[150px]">{topCategory}</h3>
                </div>
                <div className="p-3 bg-indigo-100 rounded-lg">
                    <PieIcon className="w-6 h-6 text-indigo-600" />
                </div>
            </div>
        </div>

        {/* Breakdown Chart */}
        <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-1">
             <h3 className="text-sm font-bold text-slate-700 mb-4">Category Breakdown</h3>
             <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                    <PieChart>
                        <Pie
                            data={categoryData}
                            cx="50%"
                            cy="50%"
                            innerRadius={40}
                            outerRadius={60}
                            paddingAngle={5}
                            dataKey="value"
                        >
                            {categoryData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                        </Pie>
                        <RechartsTooltip formatter={(value: number) => `${currencySymbol}${value.toLocaleString()}`} />
                        <Legend iconType="circle" layout="horizontal" verticalAlign="bottom" align="center" wrapperStyle={{fontSize: '10px'}} />
                    </PieChart>
                </ResponsiveContainer>
             </div>
        </div>

         {/* Daily Trend Chart */}
         <div className="bg-white p-6 rounded-xl shadow-sm border border-slate-200 lg:col-span-1 hidden lg:block">
             <h3 className="text-sm font-bold text-slate-700 mb-4">Daily Trend (Recent)</h3>
             <div className="h-48">
                <ResponsiveContainer width="100%" height="100%">
                    <BarChart data={dailyData}>
                        <CartesianGrid strokeDasharray="3 3" vertical={false} />
                        <XAxis dataKey="date" fontSize={10} tickLine={false} axisLine={false} />
                        <RechartsTooltip 
                            cursor={{fill: '#f1f5f9'}}
                            formatter={(value: number) => [`${currencySymbol}${value}`, 'Amount']}
                        />
                        <Bar dataKey="amount" fill="#ef4444" radius={[4, 4, 0, 0]} />
                    </BarChart>
                </ResponsiveContainer>
             </div>
        </div>
      </div>

      {/* Action & Filter Bar */}
      <div className="bg-white p-4 rounded-xl shadow-sm border border-slate-200 flex flex-col lg:flex-row gap-4 items-end lg:items-center justify-between">
            <div className="flex flex-col md:flex-row gap-2 w-full lg:w-auto">
                 {/* Search */}
                <div className="relative w-full md:w-48">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Search className="h-4 w-4 text-slate-400" />
                    </div>
                    <input
                        type="text"
                        className="block w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                        placeholder="Search..."
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                {/* Filters */}
                <select 
                    value={selectedCategory} 
                    onChange={(e) => setSelectedCategory(e.target.value)}
                    className="block w-full md:w-36 px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                >
                    <option value="All">All Categories</option>
                    {categories.map(c => <option key={c} value={c}>{c}</option>)}
                </select>

                <div className="flex gap-2">
                    <input
                        type="date"
                        className="block w-full md:w-auto px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                        value={startDate}
                        onChange={(e) => setStartDate(e.target.value)}
                        placeholder="Start Date"
                    />
                    <input
                        type="date"
                        className="block w-full md:w-auto px-3 py-2 border border-slate-300 rounded-lg text-sm focus:outline-none focus:ring-2 focus:ring-primary"
                        value={endDate}
                        onChange={(e) => setEndDate(e.target.value)}
                        placeholder="End Date"
                    />
                </div>

                {(searchTerm || startDate || endDate || selectedCategory !== 'All') && (
                     <button 
                        onClick={() => { setSearchTerm(''); setStartDate(''); setEndDate(''); setSelectedCategory('All'); }}
                        className="text-red-500 hover:text-red-700 text-xs font-medium px-2"
                    >
                        Reset
                    </button>
                )}
            </div>

            <div className="flex gap-3 w-full lg:w-auto">
                <button
                    onClick={handleExportCSV}
                    disabled={filteredExpenses.length === 0}
                    className="flex-1 lg:flex-none flex items-center justify-center px-4 py-2 border border-slate-300 text-sm font-medium rounded-lg text-slate-700 bg-white hover:bg-slate-50 focus:outline-none shadow-sm disabled:opacity-50"
                >
                    <Download className="h-4 w-4 mr-2" />
                    Export CSV
                </button>
                <button
                    onClick={() => setIsFormOpen(!isFormOpen)}
                    className="flex-1 lg:flex-none flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-lg text-white bg-primary hover:bg-blue-800 focus:outline-none shadow-sm transition-all"
                >
                    {isFormOpen ? 'Close' : 'Add Expense'}
                    {!isFormOpen && <Plus className="h-4 w-4 ml-2" />}
                </button>
            </div>
      </div>

      {/* Add Expense Form */}
      {isFormOpen && (
        <div className="bg-slate-50 p-6 rounded-xl border border-slate-200 animate-fade-in shadow-inner">
            <h3 className="text-lg font-bold text-slate-800 mb-4 flex items-center">
                <Plus className="w-5 h-5 mr-2 text-primary" /> Record New Expense
            </h3>
            <form onSubmit={handleSubmit} className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 items-end">
                <div className="lg:col-span-2">
                    <label className="block text-sm font-medium text-slate-700 mb-1">Description</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <Tag className="h-4 w-4 text-slate-400" />
                        </div>
                        <input
                            type="text"
                            required
                            className="block w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            placeholder="e.g. Shop Rent for March"
                            value={formData.description}
                            onChange={(e) => setFormData({...formData, description: e.target.value})}
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Amount</label>
                    <div className="relative">
                        <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                            <span className="text-slate-400 font-bold">{currencySymbol}</span>
                        </div>
                        <input
                            type="number"
                            min="0"
                            step="0.01"
                            required
                            className="block w-full pl-8 pr-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            value={formData.amount}
                            onChange={(e) => setFormData({...formData, amount: e.target.value})}
                        />
                    </div>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Category</label>
                    <select
                        required
                        className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                        value={formData.category}
                        onChange={(e) => setFormData({...formData, category: e.target.value})}
                    >
                        <option value="">Select Category</option>
                        {categories.map(c => <option key={c} value={c}>{c}</option>)}
                    </select>
                </div>
                <div>
                    <label className="block text-sm font-medium text-slate-700 mb-1">Date</label>
                    <div className="relative">
                        <input
                            type="date"
                            required
                            className="block w-full px-3 py-2 border border-slate-300 rounded-lg focus:ring-primary focus:border-primary"
                            value={formData.date}
                            onChange={(e) => setFormData({...formData, date: e.target.value})}
                        />
                    </div>
                </div>
                <div className="lg:col-span-5 flex justify-end mt-2">
                    <button type="submit" className="px-6 py-2 bg-green-600 text-white font-medium rounded-lg hover:bg-green-700 shadow-sm transition-colors">
                        Save Record
                    </button>
                </div>
            </form>
        </div>
      )}

      {/* Expenses Table */}
      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
                <tr>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Date</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Description</th>
                    <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Category</th>
                    <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Amount</th>
                </tr>
            </thead>
            <tbody className="divide-y divide-slate-200">
                {filteredExpenses.map((expense) => (
                    <tr key={expense.id} className="hover:bg-slate-50 transition-colors">
                        <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-600">
                            {new Date(expense.date).toLocaleDateString()}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-800">
                            {expense.description}
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap">
                            <span className="px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full bg-slate-100 text-slate-600 border border-slate-200">
                                {expense.category}
                            </span>
                        </td>
                        <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-bold text-red-600">
                            -{currencySymbol}{expense.amount.toFixed(2)}
                        </td>
                    </tr>
                ))}
                {filteredExpenses.length === 0 && (
                    <tr>
                        <td colSpan={4} className="px-6 py-12 text-center text-slate-500">
                            <div className="flex flex-col items-center justify-center">
                                <Filter className="w-8 h-8 text-slate-300 mb-2" />
                                <p>No expenses found matching current filters.</p>
                            </div>
                        </td>
                    </tr>
                )}
            </tbody>
        </table>
      </div>
    </div>
  );
};

export interface InventoryItem {
  id: string;
  name: string;
  category: string;
  quantity: number;
  costPrice: number;
  salesPrice: number;
  lowStockThreshold: number;
  lastUpdated: string;
}

export interface SaleItem {
  itemId: string;
  name: string;
  quantity: number;
  priceAtSale: number;
  costAtSale: number;
  discount?: number;
}

export interface SaleRecord {
  id: string;
  items: SaleItem[];
  totalAmount: number;
  totalProfit: number;
  timestamp: string;
}

export interface ExpenseRecord {
  id: string;
  description: string;
  amount: number;
  category: string;
  date: string;
  recordedAt: string;
}

export interface PurchaseOrderItem {
  itemId: string;
  name: string;
  quantity: number;
  unitCost: number;
}

export interface PurchaseOrder {
  id: string;
  supplier: string;
  date: string;
  status: 'ordered' | 'received' | 'cancelled';
  items: PurchaseOrderItem[];
  totalCost: number;
  notes?: string;
}

export interface AuditLog {
  id: string;
  itemId: string;
  itemName: string;
  action: 'create' | 'update' | 'adjustment' | 'sale' | 'restock';
  details: string;
  userId: string;
  timestamp: string;
}

export type ViewState = 'dashboard' | 'inventory' | 'pos' | 'history' | 'expenses' | 'financials' | 'insights' | 'purchases';

export type UserRole = 'admin' | 'cashier';

export interface DashboardMetrics {
  totalRevenue: number;
  totalProfit: number;
  lowStockCount: number;
  totalInventoryValue: number;
}

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, ShoppingCart, BrainCircuit, Menu, X, History, Wifi, WifiOff, Loader2, PieChart, Truck, LogOut, Shield } from 'lucide-react';
import { InventoryManager } from './components/InventoryManager';
import { SalesTerminal } from './components/SalesTerminal';
import { Dashboard } from './components/Dashboard';
import { AIInsights } from './components/AIInsights';
import { SalesHistory } from './components/SalesHistory';
import { ExpensesManager } from './components/ExpensesManager';
import { FinancialReport } from './components/FinancialReport';
import { PurchaseOrdersManager } from './components/PurchaseOrdersManager';
import { Auth } from './components/Auth';
import { InventoryItem, SaleRecord, SaleItem, ViewState, ExpenseRecord, PurchaseOrder, UserRole, AuditLog } from './types';
import { supabase } from './services/supabaseClient';
import { Session } from '@supabase/supabase-js';

// Custom Cedi Icon Component
const CediSign = ({ className }: { className?: string }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M16 7a6 6 0 1 0 0 10" />
    <path d="M10 3v18" />
  </svg>
);

const App: React.FC = () => {
  // Auth State
  const [session, setSession] = useState<Session | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // State Management
  const [activeView, setActiveView] = useState<ViewState>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Data State
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [expenses, setExpenses] = useState<ExpenseRecord[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);

  // Connectivity Listeners
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Auth Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      // Reset view to dashboard on login
      if (session) setActiveView('dashboard');
    });

    return () => subscription.unsubscribe();
  }, []);

  // Fetch Data from Supabase
  const fetchData = async () => {
    if (!session) return; // Don't fetch if not logged in

    setLoading(true);
    try {
      // Fetch Inventory
      const { data: invData, error: invError } = await supabase
        .from('inventory')
        .select('*');

      if (invError) throw invError;
      if (invData) setInventory(invData);

      // Fetch Sales
      const { data: salesData, error: salesError } = await supabase
        .from('sales')
        .select('*')
        .order('timestamp', { ascending: false });

      if (salesError) throw salesError;
      if (salesData) setSales(salesData);

      // Fetch Expenses
      const { data: expData, error: expError } = await supabase
        .from('expenses')
        .select('*')
        .order('date', { ascending: false });

      if (expError) throw expError;
      if (expData) setExpenses(expData);

      // Fetch Purchase Orders
      const { data: poData, error: poError } = await supabase
        .from('purchase_orders')
        .select('*')
        .order('date', { ascending: false });

      if (poError) {
         console.warn("Could not fetch purchase orders. Table might not exist yet.");
      } else if (poData) {
         setPurchaseOrders(poData);
      }

      // Fetch Audit Logs (Simulated for this demo as we can't create new tables in this environment)
      // In a real app: const { data: logData } = await supabase.from('audit_logs').select('*');
      // For now, we keep auditLogs in local state but don't overwrite it on fetch to maintain history during session

    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  // Fetch data when session becomes available
  useEffect(() => {
    if (session) {
      fetchData();
    }
  }, [session]);

  // Helper: Create Audit Log
  const logAction = (
    itemId: string, 
    itemName: string, 
    action: AuditLog['action'], 
    details: string
  ) => {
    if (!session?.user) return;

    const newLog: AuditLog = {
      id: crypto.randomUUID(),
      itemId,
      itemName,
      action,
      details,
      userId: session.user.email || 'Unknown User',
      timestamp: new Date().toISOString()
    };

    setAuditLogs(prev => [newLog, ...prev]);
    // In real app: await supabase.from('audit_logs').insert([newLog]);
  };

  // Handlers
  const handleAddItem = async (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const newItem: InventoryItem = {
      ...item,
      id: crypto.randomUUID(), // Generate UUID
      lastUpdated: new Date().toISOString()
    };

    // Optimistic Update
    setInventory(prev => [...prev, newItem]);
    logAction(newItem.id, newItem.name, 'create', `Item created. Initial Stock: ${newItem.quantity}`);

    try {
      const { error } = await supabase.from('inventory').insert([newItem]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding item:", err);
      alert("Failed to save item to database.");
      fetchData(); // Revert on error
    }
  };

  const handleUpdateItem = async (id: string, updates: Partial<InventoryItem>) => {
    const oldItem = inventory.find(i => i.id === id);
    if (!oldItem) return;

    const updatedTimestamp = new Date().toISOString();
    const finalUpdates = { ...updates, lastUpdated: updatedTimestamp };

    // Determine what changed for the log
    if (updates.quantity !== undefined && updates.quantity !== oldItem.quantity) {
       logAction(id, oldItem.name, 'adjustment', `Stock adjusted from ${oldItem.quantity} to ${updates.quantity}`);
    }
    if (updates.costPrice !== undefined && updates.costPrice !== oldItem.costPrice) {
       logAction(id, oldItem.name, 'update', `Cost price changed from ${oldItem.costPrice} to ${updates.costPrice}`);
    }
    if (updates.salesPrice !== undefined && updates.salesPrice !== oldItem.salesPrice) {
       logAction(id, oldItem.name, 'update', `Sales price changed from ${oldItem.salesPrice} to ${updates.salesPrice}`);
    }

    // Optimistic Update
    setInventory(prev => prev.map(item => item.id === id ? { ...item, ...finalUpdates } : item));

    try {
      const { error } = await supabase
        .from('inventory')
        .update(finalUpdates)
        .eq('id', id);

      if (error) throw error;
    } catch (err) {
      console.error("Error updating item:", err);
      alert("Failed to update item in database.");
      fetchData(); // Revert
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      // Optimistic Update
      setInventory(prev => prev.filter(item => item.id !== id));

      try {
        const { error } = await supabase.from('inventory').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting item:", err);
        alert("Failed to delete item from database.");
        fetchData(); // Revert
      }
    }
  };

  const handleCompleteSale = async (items: SaleItem[]) => {
    // Calculate total amount considering discounts
    const totalAmount = items.reduce((sum, item) => 
      sum + ((item.quantity * item.priceAtSale) - (item.discount || 0)), 0
    );

    // Total cost is purely COGS
    const totalCost = items.reduce((sum, item) => sum + (item.quantity * item.costAtSale), 0);

    const newSale: SaleRecord = {
      id: crypto.randomUUID(),
      items,
      totalAmount,
      totalProfit: totalAmount - totalCost,
      timestamp: new Date().toISOString()
    };

    // Optimistic Update for UI
    const newInventory = [...inventory];
    items.forEach(saleItem => {
      const productIndex = newInventory.findIndex(p => p.id === saleItem.itemId);
      if (productIndex > -1) {
        const oldQty = newInventory[productIndex].quantity;
        const newQty = oldQty - saleItem.quantity;

        newInventory[productIndex] = {
            ...newInventory[productIndex],
            quantity: newQty,
            lastUpdated: new Date().toISOString()
        };

        logAction(saleItem.itemId, saleItem.name, 'sale', `Sold ${saleItem.quantity} units. Stock: ${oldQty} -> ${newQty}`);
      }
    });

    setInventory(newInventory);
    setSales(prev => [newSale, ...prev]);

    try {
        // 1. Record Sale
        const { error: saleError } = await supabase.from('sales').insert([newSale]);
        if (saleError) throw saleError;

        // 2. Update Inventory Quantities
        for (const item of items) {
             const currentItem = inventory.find(i => i.id === item.itemId);
             if (currentItem) {
                 const newQty = currentItem.quantity - item.quantity;
                 await supabase
                    .from('inventory')
                    .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
                    .eq('id', item.itemId);
             }
        }
    } catch (err) {
        console.error("Error processing sale:", err);
        alert("Error saving sale to database. Please check connection.");
        fetchData(); // Revert to server state
    }
  };

  const handleAddExpense = async (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => {
    const newExpense: ExpenseRecord = {
      ...expense,
      id: crypto.randomUUID(),
      recordedAt: new Date().toISOString()
    };

    setExpenses(prev => [newExpense, ...prev]);

    try {
      const { error } = await supabase.from('expenses').insert([newExpense]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding expense:", err);
      alert("Failed to save expense.");
      fetchData();
    }
  };

  const handleDeleteExpense = async (id: string) => {
    if (window.confirm('Delete this expense record?')) {
      setExpenses(prev => prev.filter(e => e.id !== id));
      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting expense:", err);
        fetchData();
      }
    }
  };

  const handleCreatePO = async (po: Omit<PurchaseOrder, 'id'>) => {
    const newPO: PurchaseOrder = {
      ...po,
      id: crypto.randomUUID(),
    };

    setPurchaseOrders(prev => [newPO, ...prev]);

    try {
      const { error } = await supabase.from('purchase_orders').insert([newPO]);
      if (error) throw error;
    } catch (err) {
      console.error("Error creating PO:", err);
      alert("Failed to save Purchase Order.");
      fetchData();
    }
  };

  const handleUpdatePOStatus = async (id: string, status: 'received' | 'cancelled') => {
    const po = purchaseOrders.find(p => p.id === id);
    if (!po) return;

    // Optimistic Update
    setPurchaseOrders(prev => prev.map(p => p.id === id ? { ...p, status } : p));

    try {
      const { error } = await supabase
        .from('purchase_orders')
        .update({ status })
        .eq('id', id);

      if (error) throw error;

      // Logic: If marking as RECEIVED, update inventory stock
      if (status === 'received' && po.status !== 'received') {
        const updatedInventory = [...inventory];

        for (const item of po.items) {
           const invIndex = updatedInventory.findIndex(i => i.id === item.itemId);
           if (invIndex > -1) {
             const currentInv = updatedInventory[invIndex];
             const newQty = currentInv.quantity + item.quantity;

             // Update local state
             updatedInventory[invIndex] = {
               ...currentInv,
               quantity: newQty,
               lastUpdated: new Date().toISOString()
             };

             logAction(item.itemId, item.name, 'restock', `PO Received (${po.supplier}). Added ${item.quantity} units. Stock: ${currentInv.quantity} -> ${newQty}`);

             // Update Database
             await supabase
               .from('inventory')
               .update({ quantity: newQty, lastUpdated: new Date().toISOString() })
               .eq('id', item.itemId);
           }
        }
        setInventory(updatedInventory);
      }

    } catch (err) {
      console.error("Error updating PO status:", err);
      alert("Failed to update order status.");
      fetchData();
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState, icon: any, label: string }) => (
    <button
      onClick={() => { setActiveView(view); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center space-x-3 px-6 py-4 transition-colors ${
        activeView === view 
          ? 'bg-blue-900 border-l-4 border-secondary text-white' 
          : 'text-blue-200 hover:bg-blue-800 hover:text-white'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  // 1. Initial Loading State
  if (authLoading) {
      return (
          <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center text-primary">
              <Loader2 className="w-12 h-12 animate-spin mb-4" />
              <h2 className="text-xl font-bold">Raha Soldi System</h2>
              <p className="text-slate-500 mt-2">Checking secure session...</p>
          </div>
      );
  }

  // 2. Auth Guard
  if (!session) {
    return <Auth />;
  }

  // Extract Role
  // In a real app we might fetch this from a 'profiles' table, but for this prototype we rely on metadata
  const userRole = (session.user.user_metadata?.role as UserRole) || 'cashier';

  // 3. Main Application
  return (
    <div className="flex min-h-screen bg-slate-50 font-sans">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 bg-primary text-white fixed h-full shadow-xl z-20">
        <div className="p-8">
          <h1 className="text-2xl font-bold tracking-tight text-white">Raha Soldi <span className="text-secondary">Ent.</span></h1>
          <p className="text-xs text-blue-300 mt-1 uppercase tracking-wider">Inventory System</p>
        </div>
        <nav className="flex-1 mt-6 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {/* Admin Only Links */}
          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={CediSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}
        </nav>
        <div className="p-6 border-t border-blue-800">
             <div className="mb-4">
                 <div className="flex items-center space-x-2 mb-1">
                   <Shield className="w-3 h-3 text-secondary" />
                   <p className="text-xs text-blue-300 uppercase">{userRole}</p>
                 </div>
                 <p className="text-sm font-medium truncate" title={session.user.email}>{session.user.email}</p>
             </div>
            <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 hover:bg-blue-800 text-white py-2 rounded-lg transition-colors text-sm"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
            <div className={`mt-4 flex items-center justify-center text-xs px-3 py-2 rounded-lg ${isOnline ? 'bg-blue-800 text-blue-200' : 'bg-red-800 text-red-100'}`}>
                {isOnline ? <Wifi className="w-3 h-3 mr-2" /> : <WifiOff className="w-3 h-3 mr-2" />}
                {isOnline ? 'Online' : 'Offline Mode'}
            </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="lg:hidden fixed top-0 w-full bg-primary text-white z-30 flex items-center justify-between p-4 shadow-md">
        <h1 className="text-lg font-bold">Raha Soldi Ent.</h1>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 bg-primary z-20 pt-20 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={CediSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
            </>
          )}

          <div className="p-4 border-t border-blue-800 mt-4">
             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 text-white py-3 rounded-lg"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 lg:ml-64 p-4 lg:p-8 pt-20 lg:pt-8 transition-all duration-300">
        <div className="max-w-7xl mx-auto">
          <header className="mb-8 flex justify-between items-end">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">
                {activeView === 'dashboard' && 'Business Overview'}
                {activeView === 'inventory' && 'Inventory Management'}
                {activeView === 'pos' && 'New Sale'}
                {activeView === 'history' && 'Transaction History'}
                {activeView === 'expenses' && 'Expense Management'}
                {activeView === 'financials' && 'Financial Health'}
                {activeView === 'insights' && 'Business Intelligence'}
                {activeView === 'purchases' && 'Supplier Purchase Orders'}
              </h2>
              <p className="text-slate-500 text-sm mt-1">
                {activeView === 'dashboard' && 'Welcome back.'}
                {activeView === 'inventory' && 'Manage your stock and pricing.'}
                {activeView === 'pos' && 'Process transactions quickly.'}
                {activeView === 'history' && 'Review past sales and performance.'}
                {activeView === 'expenses' && 'Track operational costs.'}
                {activeView === 'financials' && 'Analyze Profit & Loss and Balance Sheet.'}
                {activeView === 'insights' && 'AI-powered recommendations.'}
                {activeView === 'purchases' && 'Create orders and restock inventory.'}
              </p>
            </div>
            <div className="text-right hidden sm:block">
               <div className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>
            </div>
          </header>

          <div className="fade-in">
             {loading ? (
                 <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                     <Loader2 className="w-10 h-10 animate-spin mb-4" />
                     <p>Loading data...</p>
                 </div>
             ) : (
                <>
                    {activeView === 'dashboard' && <Dashboard inventory={inventory} sales={sales} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'inventory' && <InventoryManager inventory={inventory} onAdd={handleAddItem} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} currencySymbol="GH₵" userRole={userRole} auditLogs={auditLogs} />}
                    {activeView === 'pos' && <SalesTerminal inventory={inventory} onCompleteSale={handleCompleteSale} currencySymbol="GH₵" />}
                    {activeView === 'history' && <SalesHistory sales={sales} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'expenses' && <ExpensesManager expenses={expenses} onAdd={handleAddExpense} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'financials' && <FinancialReport inventory={inventory} sales={sales} expenses={expenses} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'insights' && <AIInsights inventory={inventory} sales={sales} />}
                    {userRole === 'admin' && activeView === 'purchases' && (
                    <PurchaseOrdersManager 
                        inventory={inventory} 
                        purchaseOrders={purchaseOrders} 
                        onCreateOrder={handleCreatePO} 
                        onUpdateStatus={handleUpdatePOStatus} 
                        currencySymbol="GH₵" 
                    />
                    )}
                </>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { InventoryItem, UserRole, AuditLog } from '../types';
import { Plus, Search, Edit2, Trash2, AlertCircle, Check, ClipboardEdit, X, History as HistoryIcon, User, Clock } from 'lucide-react';

interface InventoryManagerProps {
  inventory: InventoryItem[];
  onAdd: (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => void;
  onUpdate: (id: string, item: Partial<InventoryItem>) => void;
  onDelete: (id: string) => void;
  currencySymbol: string;
  userRole: UserRole;
  auditLogs: AuditLog[];
}

export const InventoryManager: React.FC<InventoryManagerProps> = ({ inventory, onAdd, onUpdate, onDelete, currencySymbol, userRole, auditLogs }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Edit/Add Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Stock Adjust Modal State
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [adjustItem, setAdjustItem] = useState<InventoryItem | null>(null);
  const [adjustQty, setAdjustQty] = useState<string>('');
  const [adjustmentType, setAdjustmentType] = useState<'add' | 'remove' | 'set'>('add');

  // History Modal State
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [historyItem, setHistoryItem] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    quantity: 0,
    costPrice: 0,
    salesPrice: 0,
    lowStockThreshold: 5
  });

  const categories = useMemo(() => {
    return Array.from(new Set(inventory.map(i => i.category))).sort();
  }, [inventory]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [inventory, searchTerm]);

  // Filter logs for the specific item in the history modal
  const itemLogs = useMemo(() => {
    if (!historyItem) return [];
    return auditLogs.filter(log => log.itemId === historyItem.id).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [auditLogs, historyItem]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate(editingId, formData);
    } else {
      onAdd(formData);
    }
    resetForm();
  };

  const handleEdit = (item: InventoryItem) => {
    setEditingId(item.id);
    setFormData({
      name: item.name,
      category: item.category,
      quantity: item.quantity,
      costPrice: item.costPrice,
      salesPrice: item.salesPrice,
      lowStockThreshold: item.lowStockThreshold
    });
    setIsModalOpen(true);
  };

  const resetForm = () => {
    setFormData({
      name: '',
      category: '',
      quantity: 0,
      costPrice: 0,
      salesPrice: 0,
      lowStockThreshold: 5
    });
    setEditingId(null);
    setIsModalOpen(false);
  };

  // Stock Adjustment Handlers
  const openAdjustModal = (item: InventoryItem) => {
    setAdjustItem(item);
    setAdjustQty('');
    setAdjustmentType('add');
    setIsAdjustModalOpen(true);
  };

  const closeAdjustModal = () => {
    setAdjustItem(null);
    setAdjustQty('');
    setIsAdjustModalOpen(false);
  };

  const openHistoryModal = (item: InventoryItem) => {
    setHistoryItem(item);
    setIsHistoryModalOpen(true);
  };

  const closeHistoryModal = () => {
    setHistoryItem(null);
    setIsHistoryModalOpen(false);
  };

  const getResultingQty = () => {
    if (!adjustItem) return 0;
    const current = adjustItem.quantity;
    const input = parseInt(adjustQty) || 0;

    if (adjustmentType === 'add') return current + input;
    if (adjustmentType === 'remove') return Math.max(0, current - input);
    return input; // set
  };

  const handleStockAdjustment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!adjustItem) return;

    const inputVal = parseInt(adjustQty);
    if (isNaN(inputVal) || inputVal < 0) {
        alert("Please enter a valid non-negative quantity.");
        return;
    }

    const finalQty = getResultingQty();

    let message = '';
    if (adjustmentType === 'add') message = `Confirm adding ${inputVal} units to ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else if (adjustmentType === 'remove') message = `Confirm removing ${inputVal} units from ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else message = `Confirm setting stock for ${adjustItem.name} to ${finalQty}?`;

    if (window.confirm(message)) {
        onUpdate(adjustItem.id, { quantity: finalQty });
        closeAdjustModal();
    }
  };

  const getLogBadgeColor = (action: string) => {
    switch (action) {
        case 'create': return 'bg-blue-100 text-blue-800 border-blue-200';
        case 'restock': return 'bg-green-100 text-green-800 border-green-200';
        case 'adjustment': return 'bg-purple-100 text-purple-800 border-purple-200';
        case 'sale': return 'bg-red-100 text-red-800 border-red-200';
        case 'update': return 'bg-orange-100 text-orange-800 border-orange-200';
        default: return 'bg-slate-100 text-slate-800 border-slate-200';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="relative w-full sm:w-96">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-slate-400" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary sm:text-sm transition duration-150 ease-in-out"
            placeholder="Search products or categories..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        {userRole === 'admin' && (
          <button
            onClick={() => setIsModalOpen(true)}
            className="flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-lg text-white bg-primary hover:bg-blue-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary shadow-sm"
          >
            <Plus className="h-5 w-5 mr-2" />
            Add Product
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Product</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Category</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Stock</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Pricing</th>
                {userRole === 'admin' && (
                  <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Actions</th>
                )}
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {filteredInventory.map((item) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="h-10 w-10 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold text-lg">
                        {item.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="ml-4">
                        <div className="text-sm font-medium text-slate-900">{item.name}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-slate-100 text-slate-800">
                      {item.category}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <span className={`text-sm font-medium ${item.quantity <= item.lowStockThreshold ? 'text-red-600' : 'text-slate-900'}`}>
                        {item.quantity} Units
                      </span>
                      {item.quantity <= item.lowStockThreshold && (
                        <AlertCircle className="w-4 h-4 text-red-600 ml-2" />
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">
                    <div className="flex flex-col">
                      <span className="text-slate-900 font-medium">Sell: {currencySymbol}{item.salesPrice.toFixed(2)}</span>
                      {userRole === 'admin' && (
                        <span className="text-xs">Cost: {currencySymbol}{item.costPrice.toFixed(2)}</span>
                      )}
                    </div>
                  </td>
                  {userRole === 'admin' && (
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <div className="flex items-center justify-end space-x-3">
                          <button 
                              onClick={() => openHistoryModal(item)} 
                              className="text-slate-400 hover:text-blue-600 transition-colors"
                              title="View Audit Trail"
                          >
                            <HistoryIcon className="w-5 h-5" />
                          </button>
                          <button 
                              onClick={() => openAdjustModal(item)} 
                              className="text-slate-400 hover:text-indigo-600 transition-colors"
                              title="Adjust Stock"
                          >
                            <ClipboardEdit className="w-5 h-5" />
                          </button>
                          <button onClick={() => handleEdit(item)} className="text-slate-400 hover:text-indigo-600 transition-colors" title="Edit Details">
                            <Edit2 className="w-5 h-5" />
                          </button>
                          <button onClick={() => onDelete(item.id)} className="text-slate-400 hover:text-red-600 transition-colors" title="Delete Product">
                            <Trash2 className="w-5 h-5" />
                          </button>
                      </div>
                    </td>
                  )}
                </tr>
              ))}
              {filteredInventory.length === 0 && (
                <tr>
                  <td colSpan={userRole === 'admin' ? 5 : 4} className="px-6 py-12 text-center text-slate-500">
                    No products found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Product Form Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden transform transition-all">
            <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <h3 className="text-lg font-bold text-slate-800">
                {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={resetForm} className="text-slate-400 hover:text-slate-600">
                <span className="text-2xl">&times;</span>
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Product Name</label>
                <input
                  type="text"
                  required
                  className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Category</label>
                <input
                  type="text"
                  required
                  list="category-options"
                  className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  placeholder="Type or select a category"
                />
                <datalist id="category-options">
                  {categories.map((cat) => (
                    <option key={cat} value={cat} />
                  ))}
                </datalist>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Cost Price ({currencySymbol})</label>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.costPrice}
                    onChange={(e) => setFormData({ ...formData, costPrice: parseFloat(e.target.value) })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Sales Price ({currencySymbol})</label>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.salesPrice}
                    onChange={(e) => setFormData({ ...formData, salesPrice: parseFloat(e.target.value) })}
                  />
                </div>
              </div>

              <div className="grid grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Initial Stock</label>
                  <input
                    type="number"
                    min="0"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.quantity}
                    onChange={(e) => setFormData({ ...formData, quantity: parseInt(e.target.value) || 0 })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Low Stock Alert Level</label>
                  <input
                    type="number"
                    min="0"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.lowStockThreshold}
                    onChange={(e) => setFormData({ ...formData, lowStockThreshold: parseInt(e.target.value) || 0 })}
                  />
                </div>
              </div>

              <div className="pt-4 flex justify-end space-x-3">
                <button
                  type="button"
                  onClick={resetForm}
                  className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-blue-800 transition-colors flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {editingId ? 'Update Product' : 'Save Product'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Stock Adjustment Modal */}
      {isAdjustModalOpen && adjustItem && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
             <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden transform transition-all animate-fade-in">
                 <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center">
                        <ClipboardEdit className="w-5 h-5 mr-2 text-primary" />
                        Adjust Stock
                    </h3>
                    <button onClick={closeAdjustModal} className="text-slate-400 hover:text-slate-600">
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <form onSubmit={handleStockAdjustment} className="p-6">
                    <div className="mb-6 bg-slate-50 p-4 rounded-lg border border-slate-100">
                        <div className="text-sm text-slate-500 mb-1">Product</div>
                        <div className="text-lg font-bold text-slate-800">{adjustItem.name}</div>
                        <div className="text-sm text-slate-500 mt-1">Current Stock: <span className="font-bold text-slate-800">{adjustItem.quantity}</span></div>
                    </div>

                    <div className="mb-6">
                        <label className="block text-sm font-medium text-slate-700 mb-2">Action</label>
                        <div className="flex bg-slate-100 p-1 rounded-lg">
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('add')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'add' ? 'bg-white text-green-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Add (+)
                            </button>
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('remove')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'remove' ? 'bg-white text-red-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Remove (-)
                            </button>
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('set')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'set' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Set Total
                            </button>
                        </div>
                    </div>

                    <div className="mb-6">
                        <label className="block text-sm font-medium text-slate-700 mb-2">
                            {adjustmentType === 'set' ? 'New Total Quantity' : 'Quantity to ' + (adjustmentType === 'add' ? 'Add' : 'Remove')}
                        </label>
                        <input
                            type="number"
                            min="0"
                            required
                            autoFocus
                            className="block w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-3 border text-lg"
                            value={adjustQty}
                            onChange={(e) => setAdjustQty(e.target.value)}
                            placeholder="0"
                        />
                    </div>

                    <div className="flex justify-between items-center py-3 px-4 bg-slate-50 rounded-lg border border-slate-100 mb-6">
                        <span className="text-sm text-slate-500">Resulting Stock:</span>
                        <span className={`text-lg font-bold ${getResultingQty() < (adjustItem.lowStockThreshold || 0) ? 'text-red-600' : 'text-slate-800'}`}>
                            {getResultingQty()}
                        </span>
                    </div>

                    <div className="flex justify-end space-x-3">
                        <button
                            type="button"
                            onClick={closeAdjustModal}
                            className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors font-medium"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-blue-800 transition-colors font-medium"
                        >
                            Confirm Change
                        </button>
                    </div>
                </form>
             </div>
        </div>
      )}

      {/* Audit Log / History Modal */}
      {isHistoryModalOpen && historyItem && (
          <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
