import { GoogleGenAI } from "@google/genai";
import { InventoryItem, SaleRecord } from "../types";

const getClient = () => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found");
  }
  return new GoogleGenAI({ apiKey });
};

export const generateBusinessInsights = async (
  inventory: InventoryItem[],
  sales: SaleRecord[],
  startDate?: Date,
  endDate?: Date,
  customQuery?: string
): Promise<string> => {
  try {
    const ai = getClient();

    // Filter sales by date if provided
    let filteredSales = sales;
    if (startDate) {
        // Create start date at 00:00:00
        const start = new Date(startDate);
        start.setHours(0, 0, 0, 0);
        filteredSales = filteredSales.filter(s => new Date(s.timestamp) >= start);
    }
    if (endDate) {
        // Create end date at 23:59:59
        const end = new Date(endDate);
        end.setHours(23, 59, 59, 999);
        filteredSales = filteredSales.filter(s => new Date(s.timestamp) <= end);
    }

    // Summarize Inventory
    // To save context tokens and provide high-level overview
    const inventorySummary = inventory.slice(0, 100).map(item => 
      `- ${item.name} (${item.category}): Qty ${item.quantity}, Cost ${item.costPrice}, Sell ${item.salesPrice}`
    ).join('\n');

    const inventoryStats = {
        totalItems: inventory.length,
        totalValue: inventory.reduce((acc, i) => acc + (i.costPrice * i.quantity), 0),
        lowStockCount: inventory.filter(i => i.quantity <= i.lowStockThreshold).length
    };

    // Summarize Sales
    const totalRevenue = filteredSales.reduce((sum, s) => sum + s.totalAmount, 0);
    const totalProfit = filteredSales.reduce((sum, s) => sum + s.totalProfit, 0);
    const salesCount = filteredSales.length;

    // Provide detailed transaction list (limit to recent 50 within the filtered set)
    const recentSalesDetails = filteredSales.slice(0, 50).map(s => 
      `- ${new Date(s.timestamp).toLocaleDateString()}: Items[${s.items.map(i => i.name).join(', ')}], Total ${s.totalAmount.toFixed(2)}`
    ).join('\n');

    const context = `
      Data Context:
      Analysis Period: ${startDate ? startDate.toLocaleDateString() : 'All Time'} to ${endDate ? endDate.toLocaleDateString() : 'Now'}

      Sales Performance in Period:
      - Total Revenue: GH₵${totalRevenue.toFixed(2)}
      - Total Profit: GH₵${totalProfit.toFixed(2)}
      - Transaction Count: ${salesCount}

      Inventory Overview (Current Snapshot):
      - Total SKUs: ${inventoryStats.totalItems}
      - Total Valuation: GH₵${inventoryStats.totalValue.toFixed(2)}
      - Items Low on Stock: ${inventoryStats.lowStockCount}
    `;

    let prompt = `
      You are an expert business consultant for "Raha Soldi Ent", a Ghanaian general trading company.

      ${context}

      Current Inventory Details (Sample):
      ${inventorySummary}

      Transactions in Selected Period (Sample up to 50):
      ${recentSalesDetails}
    `;

    if (customQuery && customQuery.trim() !== "") {
        prompt += `

        USER QUESTION: "${customQuery}"

        Please answer the user's question specifically based on the provided data context. 
        If the data is insufficient to answer the question fully, explain why and provide the best possible related insights.
        Focus on the data from the specified period.
        `;
    } else {
        prompt += `

        Please provide a concise but insightful analysis of the business status for this period. 

        1. **Sales & Profitability:** Analyze performance trends. Are margins healthy?
        2. **Inventory Health:** Identify low stock items and suggest restocking priorities.
        3. **Top Performers:** Which items are driving revenue?
        4. **Recommendations:** Give actionable advice on pricing, bundling, or stock mix.

        Keep the tone professional, encouraging, and actionable. Use the currency GH₵. Format the response with Markdown for readability (bolding, lists).
        `;
    }

    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: {
        thinkingConfig: { thinkingBudget: 0 }
      }
    });

    return response.text || "Unable to generate insights at this time.";
  } catch (error) {
    console.error("Error generating insights:", error);
    return "Error connecting to AI service. Please check your API key and try again.";
  }
};

import React, { useState, useEffect } from 'react';
import { InventoryItem, SaleItem } from '../types';
import { ShoppingCart, Plus, Trash2, CheckCircle, Search, Tag } from 'lucide-react';

interface SalesTerminalProps {
  inventory: InventoryItem[];
  onCompleteSale: (items: SaleItem[]) => void;
  currencySymbol: string;
}

export const SalesTerminal: React.FC<SalesTerminalProps> = ({ inventory, onCompleteSale, currencySymbol }) => {
  const [cart, setCart] = useState<SaleItem[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [selectedProduct, setSelectedProduct] = useState<InventoryItem | null>(null);
  const [qtyInput, setQtyInput] = useState<number>(1);
  const [successMsg, setSuccessMsg] = useState('');

  // Auto-clear success message
  useEffect(() => {
    if (successMsg) {
      const timer = setTimeout(() => setSuccessMsg(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [successMsg]);

  const filteredInventory = inventory.filter(item => 
    item.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const addToCart = () => {
    if (!selectedProduct) return;

    if (qtyInput <= 0) {
      alert("Quantity must be greater than 0");
      return;
    }

    if (qtyInput > selectedProduct.quantity) {
      alert(`Not enough stock. Only ${selectedProduct.quantity} available.`);
      return;
    }

    const existingItemIndex = cart.findIndex(item => item.itemId === selectedProduct.id);

    if (existingItemIndex > -1) {
        // Check if total new quantity exceeds stock
        if (cart[existingItemIndex].quantity + qtyInput > selectedProduct.quantity) {
             alert(`Cannot add more. Total in cart would exceed stock (${selectedProduct.quantity}).`);
             return;
        }

        const newCart = [...cart];
        newCart[existingItemIndex].quantity += qtyInput;
        setCart(newCart);
    } else {
        const newItem: SaleItem = {
            itemId: selectedProduct.id,
            name: selectedProduct.name,
            quantity: qtyInput,
            priceAtSale: selectedProduct.salesPrice,
            costAtSale: selectedProduct.costPrice,
            discount: 0
        };
        setCart([...cart, newItem]);
    }

    // Reset selection
    setSelectedProduct(null);
    setQtyInput(1);
    setSearchTerm('');
  };

  const removeFromCart = (index: number) => {
    const newCart = [...cart];
    newCart.splice(index, 1);
    setCart(newCart);
  };

  const updateDiscount = (index: number, discount: number) => {
    const newCart = [...cart];
    const item = newCart[index];
    const maxDiscount = item.quantity * item.priceAtSale;

    // Validate discount is positive and doesn't exceed total price
    if (discount < 0) discount = 0;
    if (discount > maxDiscount) discount = maxDiscount;

    newCart[index].discount = discount;
    setCart(newCart);
  };

  const handleCheckout = () => {
    if (cart.length === 0) return;
    onCompleteSale(cart);
    setCart([]);
    setSuccessMsg('Sale recorded successfully!');
  };

  const cartTotal = cart.reduce((acc, item) => acc + (item.quantity * item.priceAtSale) - (item.discount || 0), 0);

  return (
    <div className="flex flex-col lg:grid lg:grid-cols-3 gap-6 h-auto lg:h-[calc(100vh-140px)]">
      {/* Left: Product Selection */}
      <div className="lg:col-span-2 flex flex-col bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden h-[60vh] lg:h-auto">
        <div className="p-4 border-b border-slate-100 bg-slate-50 flex-shrink-0">
          <div className="relative">
             <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="h-5 w-5 text-slate-400" />
              </div>
            <input
              type="text"
              className="block w-full pl-10 pr-3 py-3 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary transition duration-150 ease-in-out"
              placeholder="Search product to add..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        <div className="flex-1 overflow-y-auto p-4">
          <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
            {filteredInventory.map(item => (
              <div 
                key={item.id}
                onClick={() => setSelectedProduct(item)}
                className={`cursor-pointer p-4 rounded-xl border transition-all ${
                  selectedProduct?.id === item.id 
                    ? 'border-primary ring-2 ring-primary ring-opacity-50 bg-indigo-50' 
                    : 'border-slate-200 hover:border-primary hover:shadow-md bg-white'
                }`}
              >
                <div className="flex justify-between items-start mb-2">
                   <div className="font-bold text-slate-800 truncate">{item.name}</div>
                   <div className={`text-xs font-bold px-2 py-1 rounded-full ${item.quantity > item.lowStockThreshold ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
                     Qty: {item.quantity}
                   </div>
                </div>
                <div className="text-sm text-slate-500 mb-1">{item.category}</div>
                <div className="text-lg font-bold text-primary">{currencySymbol}{item.salesPrice.toFixed(2)}</div>
              </div>
            ))}
          </div>
        </div>

        {/* Selected Product Action Area */}
        <div className="p-4 bg-slate-50 border-t border-slate-200 flex-shrink-0">
           {selectedProduct ? (
             <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
               <div className="flex items-center gap-4 w-full sm:w-auto">
                 <span className="font-medium text-slate-700 hidden sm:inline">Add {selectedProduct.name}:</span>
                 <div className="flex items-center border border-slate-300 rounded-lg bg-white">
                   <button 
                    onClick={() => setQtyInput(Math.max(1, qtyInput - 1))}
                    className="px-3 py-2 text-slate-600 hover:bg-slate-100 rounded-l-lg border-r border-slate-300"
                   >-</button>
                   <input 
                    type="number" 
                    className="w-16 text-center py-2 focus:outline-none"
                    value={qtyInput}
                    onChange={(e) => setQtyInput(parseInt(e.target.value) || 0)}
                   />
                    <button 
                    onClick={() => setQtyInput(qtyInput + 1)}
                    className="px-3 py-2 text-slate-600 hover:bg-slate-100 rounded-r-lg border-l border-slate-300"
                   >+</button>
                 </div>
               </div>
               <button 
                onClick={addToCart}
                disabled={itemInCartTotal(cart, selectedProduct.id) + qtyInput > selectedProduct.quantity}
                className="w-full sm:w-auto px-6 py-3 bg-primary text-white font-medium rounded-lg hover:bg-blue-800 shadow-md transition-colors flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
               >
                 <Plus className="w-5 h-5 mr-2" />
                 Add to Cart
               </button>
             </div>
           ) : (
             <div className="text-center text-slate-500 py-3">Select a product above to start adding to cart</div>
           )}
        </div>
      </div>

      {/* Right: Cart & Checkout */}
      <div className="bg-white rounded-xl shadow-xl border border-slate-200 flex flex-col h-auto lg:h-full">
        <div className="p-4 border-b border-slate-100 bg-slate-50 flex justify-between items-center rounded-t-xl">
          <h2 className="font-bold text-slate-800 flex items-center">
            <ShoppingCart className="w-5 h-5 mr-2" />
            Current Sale
          </h2>
          <span className="bg-primary text-white text-xs font-bold px-2 py-1 rounded-full">{cart.length} items</span>
        </div>

        <div className="flex-1 overflow-y-auto p-4 space-y-3 min-h-[250px] lg:min-h-0">
          {cart.length === 0 ? (
            <div className="h-full flex flex-col items-center justify-center text-slate-400">
              <ShoppingCart className="w-12 h-12 mb-2 opacity-20" />
              <p>Cart is empty</p>
            </div>
          ) : (
            cart.map((item, index) => (
              <div key={index} className="p-3 bg-slate-50 rounded-lg border border-slate-100">
                <div className="flex justify-between items-start mb-2">
                  <div>
                    <div className="font-medium text-slate-800">{item.name}</div>
                    <div className="text-sm text-slate-500">{item.quantity} x {currencySymbol}{item.priceAtSale.toFixed(2)}</div>
                  </div>
                  <button onClick={() => removeFromCart(index)} className="text-red-400 hover:text-red-600 transition-colors">
                    <Trash2 className="w-4 h-4" />
                  </button>
                </div>

                <div className="flex items-center justify-between mt-2 pt-2 border-t border-slate-200">
                    {/* Discount Input */}
                    <div className="flex items-center space-x-2">
                         <Tag className="w-3 h-3 text-slate-400" />
                         <input 
                            type="number"
                            min="0"
                            placeholder="Discount"
                            className="w-20 text-xs p-1 border border-slate-300 rounded focus:ring-1 focus:ring-primary focus:outline-none"
                            value={item.discount || ''}
                            onChange={(e) => updateDiscount(index, parseFloat(e.target.value) || 0)}
                         />
                         {item.discount ? <span className="text-xs text-red-500">-{currencySymbol}{item.discount}</span> : null}
                    </div>

                    <div className="font-bold text-slate-800">
                        {currencySymbol}{((item.quantity * item.priceAtSale) - (item.discount || 0)).toFixed(2)}
                    </div>
                </div>
              </div>
            ))
          )}
        </div>

        <div className="p-6 bg-slate-50 border-t border-slate-200 rounded-b-xl">
          <div className="flex justify-between items-center mb-6">
            <span className="text-slate-500 font-medium">Total Amount</span>
            <span className="text-3xl font-bold text-slate-900">{currencySymbol}{cartTotal.toFixed(2)}</span>
          </div>

          <button 
            onClick={handleCheckout}
            disabled={cart.length === 0}
            className="w-full py-4 bg-green-600 text-white font-bold rounded-xl shadow-lg hover:bg-green-700 transition-transform active:scale-95 disabled:opacity-50 disabled:cursor-not-allowed flex items-center justify-center"
          >
            <CheckCircle className="w-6 h-6 mr-2" />
            Complete Sale
          </button>

          {successMsg && (
             <div className="mt-4 p-3 bg-green-100 text-green-800 text-center rounded-lg text-sm font-medium animate-pulse">
               {successMsg}
             </div>
          )}
        </div>
      </div>
    </div>
  );
};

// Helper to calculate total quantity of an item already in cart
const itemInCartTotal = (cart: SaleItem[], itemId: string): number => {
    return cart.filter(i => i.itemId === itemId).reduce((acc, i) => acc + i.quantity, 0);
};

import React, { useState, useMemo } from 'react';
import { InventoryItem, UserRole, AuditLog } from '../types';
import { Plus, Search, Edit2, Trash2, AlertCircle, Check, ClipboardEdit, X, History as HistoryIcon, User, Clock } from 'lucide-react';

interface InventoryManagerProps {
  inventory: InventoryItem[];
  onAdd: (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => void;
  onUpdate: (id: string, item: Partial<InventoryItem>) => void;
  onDelete: (id: string) => void;
  currencySymbol: string;
  userRole: UserRole;
  auditLogs: AuditLog[];
}

export const InventoryManager: React.FC<InventoryManagerProps> = ({ inventory, onAdd, onUpdate, onDelete, currencySymbol, userRole, auditLogs }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Edit/Add Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Stock Adjust Modal State
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [adjustItem, setAdjustItem] = useState<InventoryItem | null>(null);
  const [adjustQty, setAdjustQty] = useState<string>('');
  const [adjustmentType, setAdjustmentType] = useState<'add' | 'remove' | 'set'>('add');

  // History Modal State
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [historyItem, setHistoryItem] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    quantity: 0,
    costPrice: 0,
    salesPrice: 0,
    lowStockThreshold: 5
  });

  const categories = useMemo(() => {
    return Array.from(new Set(inventory.map(i => i.category))).sort();
  }, [inventory]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [inventory, searchTerm]);

  // Filter logs for the specific item in the history modal
  const itemLogs = useMemo(() => {
    if (!historyItem) return [];
    return auditLogs.filter(log => log.itemId === historyItem.id).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [auditLogs, historyItem]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate(editingId, formData);
    } else {
      onAdd(formData);
    }
    resetForm();
  };

  const handleEdit = (item: InventoryItem) => {
    setEditingId(item.id);
    setFormData({
      name: item.name,
      category: item.category,
      quantity: item.quantity,
      costPrice: item.costPrice,
      salesPrice: item.salesPrice,
      lowStockThreshold: item.lowStockThreshold
    });
    setIsModalOpen(true);
  };

  const resetForm = () => {
    setFormData({
      name: '',
      category: '',
      quantity: 0,
      costPrice: 0,
      salesPrice: 0,
      lowStockThreshold: 5
    });
    setEditingId(null);
    setIsModalOpen(false);
  };

  // Stock Adjustment Handlers
  const openAdjustModal = (item: InventoryItem) => {
    setAdjustItem(item);
    setAdjustQty('');
    setAdjustmentType('add');
    setIsAdjustModalOpen(true);
  };

  const closeAdjustModal = () => {
    setAdjustItem(null);
    setAdjustQty('');
    setIsAdjustModalOpen(false);
  };

  const openHistoryModal = (item: InventoryItem) => {
    setHistoryItem(item);
    setIsHistoryModalOpen(true);
  };

  const closeHistoryModal = () => {
    setHistoryItem(null);
    setIsHistoryModalOpen(false);
  };

  const getResultingQty = () => {
    if (!adjustItem) return 0;
    const current = adjustItem.quantity;
    const input = parseInt(adjustQty) || 0;

    if (adjustmentType === 'add') return current + input;
    if (adjustmentType === 'remove') return Math.max(0, current - input);
    return input; // set
  };

  const handleStockAdjustment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!adjustItem) return;

    const inputVal = parseInt(adjustQty);
    if (isNaN(inputVal) || inputVal < 0) {
        alert("Please enter a valid non-negative quantity.");
        return;
    }

    const finalQty = getResultingQty();

    let message = '';
    if (adjustmentType === 'add') message = `Confirm adding ${inputVal} units to ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else if (adjustmentType === 'remove') message = `Confirm removing ${inputVal} units from ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else message = `Confirm setting stock for ${adjustItem.name} to ${finalQty}?`;

    if (window.confirm(message)) {
        onUpdate(adjustItem.id, { quantity: finalQty });
        closeAdjustModal();
    }
  };

  const getLogBadgeColor = (action: string) => {
    switch (action) {
        case 'create': return 'bg-blue-100 text-blue-800 border-blue-200';
        case 'restock': return 'bg-green-100 text-green-800 border-green-200';
        case 'adjustment': return 'bg-purple-100 text-purple-800 border-purple-200';
        case 'sale': return 'bg-red-100 text-red-800 border-red-200';
        case 'update': return 'bg-orange-100 text-orange-800 border-orange-200';
        default: return 'bg-slate-100 text-slate-800 border-slate-200';
    }
  };

  return (
    <div className="space-y-6">
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
        <div className="relative w-full sm:w-96">
          <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
            <Search className="h-5 w-5 text-slate-400" />
          </div>
          <input
            type="text"
            className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary sm:text-sm transition duration-150 ease-in-out"
            placeholder="Search products or categories..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
        {userRole === 'admin' && (
          <button
            onClick={() => setIsModalOpen(true)}
            className="flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-lg text-white bg-primary hover:bg-blue-800 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary shadow-sm"
          >
            <Plus className="h-5 w-5 mr-2" />
            Add Product
          </button>
        )}
      </div>

      <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
        <div className="overflow-x-auto">
          <table className="min-w-full divide-y divide-slate-200">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Product</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Category</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Stock</th>
                <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Pricing</th>
                {userRole === 'admin' && (
                  <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Actions</th>
                )}
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-slate-200">
              {filteredInventory.map((item) => (
                <tr key={item.id} className="hover:bg-slate-50 transition-colors">
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="h-10 w-10 rounded-lg bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold text-lg">
                        {item.name.charAt(0).toUpperCase()}
                      </div>
                      <div className="ml-4">
                        <div className="text-sm font-medium text-slate-900">{item.name}</div>
                      </div>
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className="px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-slate-100 text-slate-800">
                      {item.category}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <span className={`text-sm font-medium ${item.quantity <= item.lowStockThreshold ? 'text-red-600' : 'text-slate-900'}`}>
                        {item.quantity} Units
                      </span>
                      {item.quantity <= item.lowStockThreshold && (
                        <AlertCircle className="w-4 h-4 text-red-600 ml-2" />
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">
                    <div className="flex flex-col">
                      <span className="text-slate-900 font-medium">Sell: {currencySymbol}{item.salesPrice.toFixed(2)}</span>
                      {userRole === 'admin' && (
                        <span className="text-xs">Cost: {currencySymbol}{item.costPrice.toFixed(2)}</span>
                      )}
                    </div>
                  </td>
                  {userRole === 'admin' && (
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      <div className="flex items-center justify-end space-x-3">
                          <button 
                              onClick={() => openHistoryModal(item)} 
                              className="text-slate-400 hover:text-blue-600 transition-colors"
                              title="View Audit Trail"
                          >
                            <HistoryIcon className="w-5 h-5" />
                          </button>
                          <button 
                              onClick={() => openAdjustModal(item)} 
                              className="text-slate-400 hover:text-indigo-600 transition-colors"
                              title="Adjust Stock"
                          >
                            <ClipboardEdit className="w-5 h-5" />
                          </button>
                          <button onClick={() => handleEdit(item)} className="text-slate-400 hover:text-indigo-600 transition-colors" title="Edit Details">
                            <Edit2 className="w-5 h-5" />
                          </button>
                          <button onClick={() => onDelete(item.id)} className="text-slate-400 hover:text-red-600 transition-colors" title="Delete Product">
                            <Trash2 className="w-5 h-5" />
                          </button>
                      </div>
                    </td>
                  )}
                </tr>
              ))}
              {filteredInventory.length === 0 && (
                <tr>
                  <td colSpan={userRole === 'admin' ? 5 : 4} className="px-6 py-12 text-center text-slate-500">
                    No products found.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* Product Form Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
          <div className="bg-white rounded-2xl shadow-xl w-full max-w-lg overflow-hidden transform transition-all">
            <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
              <h3 className="text-lg font-bold text-slate-800">
                {editingId ? 'Edit Product' : 'Add New Product'}
              </h3>
              <button onClick={resetForm} className="text-slate-400 hover:text-slate-600">
                <span className="text-2xl">&times;</span>
              </button>
            </div>
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Product Name</label>
                <input
                  type="text"
                  required
                  className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1">Category</label>
                <input
                  type="text"
                  required
                  list="category-options"
                  className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                  value={formData.category}
                  onChange={(e) => setFormData({ ...formData, category: e.target.value })}
                  placeholder="Type or select a category"
                />
                <datalist id="category-options">
                  {categories.map((cat) => (
                    <option key={cat} value={cat} />
                  ))}
                </datalist>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Cost Price ({currencySymbol})</label>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.costPrice}
                    onChange={(e) => setFormData({ ...formData, costPrice: parseFloat(e.target.value) })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Sales Price ({currencySymbol})</label>
                  <input
                    type="number"
                    min="0"
                    step="0.01"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.salesPrice}
                    onChange={(e) => setFormData({ ...formData, salesPrice: parseFloat(e.target.value) })}
                  />
                </div>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Initial Stock</label>
                  <input
                    type="number"
                    min="0"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.quantity}
                    onChange={(e) => setFormData({ ...formData, quantity: parseInt(e.target.value) || 0 })}
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium text-slate-700 mb-1">Low Stock Alert Level</label>
                  <input
                    type="number"
                    min="0"
                    required
                    className="w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                    value={formData.lowStockThreshold}
                    onChange={(e) => setFormData({ ...formData, lowStockThreshold: parseInt(e.target.value) || 0 })}
                  />
                </div>
              </div>

              <div className="pt-4 flex justify-end space-x-3">
                <button
                  type="button"
                  onClick={resetForm}
                  className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors"
                >
                  Cancel
                </button>
                <button
                  type="submit"
                  className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-blue-800 transition-colors flex items-center"
                >
                  <Check className="w-4 h-4 mr-2" />
                  {editingId ? 'Update Product' : 'Save Product'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Stock Adjustment Modal */}
      {isAdjustModalOpen && adjustItem && (
        <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
             <div className="bg-white rounded-2xl shadow-xl w-full max-w-md overflow-hidden transform transition-all animate-fade-in">
                 <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <h3 className="text-lg font-bold text-slate-800 flex items-center">
                        <ClipboardEdit className="w-5 h-5 mr-2 text-primary" />
                        Adjust Stock
                    </h3>
                    <button onClick={closeAdjustModal} className="text-slate-400 hover:text-slate-600">
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <form onSubmit={handleStockAdjustment} className="p-6">
                    <div className="mb-6 bg-slate-50 p-4 rounded-lg border border-slate-100">
                        <div className="text-sm text-slate-500 mb-1">Product</div>
                        <div className="text-lg font-bold text-slate-800">{adjustItem.name}</div>
                        <div className="text-sm text-slate-500 mt-1">Current Stock: <span className="font-bold text-slate-800">{adjustItem.quantity}</span></div>
                    </div>

                    <div className="mb-6">
                        <label className="block text-sm font-medium text-slate-700 mb-2">Action</label>
                        <div className="flex bg-slate-100 p-1 rounded-lg">
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('add')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'add' ? 'bg-white text-green-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Add (+)
                            </button>
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('remove')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'remove' ? 'bg-white text-red-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Remove (-)
                            </button>
                            <button
                                type="button"
                                onClick={() => setAdjustmentType('set')}
                                className={`flex-1 py-2 text-sm font-medium rounded-md transition-all ${adjustmentType === 'set' ? 'bg-white text-blue-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'}`}
                            >
                                Set Total
                            </button>
                        </div>
                    </div>

                    <div className="mb-6">
                        <label className="block text-sm font-medium text-slate-700 mb-2">
                            {adjustmentType === 'set' ? 'New Total Quantity' : 'Quantity to ' + (adjustmentType === 'add' ? 'Add' : 'Remove')}
                        </label>
                        <input
                            type="number"
                            min="0"
                            required
                            autoFocus
                            className="block w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-3 border text-lg"
                            value={adjustQty}
                            onChange={(e) => setAdjustQty(e.target.value)}
                            placeholder="0"
                        />
                    </div>

                    <div className="flex justify-between items-center py-3 px-4 bg-slate-50 rounded-lg border border-slate-100 mb-6">
                        <span className="text-sm text-slate-500">Resulting Stock:</span>
                        <span className={`text-lg font-bold ${getResultingQty() < (adjustItem.lowStockThreshold || 0) ? 'text-red-600' : 'text-slate-800'}`}>
                            {getResultingQty()}
                        </span>
                    </div>

                    <div className="flex justify-end space-x-3">
                        <button
                            type="button"
                            onClick={closeAdjustModal}
                            className="px-4 py-2 bg-slate-100 text-slate-700 rounded-lg hover:bg-slate-200 transition-colors font-medium"
                        >
                            Cancel
                        </button>
                        <button
                            type="submit"
                            className="px-4 py-2 bg-primary text-white rounded-lg hover:bg-blue-800 transition-colors font-medium"
                        >
                            Confirm Change
                        </button>
                    </div>
                </form>
             </div>
        </div>
      )}

      {/* Audit Log / History Modal */}
      {isHistoryModalOpen && historyItem && (
          <div className="fixed inset-0 z-50 overflow-y-auto bg-black bg-opacity-50 flex items-center justify-center p-4 backdrop-blur-sm">
            <div className="bg-white rounded-2xl shadow-xl w-full max-w-2xl overflow-hidden animate-fade-in flex flex-col max-h-[80vh]">
                <div className="px-6 py-4 border-b border-slate-100 flex justify-between items-center bg-slate-50">
                    <div>
                        <h3 className="text-lg font-bold text-slate-800 flex items-center">
                            <HistoryIcon className="w-5 h-5 mr-2 text-primary" />
                            Audit Trail
                        </h3>
                        <p className="text-sm text-slate-500">{historyItem.name} ({historyItem.category})</p>
                    </div>
                    <button onClick={closeHistoryModal} className="text-slate-400 hover:text-slate-600">
                        <X className="w-6 h-6" />
                    </button>
                </div>

                <div className="p-0 overflow-y-auto flex-1">
                    {itemLogs.length > 0 ? (
                        <div className="divide-y divide-slate-100">
                            {itemLogs.map((log) => (
                                <div key={log.id} className="p-4 hover:bg-slate-50 transition-colors">
                                    <div className="flex justify-between items-start mb-1">
                                        <div className="flex items-center">
                                            <span className={`px-2 py-0.5 text-xs font-bold rounded border uppercase ${getLogBadgeColor(log.action)}`}>
                                                {log.action}
                                            </span>
                                            <span className="text-xs text-slate-400 ml-3 flex items-center">
                                                <Clock className="w-3 h-3 mr-1" />
                                                {new Date(log.timestamp).toLocaleString()}
                                            </span>
                                        </div>
                                    </div>
                                    <p className="text-slate-800 text-sm font-medium mt-1">{log.details}</p>
                                    <div className="mt-2 flex items-center text-xs text-slate-500">
                                        <User className="w-3 h-3 mr-1" />
                                        {log.userId}
                                    </div>
                                </div>
                            ))}
                        </div>
                    ) : (
                        <div className="flex flex-col items-center justify-center py-12 text-slate-400">
                            <HistoryIcon className="w-12 h-12 mb-2 opacity-20" />
                            <p>No history records found for this item.</p>
                        </div>
                    )}
                </div>

                <div className="bg-slate-50 px-6 py-3 border-t border-slate-200 flex justify-end">
                    <button 
                        onClick={closeHistoryModal}
                        className="px-4 py-2 bg-white border border-slate-300 rounded-lg text-slate-700 hover:bg-slate-100 text-sm font-medium shadow-sm transition-colors"
                    >
                        Close
                    </button>
                </div>
            </div>
          </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { InventoryItem, PurchaseOrder, PurchaseOrderItem } from '../types';
import { Plus, Search, Truck, CheckCircle, XCircle, FileText, ChevronRight, AlertCircle } from 'lucide-react';

interface PurchaseOrdersManagerProps {
  inventory: InventoryItem[];
  purchaseOrders: PurchaseOrder[];
  onCreateOrder: (order: Omit<PurchaseOrder, 'id'>) => void;
  onUpdateStatus: (id: string, status: 'received' | 'cancelled') => void;
  currencySymbol: string;
}

export const PurchaseOrdersManager: React.FC<PurchaseOrdersManagerProps> = ({ 
  inventory, 
  purchaseOrders, 
  onCreateOrder, 
  onUpdateStatus, 
  currencySymbol 
}) => {
  const [viewMode, setViewMode] = useState<'list' | 'create'>('list');
  const [searchTerm, setSearchTerm] = useState('');

  // Create Form State
  const [supplier, setSupplier] = useState('');
  const [notes, setNotes] = useState('');
  const [orderItems, setOrderItems] = useState<PurchaseOrderItem[]>([]);
  const [itemSearch, setItemSearch] = useState('');

  // Selected item for adding to order
  const [selectedInventoryItem, setSelectedInventoryItem] = useState<InventoryItem | null>(null);
  const [addQty, setAddQty] = useState<number>(1);
  const [addCost, setAddCost] = useState<number>(0);

  const filteredOrders = useMemo(() => {
    return purchaseOrders.filter(po => 
      po.supplier.toLowerCase().includes(searchTerm.toLowerCase()) || 
      po.id.toLowerCase().includes(searchTerm.toLowerCase())
    ).sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
  }, [purchaseOrders, searchTerm]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(i => i.name.toLowerCase().includes(itemSearch.toLowerCase()));
  }, [inventory, itemSearch]);

  const handleAddItem = () => {
    if (!selectedInventoryItem) return;

    const newItem: PurchaseOrderItem = {
      itemId: selectedInventoryItem.id,
      name: selectedInventoryItem.name,
      quantity: addQty,
      unitCost: addCost
    };

    setOrderItems([...orderItems, newItem]);

    // Reset selection
    setSelectedInventoryItem(null);
    setAddQty(1);
    setAddCost(0);
    setItemSearch('');
  };

  const handleRemoveItem = (index: number) => {
    const newItems = [...orderItems];
    newItems.splice(index, 1);
    setOrderItems(newItems);
  };

  const handleSubmitOrder = () => {
    if (!supplier || orderItems.length === 0) {
      alert("Please provide a supplier name and add at least one item.");
      return;
    }

    const totalCost = orderItems.reduce((acc, item) => acc + (item.quantity * item.unitCost), 0);

    onCreateOrder({
      supplier,
      date: new Date().toISOString(),
      status: 'ordered',
      items: orderItems,
      totalCost,
      notes
    });

    // Reset Form
    setSupplier('');
    setNotes('');
    setOrderItems([]);
    setViewMode('list');
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'received': return 'bg-green-100 text-green-800 border-green-200';
      case 'cancelled': return 'bg-red-100 text-red-800 border-red-200';
      default: return 'bg-yellow-100 text-yellow-800 border-yellow-200';
    }
  };

  return (
    <div className="space-y-6 animate-fade-in">
      {viewMode === 'list' ? (
        <>
          <div className="flex flex-col sm:flex-row justify-between items-center gap-4">
            <div className="relative w-full sm:w-96">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <Search className="h-5 w-5 text-slate-400" />
              </div>
              <input
                type="text"
                className="block w-full pl-10 pr-3 py-2 border border-slate-300 rounded-lg leading-5 bg-white placeholder-slate-500 focus:outline-none focus:ring-2 focus:ring-primary focus:border-primary sm:text-sm transition duration-150 ease-in-out"
                placeholder="Search supplier or order ID..."
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <button
              onClick={() => setViewMode('create')}
              className="flex items-center justify-center px-4 py-2 border border-transparent text-sm font-medium rounded-lg text-white bg-primary hover:bg-blue-800 focus:outline-none shadow-sm transition-colors"
            >
              <Plus className="h-5 w-5 mr-2" />
              New Purchase Order
            </button>
          </div>

          <div className="bg-white rounded-xl shadow-sm border border-slate-200 overflow-hidden">
            <table className="min-w-full divide-y divide-slate-200">
              <thead className="bg-slate-50">
                <tr>
                  <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Date</th>
                  <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Supplier</th>
                  <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Items</th>
                  <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Total Cost</th>
                  <th className="px-6 py-3 text-left text-xs font-bold text-slate-500 uppercase tracking-wider">Status</th>
                  <th className="px-6 py-3 text-right text-xs font-bold text-slate-500 uppercase tracking-wider">Actions</th>
                </tr>
              </thead>
              <tbody className="divide-y divide-slate-200 bg-white">
                {filteredOrders.map((po) => (
                  <tr key={po.id} className="hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4 whitespace-nowrap text-sm text-slate-500">
                      {new Date(po.date).toLocaleDateString()}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-medium text-slate-900">
                      {po.supplier}
                    </td>
                    <td className="px-6 py-4 text-sm text-slate-500">
                       <div className="max-w-xs truncate">
                         {po.items.map(i => `${i.quantity}x ${i.name}`).join(', ')}
                       </div>
                       <div className="text-xs text-slate-400 mt-1">{po.items.length} items</div>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-sm font-bold text-slate-800">
                      {currencySymbol}{po.totalCost.toLocaleString(undefined, { minimumFractionDigits: 2 })}
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap">
                      <span className={`px-2 py-1 inline-flex text-xs leading-5 font-semibold rounded-full border ${getStatusColor(po.status)}`}>
                        {po.status.toUpperCase()}
                      </span>
                    </td>
                    <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium">
                      {po.status === 'ordered' && (
                        <div className="flex justify-end space-x-2">
                           <button 
                             onClick={() => {
                               if(window.confirm(`Confirm receipt of goods from ${po.supplier}? This will update inventory stocks.`)) {
                                 onUpdateStatus(po.id, 'received');
                               }
                             }}
                             className="text-green-600 hover:text-green-900 bg-green-50 hover:bg-green-100 px-3 py-1 rounded-md transition-colors flex items-center"
                           >
                             <CheckCircle className="w-4 h-4 mr-1" /> Receive
                           </button>
                           <button 
                             onClick={() => {
                               if(window.confirm('Cancel this order?')) {
                                 onUpdateStatus(po.id, 'cancelled');
                               }
                             }}
                             className="text-red-600 hover:text-red-900 bg-red-50 hover:bg-red-100 px-3 py-1 rounded-md transition-colors flex items-center"
                           >
                             <XCircle className="w-4 h-4 mr-1" /> Cancel
                           </button>
                        </div>
                      )}
                      {po.status !== 'ordered' && (
                        <span className="text-slate-400 text-xs italic">Completed</span>
                      )}
                    </td>
                  </tr>
                ))}
                {filteredOrders.length === 0 && (
                  <tr>
                    <td colSpan={6} className="px-6 py-12 text-center text-slate-500">
                      <Truck className="w-12 h-12 mx-auto text-slate-300 mb-2" />
                      <p>No purchase orders found. Create one to restock inventory.</p>
                    </td>
                  </tr>
                )}
              </tbody>
            </table>
          </div>
        </>
      ) : (
        // Create Mode
        <div className="max-w-4xl mx-auto bg-white rounded-xl shadow-lg border border-slate-200 overflow-hidden">
            <div className="bg-slate-50 px-6 py-4 border-b border-slate-200 flex justify-between items-center">
                <h2 className="text-lg font-bold text-slate-800 flex items-center">
                    <Truck className="w-5 h-5 mr-2 text-primary" />
                    Create Purchase Order
                </h2>
                <button onClick={() => setViewMode('list')} className="text-slate-500 hover:text-slate-700 text-sm">
                    Cancel
                </button>
            </div>

            <div className="p-6 grid grid-cols-1 md:grid-cols-2 gap-8">
                {/* Left: Supplier & Order Items */}
                <div className="space-y-6">
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Supplier Name</label>
                        <input
                            type="text"
                            className="block w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                            placeholder="e.g. Accra Wholesalers Ltd"
                            value={supplier}
                            onChange={(e) => setSupplier(e.target.value)}
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium text-slate-700 mb-1">Notes (Optional)</label>
                        <textarea
                            className="block w-full border-slate-300 rounded-lg shadow-sm focus:ring-primary focus:border-primary p-2 border"
                            rows={2}
                            value={notes}
                            onChange={(e) => setNotes(e.target.value)}
                        />
                    </div>

                    <div className="border-t border-slate-200 pt-6">
                        <h3 className="font-medium text-slate-800 mb-3">Add Items to Order</h3>

                        {!selectedInventoryItem ? (
                             <div className="relative">
                                <Search className="absolute left-3 top-3 h-4 w-4 text-slate-400" />
                                <input
                                    type="text"
                                    className="block w-full pl-9 pr-3 py-2 border border-slate-300 rounded-lg text-sm focus:ring-primary focus:border-primary"
                                    placeholder="Search inventory to order..."
                                    value={itemSearch}
                                    onChange={(e) => setItemSearch(e.target.value)}
                                />
                                {itemSearch && (
                                    <div className="absolute z-10 w-full mt-1 bg-white border border-slate-200 rounded-lg shadow-lg max-h-60 overflow-y-auto">
                                        {filteredInventory.length > 0 ? (
                                            filteredInventory.map(item => (
                                                <div 
                                                    key={item.id}
                                                    className="px-4 py-2 hover:bg-slate-50 cursor-pointer text-sm flex justify-between items-center"
                                                    onClick={() => {
                                                        setSelectedInventoryItem(item);
                                                        setAddCost(item.costPrice); // Default to current cost
                                                        setItemSearch('');
                                                    }}
                                                >
                                                    <span className="font-medium text-slate-700">{item.name}</span>
                                                    <span className="text-slate-400 text-xs">Current Stock: {item.quantity}</span>
                                                </div>
                                            ))
                                        ) : (
                                            <div className="px-4 py-2 text-sm text-slate-500">No items found</div>
                                        )}
                                    </div>
                                )}
                             </div>
                        ) : (
                            <div className="bg-blue-50 p-4 rounded-lg border border-blue-100">
                                <div className="flex justify-between items-start mb-3">
                                    <span className="font-bold text-blue-900">{selectedInventoryItem.name}</span>
                                    <button onClick={() => setSelectedInventoryItem(null)} className="text-blue-400 hover:text-blue-600">
                                        <span className="text-xl">&times;</span>
                                    </button>
                                </div>
                                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4 mb-3">
                                    <div>
                                        <label className="block text-xs font-medium text-blue-800 mb-1">Quantity</label>
                                        <input 
                                            type="number" 
                                            min="1"
                                            className="block w-full border-blue-200 rounded-md text-sm p-1.5 focus:ring-blue-500 focus:border-blue-500"
                                            value={addQty}
                                            onChange={(e) => setAddQty(parseInt(e.target.value) || 0)}
                                        />
                                    </div>
                                    <div>
                                        <label className="block text-xs font-medium text-blue-800 mb-1">Unit Cost ({currencySymbol})</label>
                                        <input 
                                            type="number" 
                                            min="0"
                                            step="0.01"
                                            className="block w-full border-blue-200 rounded-md text-sm p-1.5 focus:ring-blue-500 focus:border-blue-500"
                                            value={addCost}
                                            onChange={(e) => setAddCost(parseFloat(e.target.value) || 0)}
                                        />
                                    </div>
                                </div>
                                <button 
                                    onClick={handleAddItem}
                                    className="w-full bg-blue-600 text-white text-sm font-medium py-2 rounded-lg hover:bg-blue-700 transition-colors"
                                >
                                    Add to List
                                </button>
                            </div>
                        )}
                    </div>
                </div>

                {/* Right: Order Summary */}
                <div className="bg-slate-50 rounded-xl p-6 border border-slate-200 flex flex-col h-full">
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center">
                        <FileText className="w-5 h-5 mr-2 text-slate-500" />
                        Order Summary
                    </h3>

                    <div className="flex-1 overflow-y-auto mb-4 space-y-2">
                        {orderItems.length === 0 ? (
                            <div className="text-center text-slate-400 text-sm py-8">
                                No items added yet.
                            </div>
                        ) : (
                            orderItems.map((item, idx) => (
                                <div key={idx} className="bg-white p-3 rounded-lg border border-slate-200 flex justify-between items-center shadow-sm">
                                    <div>
                                        <div className="font-medium text-slate-800 text-sm">{item.name}</div>
                                        <div className="text-xs text-slate-500">{item.quantity} x {currencySymbol}{item.unitCost.toFixed(2)}</div>
                                    </div>
                                    <div className="flex items-center">
                                        <span className="font-bold text-slate-700 text-sm mr-3">
                                            {currencySymbol}{(item.quantity * item.unitCost).toFixed(2)}
                                        </span>
                                        <button onClick={() => handleRemoveItem(idx)} className="text-slate-300 hover:text-red-500">
                                            <span className="text-lg">&times;</span>
                                        </button>
                                    </div>
                                </div>
                            ))
                        )}
                    </div>

                    <div className="border-t border-slate-200 pt-4 mt-auto">
                        <div className="flex justify-between items-center mb-6">
                            <span className="text-slate-600 font-medium">Total Cost</span>
                            <span className="text-2xl font-bold text-slate-900">
                                {currencySymbol}
                                {orderItems.reduce((acc, item) => acc + (item.quantity * item.unitCost), 0).toLocaleString(undefined, { minimumFractionDigits: 2 })}
                            </span>
                        </div>
                        <button 
                            onClick={handleSubmitOrder}
                            disabled={orderItems.length === 0}
                            className="w-full py-3 bg-primary text-white font-bold rounded-lg hover:bg-blue-800 shadow-md transition-colors flex items-center justify-center disabled:opacity-50 disabled:cursor-not-allowed"
                        >
                            Place Order <ChevronRight className="w-5 h-5 ml-1" />
                        </button>
                    </div>
                </div>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo } from 'react';
import { InventoryItem, UserRole, AuditLog } from '../types';
import { Plus, Search, Edit2, Trash2, AlertCircle, Check, ClipboardEdit, X, History as HistoryIcon, User, Clock, ChevronDown, ChevronUp } from 'lucide-react';

interface InventoryManagerProps {
  inventory: InventoryItem[];
  onAdd: (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => void;
  onUpdate: (id: string, item: Partial<InventoryItem>) => void;
  onDelete: (id: string) => void;
  currencySymbol: string;
  userRole: UserRole;
  auditLogs: AuditLog[];
}

export const InventoryManager: React.FC<InventoryManagerProps> = ({ inventory, onAdd, onUpdate, onDelete, currencySymbol, userRole, auditLogs }) => {
  const [searchTerm, setSearchTerm] = useState('');

  // Edit/Add Modal State
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingId, setEditingId] = useState<string | null>(null);

  // Stock Adjust Modal State
  const [isAdjustModalOpen, setIsAdjustModalOpen] = useState(false);
  const [adjustItem, setAdjustItem] = useState<InventoryItem | null>(null);
  const [adjustQty, setAdjustQty] = useState<string>('');
  const [adjustmentType, setAdjustmentType] = useState<'add' | 'remove' | 'set'>('add');

  // History Modal State
  const [isHistoryModalOpen, setIsHistoryModalOpen] = useState(false);
  const [historyItem, setHistoryItem] = useState<InventoryItem | null>(null);

  // Form State
  const [formData, setFormData] = useState({
    name: '',
    category: '',
    quantity: 0,
    costPrice: 0,
    salesPrice: 0,
    lowStockThreshold: 5
  });

  const categories = useMemo(() => {
    return Array.from(new Set(inventory.map(i => i.category))).sort();
  }, [inventory]);

  const filteredInventory = useMemo(() => {
    return inventory.filter(item => 
      item.name.toLowerCase().includes(searchTerm.toLowerCase()) || 
      item.category.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [inventory, searchTerm]);

  // Filter logs for the specific item in the history modal
  const itemLogs = useMemo(() => {
    if (!historyItem) return [];
    return auditLogs.filter(log => log.itemId === historyItem.id).sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime());
  }, [auditLogs, historyItem]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      onUpdate(editingId, formData);
    } else {
      onAdd(formData);
    }
    resetForm();
  };

  const handleEdit = (item: InventoryItem) => {
    setEditingId(item.id);
    setFormData({
      name: item.name,
      category: item.category,
      quantity: item.quantity,
      costPrice: item.costPrice,
      salesPrice: item.salesPrice,
      lowStockThreshold: item.lowStockThreshold
    });
    setIsModalOpen(true);
  };

  const resetForm = () => {
    setFormData({
      name: '',
      category: '',
      quantity: 0,
      costPrice: 0,
      salesPrice: 0,
      lowStockThreshold: 5
    });
    setEditingId(null);
    setIsModalOpen(false);
  };

  // Stock Adjustment Handlers
  const openAdjustModal = (item: InventoryItem) => {
    setAdjustItem(item);
    setAdjustQty('');
    setAdjustmentType('add');
    setIsAdjustModalOpen(true);
  };

  const closeAdjustModal = () => {
    setAdjustItem(null);
    setAdjustQty('');
    setIsAdjustModalOpen(false);
  };

  const openHistoryModal = (item: InventoryItem) => {
    setHistoryItem(item);
    setIsHistoryModalOpen(true);
  };

  const closeHistoryModal = () => {
    setHistoryItem(null);
    setIsHistoryModalOpen(false);
  };

  const getResultingQty = () => {
    if (!adjustItem) return 0;
    const current = adjustItem.quantity;
    const input = parseInt(adjustQty) || 0;

    if (adjustmentType === 'add') return current + input;
    if (adjustmentType === 'remove') return Math.max(0, current - input);
    return input; // set
  };

  const handleStockAdjustment = (e: React.FormEvent) => {
    e.preventDefault();
    if (!adjustItem) return;

    const inputVal = parseInt(adjustQty);
    if (isNaN(inputVal) || inputVal < 0) {
        alert("Please enter a valid non-negative quantity.");
        return;
    }

    const finalQty = getResultingQty();

    let message = '';
    if (adjustmentType === 'add') message = `Confirm adding ${inputVal} units to ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else if (adjustmentType === 'remove') message = `Confirm removing ${inputVal} units from ${adjustItem.name}?\nNew Total: ${finalQty}`;
    else message = `Confirm setting stock for ${adjustItem.name} to ${finalQty}?`;

    if (window.confirm(message)) {
        onUpdate(adjustItem.id, { quantity: finalQty });
        closeAdjustModal();
    }
  };

