import React, { useState, useEffect, useMemo, useRef } from 'react';
import { InventoryItem, SaleRecord } from '../types';
import { Search, Network, Zap, Activity, Filter, Maximize2, Share2, Target, Clock, AlertTriangle } from 'lucide-react';
import { ScatterChart, Scatter, XAxis, YAxis, ZAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DeepAnalyticsProps {
  inventory: InventoryItem[];
  sales: SaleRecord[];
  currencySymbol: string;
}

// Graph Types
interface Node {
  id: string;
  label: string;
  type: 'category' | 'product' | 'sale';
  value: number; // For sizing
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  data?: any;
}

interface Link {
  source: string;
  target: string;
  value: number;
}

export const DeepAnalytics: React.FC<DeepAnalyticsProps> = ({ inventory, sales, currencySymbol }) => {
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // --- SIGNAL DETECTION ---
  const signals = useMemo(() => {
    const alerts: { id: string; type: 'critical' | 'warning' | 'info'; message: string; timestamp: string }[] = [];

    // 1. High Discount Anomaly
    sales.forEach(sale => {
      const discountRatio = sale.items.reduce((acc, i) => acc + (i.discount || 0), 0) / (sale.totalAmount + 1); // +1 to avoid div0
      if (discountRatio > 0.25) {
        alerts.push({
          id: sale.id,
          type: 'warning',
          message: `High Discount detected (${(discountRatio * 100).toFixed(0)}%) on Sale ${sale.id.slice(-6)}`,
          timestamp: sale.timestamp
        });
      }
    });

    // 2. Stock Rapid Depletion (Mock logic: Low stock items that are selling fast)
    inventory.forEach(item => {
      if (item.quantity <= item.lowStockThreshold && item.quantity > 0) {
        alerts.push({
          id: item.id,
          type: 'critical',
          message: `Critical Stock Level: ${item.name} (${item.quantity} remaining)`,
          timestamp: new Date().toISOString()
        });
      }
    });

    return alerts.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);
  }, [sales, inventory]);

  // --- KNOWLEDGE GRAPH ENGINE ---
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [nodes, setNodes] = useState<Node[]>([]);
  const [links, setLinks] = useState<Link[]>([]);

  // Initialize Graph Data
  useEffect(() => {
    const newNodes: Node[] = [];
    const newLinks: Link[] = [];

    // 1. Category Nodes (Hubs)
    const categories = Array.from(new Set(inventory.map(i => i.category)));
    categories.forEach(cat => {
      newNodes.push({ id: `cat-${cat}`, label: cat, type: 'category', value: 20 });
    });

    // 2. Product Nodes
    // Limit to top 50 items by value to keep graph performant
    const topItems = [...inventory].sort((a, b) => (b.salesPrice * b.quantity) - (a.salesPrice * a.quantity)).slice(0, 50);
    topItems.forEach(item => {
      newNodes.push({ id: item.id, label: item.name, type: 'product', value: 10, data: item });
      // Link to Category
      newLinks.push({ source: item.id, target: `cat-${item.category}`, value: 1 });
    });

    // 3. Recent Big Sales (Context)
    // Find sales > avg value
    const avgSale = sales.reduce((acc, s) => acc + s.totalAmount, 0) / (sales.length || 1);
    const bigSales = sales.filter(s => s.totalAmount > avgSale * 1.5).slice(0, 10); // Top 10 recent big sales

    bigSales.forEach(sale => {
      newNodes.push({ id: sale.id, label: `Sale ${currencySymbol}${sale.totalAmount.toFixed(0)}`, type: 'sale', value: 15, data: sale });
      // Link Sale to Items involved
      sale.items.forEach(saleItem => {
        // Only link if item node exists in our graph
        if (newNodes.find(n => n.id === saleItem.itemId)) {
           newLinks.push({ source: sale.id, target: saleItem.itemId, value: 2 });
        }
      });
    });

    setNodes(newNodes.map(n => ({...n, x: Math.random() * 800, y: Math.random() * 600, vx: 0, vy: 0})));
    setLinks(newLinks);
  }, [inventory, sales, currencySymbol]);

  // Force Directed Simulation (Custom Implementation)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const simulate = () => {
      const width = canvas.width;
      const height = canvas.height;
      const center = { x: width / 2, y: height / 2 };

      // Physics Constants
      const k = 0.05; // Spring constant
      const repulsion = 500;
      const damping = 0.9;

      // 1. Apply Forces
      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        if (!node.x || !node.y) continue;

        let fx = 0, fy = 0;

        // Repulsion (Coulomb's Law-ish)
        for (let j = 0; j < nodes.length; j++) {
            if (i === j) continue;
            const other = nodes[j];
            const dx = node.x! - other.x!;
            const dy = node.y! - other.y!;
            const distSq = dx * dx + dy * dy;
            if (distSq > 0.1) {
                const force = repulsion / Math.sqrt(distSq);
                fx += (dx / Math.sqrt(distSq)) * force;
                fy += (dy / Math.sqrt(distSq)) * force;
            }
        }

        // Attraction (Springs)
        links.forEach(link => {
             // Find source and target objects (React state might have raw IDs, need to map)
             // Simplified: assumes indices or direct matching logic isn't needed if we loop links and find nodes
             // Optimization: Map links to indices once, but for < 100 nodes, find is okay
             const sourceNode = nodes.find(n => n.id === link.source);
             const targetNode = nodes.find(n => n.id === link.target);

             if (sourceNode && targetNode && sourceNode.id === node.id) {
                 const dx = targetNode.x! - node.x!;
                 const dy = targetNode.y! - node.y!;
                 fx += dx * k;
                 fy += dy * k;
             }
             if (sourceNode && targetNode && targetNode.id === node.id) {
                 const dx = sourceNode.x! - node.x!;
                 const dy = sourceNode.y! - node.y!;
                 fx += dx * k;
                 fy += dy * k;
             }
        });

        // Center Gravity
        fx += (center.x - node.x!) * 0.015;
        fy += (center.y - node.y!) * 0.015;

        // Update Velocity & Position
        node.vx = (node.vx || 0) + fx * 0.05;
        node.vy = (node.vy || 0) + fy * 0.05;
        node.vx *= damping;
        node.vy *= damping;

        node.x! += node.vx;
        node.y! += node.vy;
      }

      // 2. Render
      ctx.clearRect(0, 0, width, height);

      // Draw Links
      ctx.strokeStyle = '#334155'; // Slate 700
      ctx.lineWidth = 1;
      links.forEach(link => {
          const s = nodes.find(n => n.id === link.source);
          const t = nodes.find(n => n.id === link.target);
          if (s && t) {
              ctx.beginPath();
              ctx.moveTo(s.x!, s.y!);
              ctx.lineTo(t.x!, t.y!);
              ctx.stroke();
          }
      });

      // Draw Nodes
      nodes.forEach(node => {
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, node.value * 0.8, 0, 2 * Math.PI);

          // Style based on type
          if (node.type === 'category') {
              ctx.fillStyle = '#0ea5e9'; // Sky Blue
              ctx.shadowColor = '#0ea5e9';
          } else if (node.type === 'product') {
              ctx.fillStyle = '#10b981'; // Emerald
              ctx.shadowColor = '#10b981';
          } else {
              ctx.fillStyle = '#f59e0b'; // Amber
              ctx.shadowColor = '#f59e0b';
          }

          // Glow effect for "War Room" feel
          ctx.shadowBlur = 10;
          ctx.fill();
          ctx.shadowBlur = 0; // Reset

          // Label (Conditional - only if large or selected)
          if (node.value > 12 || node === selectedNode) {
            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px monospace';
            ctx.fillText(node.label, node.x! + 12, node.y! + 4);
          }

          // Selection Highlight
          if (node === selectedNode) {
              ctx.strokeStyle = '#fff';
              ctx.lineWidth = 2;
              ctx.stroke();
          }
      });

      animationFrameId = requestAnimationFrame(simulate);
    };

    simulate();
    return () => cancelAnimationFrame(animationFrameId);
  }, [nodes, links, selectedNode]);

  // Handle Canvas Click for Selection
  const handleCanvasClick = (e: React.MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Find clicked node
      const clicked = nodes.find(node => {
          const dx = node.x! - x;
          const dy = node.y! - y;
          return Math.sqrt(dx*dx + dy*dy) < node.value + 5;
      });

      setSelectedNode(clicked || null);
  };

  // --- HEATMAP DATA ---
  const heatmapData = useMemo(() => {
    // 7x24 Grid. Days 0-6, Hours 0-23.
    const grid: { day: number; hour: number; count: number }[] = [];
    for(let d=0; d<7; d++) {
        for(let h=0; h<24; h++) {
            grid.push({ day: d, hour: h, count: 0 });
        }
    }

    sales.forEach(sale => {
        const date = new Date(sale.timestamp);
        const day = date.getDay();
        const hour = date.getHours();
        const cell = grid.find(c => c.day === day && c.hour === hour);
        if (cell) cell.count += sale.totalAmount; // Weight by volume
    });

    // Normalize for chart bubble size
    return grid.map(g => ({ ...g, dayName: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][g.day] }));
  }, [sales]);

  return (
    <div className="fixed inset-0 z-40 bg-slate-950 text-slate-200 font-mono overflow-hidden flex flex-col">
       {/* Top Bar */}
       <div className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md">
          <div className="flex items-center space-x-3">
             <div className="p-2 bg-blue-500/10 rounded border border-blue-500/50">
                 <Target className="w-5 h-5 text-blue-400" />
             </div>
             <div>
                <h1 className="text-lg font-bold tracking-wider text-slate-100">DEEP ANALYTICS</h1>
                <p className="text-[10px] text-slate-500 uppercase tracking-[0.2em]">Raha Soldi Intelligence</p>
             </div>
          </div>

          <div className="flex-1 max-w-xl mx-8 relative group">
             <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-600 group-focus-within:text-blue-400 transition-colors" />
             <input 
                type="text" 
                placeholder="Search entities, transaction IDs, or SKU codes..." 
                className="w-full bg-slate-900 border border-slate-700 rounded-sm py-2 pl-10 pr-4 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all placeholder-slate-600 text-slate-300"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>

          <div className="flex items-center space-x-4 text-xs">
             <div className="flex items-center text-green-400">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                SYSTEM ONLINE
             </div>
             <div className="text-slate-500">
                {new Date().toLocaleTimeString()}
             </div>
          </div>
       </div>

       {/* Main Workspace */}
       <div className="flex-1 flex overflow-hidden">

          {/* Left Panel: Signal Feed */}
          <div className="w-80 border-r border-slate-800 bg-slate-900/30 flex flex-col">
             <div className="p-4 border-b border-slate-800 flex items-center justify-between">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center">
                    <Activity className="w-4 h-4 mr-2" /> Signals
                </h3>
                <span className="bg-red-500/20 text-red-400 text-[10px] px-2 py-0.5 rounded border border-red-500/30">{signals.length} Active</span>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                {signals.map((signal, idx) => (
                    <div key={idx} className={`p-3 rounded border text-xs relative overflow-hidden transition-all hover:bg-slate-800 ${signal.type === 'critical' ? 'bg-red-950/30 border-red-900/50' : 'bg-amber-950/20 border-amber-900/30'}`}>
                        <div className={`absolute left-0 top-0 bottom-0 w-1 ${signal.type === 'critical' ? 'bg-red-500' : 'bg-amber-500'}`}></div>
                        <div className="flex justify-between items-start mb-1 pl-2">
                             <span className={`font-bold ${signal.type === 'critical' ? 'text-red-400' : 'text-amber-400'}`}>
                                {signal.type.toUpperCase()}
                             </span>
                             <span className="text-slate-600">{new Date(signal.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                        <p className="pl-2 text-slate-400 leading-relaxed">
                            {signal.message}
                        </p>
                    </div>
                ))}
                {signals.length === 0 && (
                    <div className="text-center py-10 text-slate-600 text-sm">
                        No active anomalies detected.
                    </div>
                )}
             </div>
          </div>

          {/* Center Panel: Visualization */}
          <div className="flex-1 relative bg-slate-950 flex flex-col">
             {/* Graph Controls overlay */}
             <div className="absolute top-4 left-4 z-10 flex space-x-2">
                 <button className="p-2 bg-slate-900 border border-slate-700 rounded text-slate-400 hover:text-white hover:border-slate-500">
                     <Network className="w-4 h-4" />
                 </button>
                 <button className="p-2 bg-slate-900 border border-slate-700 rounded text-slate-400 hover:text-white hover:border-slate-500">
                     <Share2 className="w-4 h-4" />
                 </button>
             </div>

             {/* Canvas Container */}
             <div className="flex-1 overflow-hidden relative">
                 <canvas 
                    ref={canvasRef} 
                    width={800} 
                    height={600} 
                    className="w-full h-full cursor-crosshair"
                    onClick={handleCanvasClick}
                 />

                 {/* Empty State / Legend */}
                 <div className="absolute bottom-4 left-4 pointer-events-none">
                     <div className="flex items-center space-x-4 text-[10px] text-slate-500">
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-sky-500 mr-1 shadow shadow-sky-500"></span> Category</div>
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-emerald-500 mr-1 shadow shadow-emerald-500"></span> Product</div>
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-amber-500 mr-1 shadow shadow-amber-500"></span> Sale</div>
                     </div>
                 </div>
             </div>

             {/* Bottom Panel: Temporal Analysis (Heatmap) */}
             <div className="h-64 border-t border-slate-800 bg-slate-900/50 p-4">
                 <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4 flex items-center">
                    <Clock className="w-4 h-4 mr-2" /> Temporal Distribution (Volume by Hour/Day)
                 </h3>
                 <div className="w-full h-full pb-6">
                    <ResponsiveContainer width="100%" height="100%">
                        <ScatterChart
                            margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
                        >
                            <XAxis 
                                type="number" 
                                dataKey="hour" 
                                name="Hour" 
                                domain={[0, 23]} 
                                tickCount={24} 
                                tick={{fontSize: 10, fill: '#475569'}} 
                                tickLine={false}
                                axisLine={{stroke: '#334155'}}
                            />
                            <YAxis 
                                type="category" 
                                dataKey="dayName" 
                                name="Day" 
                                allowDuplicatedCategory={false} 
                                tick={{fontSize: 10, fill: '#475569'}}
                                tickLine={false}
                                axisLine={{stroke: '#334155'}}
                            />
                            <ZAxis type="number" dataKey="count" range={[0, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }} 
                                contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#e2e8f0', fontSize: '12px' }}
                                itemStyle={{ color: '#94a3b8' }}
                                formatter={(value: any, name: any) => [name === 'count' ? `${currencySymbol}${value}` : value, name === 'count' ? 'Volume' : name]}
                            />
                            <Scatter name="Sales" data={heatmapData} shape="circle">
                                {heatmapData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={`rgba(14, 165, 233, ${Math.min(0.8, Math.max(0.2, entry.count / 1000))})`} />
                                ))}
                            </Scatter>
                        </ScatterChart>
                    </ResponsiveContainer>
                 </div>
             </div>
          </div>

          {/* Right Panel: Object Inspector */}
          <div className="w-80 border-l border-slate-800 bg-slate-900/30 flex flex-col">
             <div className="p-4 border-b border-slate-800">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center">
                    <Maximize2 className="w-4 h-4 mr-2" /> Entity Inspector
                </h3>
             </div>

             <div className="p-6 flex-1 overflow-y-auto">
                 {selectedNode ? (
                     <div className="space-y-6 animate-fade-in">
                         <div className="flex items-start justify-between">
                            <div>
                                <div className="text-[10px] uppercase text-blue-500 font-bold mb-1 tracking-wider">{selectedNode.type}</div>
                                <h2 className="text-xl font-bold text-white leading-tight">{selectedNode.label}</h2>
                                <div className="text-slate-500 text-xs mt-1 font-mono">{selectedNode.id}</div>
                            </div>
                            {/* Icon based on type */}
                            <div className="p-3 bg-slate-800 rounded-lg border border-slate-700">
                                {selectedNode.type === 'category' && <Network className="w-6 h-6 text-sky-500" />}
                                {selectedNode.type === 'product' && <Target className="w-6 h-6 text-emerald-500" />}
                                {selectedNode.type === 'sale' && <Zap className="w-6 h-6 text-amber-500" />}
                            </div>
                         </div>

                         {/* Properties Table */}
                         <div className="border border-slate-700 rounded-lg overflow-hidden">
                             <table className="w-full text-xs">
                                 <tbody className="divide-y divide-slate-800">
                                     {selectedNode.data && Object.entries(selectedNode.data).map(([key, value]) => {
                                         if (key === 'items' || typeof value === 'object') return null; // Skip complex objects
                                         return (
                                             <tr key={key}>
                                                 <td className="px-3 py-2 bg-slate-900 text-slate-500 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</td>
                                                 <td className="px-3 py-2 text-slate-300 font-mono text-right">{String(value)}</td>
                                             </tr>
                                         );
                                     })}
                                     {!selectedNode.data && (
                                         <tr><td className="p-3 text-center text-slate-500">No additional metadata</td></tr>
                                     )}
                                 </tbody>
                             </table>
                         </div>

                         {/* Connected Actions */}
                         {selectedNode.type === 'product' && selectedNode.data && (
                             <div className="p-4 bg-emerald-950/20 border border-emerald-900/50 rounded-lg">
                                 <div className="text-xs text-emerald-400 mb-2 font-bold uppercase">Stock Status</div>
                                 <div className="text-2xl font-mono text-emerald-300">{selectedNode.data.quantity} <span className="text-sm text-emerald-600">units</span></div>
                                 <div className="w-full bg-slate-800 h-1 mt-2 rounded-full overflow-hidden">
                                     <div className="h-full bg-emerald-500" style={{ width: `${Math.min(100, (selectedNode.data.quantity / 50) * 100)}%` }}></div>
                                 </div>
                             </div>
                         )}

                         {selectedNode.type === 'sale' && selectedNode.data && (
                             <div>
                                 <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Items in Transaction</h4>
                                 <div className="space-y-1">
                                     {(selectedNode.data.items as any[]).map((item, i) => (
                                         <div key={i} className="flex justify-between items-center text-xs p-2 bg-slate-800/50 rounded border border-slate-800">
                                             <span className="text-slate-300">{item.name}</span>
                                             <span className="font-mono text-slate-500">x{item.quantity}</span>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         )}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-50">
                         <Target className="w-12 h-12 mb-4" />
                         <p className="text-sm text-center px-4">Select a node in the network graph to inspect details.</p>
                     </div>
                 )}
             </div>
          </div>
       </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { LayoutDashboard, Package, ShoppingCart, BrainCircuit, Menu, X, History, Wifi, WifiOff, Loader2, PieChart, Truck, LogOut, Shield, RefreshCw, Network } from 'lucide-react';
import { InventoryManager } from './components/InventoryManager';
import { SalesTerminal } from './components/SalesTerminal';
import { Dashboard } from './components/Dashboard';
import { AIInsights } from './components/AIInsights';
import { SalesHistory } from './components/SalesHistory';
import { ExpensesManager } from './components/ExpensesManager';
import { FinancialReport } from './components/FinancialReport';
import { PurchaseOrdersManager } from './components/PurchaseOrdersManager';
import { DeepAnalytics } from './components/DeepAnalytics';
import { Auth } from './components/Auth';
import { InventoryItem, SaleRecord, SaleItem, ViewState, ExpenseRecord, PurchaseOrder, UserRole, AuditLog } from './types';
import { supabase } from './services/supabaseClient';
import { Session } from '@supabase/supabase-js';

// Custom Cedi Icon Component
const CediSign = ({ className }: { className?: string }) => (
  <svg 
    xmlns="http://www.w3.org/2000/svg" 
    viewBox="0 0 24 24" 
    fill="none" 
    stroke="currentColor" 
    strokeWidth="2" 
    strokeLinecap="round" 
    strokeLinejoin="round" 
    className={className}
  >
    <path d="M16 7a6 6 0 1 0 0 10" />
    <path d="M10 3v18" />
  </svg>
);

const App: React.FC = () => {
  // Auth State
  const [session, setSession] = useState<Session | null>(null);
  const [authLoading, setAuthLoading] = useState(true);

  // State Management
  const [activeView, setActiveView] = useState<ViewState>('dashboard');
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Offline / Sync State
  const [pendingActions, setPendingActions] = useState<number>(0);
  const [isSyncing, setIsSyncing] = useState(false);

  // Data State
  const [inventory, setInventory] = useState<InventoryItem[]>([]);
  const [sales, setSales] = useState<SaleRecord[]>([]);
  const [expenses, setExpenses] = useState<ExpenseRecord[]>([]);
  const [purchaseOrders, setPurchaseOrders] = useState<PurchaseOrder[]>([]);
  const [auditLogs, setAuditLogs] = useState<AuditLog[]>([]);

  // Connectivity Listeners
  useEffect(() => {
    const handleOnline = () => setIsOnline(true);
    const handleOffline = () => setIsOnline(false);
    window.addEventListener('online', handleOnline);
    window.addEventListener('offline', handleOffline);
    return () => {
      window.removeEventListener('online', handleOnline);
      window.removeEventListener('offline', handleOffline);
    };
  }, []);

  // Auth Listener
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      setSession(session);
      setAuthLoading(false);
    });

    const {
      data: { subscription },
    } = supabase.auth.onAuthStateChange((_event, session) => {
      setSession(session);
      if (session) setActiveView('dashboard');
    });

    return () => subscription.unsubscribe();
  }, []);

  // Load Cached Data on Mount
  useEffect(() => {
    const loadLocal = (key: string, setter: any) => {
        const local = localStorage.getItem(key);
        if(local) setter(JSON.parse(local));
    };
    loadLocal('inventory', setInventory);
    loadLocal('sales', setSales);
    loadLocal('expenses', setExpenses);
    loadLocal('purchaseOrders', setPurchaseOrders);

    // Check pending actions
    const queue = JSON.parse(localStorage.getItem('offlineQueue') || '[]');
    setPendingActions(queue.length);
  }, []);

  // Persist Helper
  const persist = (key: string, data: any) => {
      localStorage.setItem(key, JSON.stringify(data));
  };

  // Queue Action Helper
  const queueAction = (action: any) => {
    const queue = JSON.parse(localStorage.getItem('offlineQueue') || '[]');
    queue.push(action);
    localStorage.setItem('offlineQueue', JSON.stringify(queue));
    setPendingActions(queue.length);
  };

  // Process Offline Queue (Sync)
  const processOfflineQueue = async () => {
    if (isSyncing) return;

    const queue = JSON.parse(localStorage.getItem('offlineQueue') || '[]');
    if (queue.length === 0) return;

    setIsSyncing(true);
    const newQueue = [...queue];

    try {
        while (newQueue.length > 0) {
            const action = newQueue[0];
            let success = false;

            try {
                switch (action.type) {
                    case 'ADD_ITEM':
                        await supabase.from('inventory').insert([action.payload]);
                        break;
                    case 'UPDATE_ITEM':
                        await supabase.from('inventory').update(action.payload.updates).eq('id', action.payload.id);
                        break;
                    case 'DELETE_ITEM':
                        await supabase.from('inventory').delete().eq('id', action.payload.id);
                        break;
                    case 'SALE':
                        const { sale, items } = action.payload;
                        const { error: saleErr } = await supabase.from('sales').insert([sale]);
                        if(saleErr) throw saleErr;

                        for (const item of items) {
                             const { data: curr } = await supabase.from('inventory').select('quantity').eq('id', item.itemId).single();
                             if(curr) {
                                 await supabase.from('inventory').update({ 
                                     quantity: curr.quantity - item.quantity,
                                     lastUpdated: new Date().toISOString()
                                 }).eq('id', item.itemId);
                             }
                        }
                        break;
                    case 'ADD_EXPENSE':
                        await supabase.from('expenses').insert([action.payload]);
                        break;
                    case 'DELETE_EXPENSE':
                        await supabase.from('expenses').delete().eq('id', action.payload.id);
                        break;
                    case 'CREATE_PO':
                         await supabase.from('purchase_orders').insert([action.payload]);
                         break;
                    case 'UPDATE_PO_STATUS':
                        const { id, status, po } = action.payload;
                        await supabase.from('purchase_orders').update({ status }).eq('id', id);
                        if (status === 'received' && po.status !== 'received') {
                             for (const item of po.items) {
                                 const { data: curr } = await supabase.from('inventory').select('quantity').eq('id', item.itemId).single();
                                 if(curr) {
                                     await supabase.from('inventory').update({
                                         quantity: curr.quantity + item.quantity,
                                         lastUpdated: new Date().toISOString()
                                     }).eq('id', item.itemId);
                                 }
                             }
                        }
                        break;
                }
                success = true;
            } catch (err) {
                console.error("Error syncing action:", action, err);
                // If permanent error, maybe remove? For now, we abort sync loop
                break;
            }

            if (success) {
                newQueue.shift();
                localStorage.setItem('offlineQueue', JSON.stringify(newQueue));
                setPendingActions(newQueue.length);
            }
        }
    } finally {
        setIsSyncing(false);
        if (newQueue.length === 0) fetchData(); // Refresh data after successful sync
    }
  };

  // Trigger Sync when Online
  useEffect(() => {
    if (isOnline && pendingActions > 0 && !isSyncing) {
        processOfflineQueue();
    }
  }, [isOnline, pendingActions]);


  // Fetch Data from Supabase
  const fetchData = async () => {
    if (!session) return;
    if (!isOnline) return; // Rely on cache if offline

    setLoading(true);
    try {
      // Fetch Inventory
      const { data: invData, error: invError } = await supabase.from('inventory').select('*');
      if (invError) throw invError;
      if (invData) {
          setInventory(invData);
          persist('inventory', invData);
      }

      // Fetch Sales
      const { data: salesData, error: salesError } = await supabase.from('sales').select('*').order('timestamp', { ascending: false });
      if (salesError) throw salesError;
      if (salesData) {
          setSales(salesData);
          persist('sales', salesData);
      }

      // Fetch Expenses
      const { data: expData, error: expError } = await supabase.from('expenses').select('*').order('date', { ascending: false });
      if (expError) throw expError;
      if (expData) {
          setExpenses(expData);
          persist('expenses', expData);
      }

      // Fetch Purchase Orders
      const { data: poData, error: poError } = await supabase.from('purchase_orders').select('*').order('date', { ascending: false });
      if (poError) console.warn("Could not fetch POs");
      else if (poData) {
          setPurchaseOrders(poData);
          persist('purchaseOrders', poData);
      }

    } catch (error) {
      console.error("Error fetching data:", error);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (session) fetchData();
  }, [session]);

  const logAction = (itemId: string, itemName: string, action: AuditLog['action'], details: string) => {
    if (!session?.user) return;
    const newLog: AuditLog = {
      id: crypto.randomUUID(),
      itemId,
      itemName,
      action,
      details,
      userId: session.user.email || 'Unknown User',
      timestamp: new Date().toISOString()
    };
    setAuditLogs(prev => [newLog, ...prev]);
  };

  // Handlers with Offline Support
  const handleAddItem = async (item: Omit<InventoryItem, 'id' | 'lastUpdated'>) => {
    const newItem: InventoryItem = {
      ...item,
      id: crypto.randomUUID(),
      lastUpdated: new Date().toISOString()
    };

    const newInventory = [...inventory, newItem];
    setInventory(newInventory);
    persist('inventory', newInventory);
    logAction(newItem.id, newItem.name, 'create', `Item created. Initial Stock: ${newItem.quantity}`);

    if (!isOnline) {
        queueAction({ type: 'ADD_ITEM', payload: newItem });
        return;
    }

    try {
      const { error } = await supabase.from('inventory').insert([newItem]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding item:", err);
      // Fallback behavior could be added here
    }
  };

  const handleUpdateItem = async (id: string, updates: Partial<InventoryItem>) => {
    const oldItem = inventory.find(i => i.id === id);
    if (!oldItem) return;

    const updatedTimestamp = new Date().toISOString();
    const finalUpdates = { ...updates, lastUpdated: updatedTimestamp };

    if (updates.quantity !== undefined && updates.quantity !== oldItem.quantity) {
       logAction(id, oldItem.name, 'adjustment', `Stock adjusted from ${oldItem.quantity} to ${updates.quantity}`);
    }

    const updatedInventory = inventory.map(item => item.id === id ? { ...item, ...finalUpdates } : item);
    setInventory(updatedInventory);
    persist('inventory', updatedInventory);

    if (!isOnline) {
        queueAction({ type: 'UPDATE_ITEM', payload: { id, updates: finalUpdates } });
        return;
    }

    try {
      const { error } = await supabase.from('inventory').update(finalUpdates).eq('id', id);
      if (error) throw error;
    } catch (err) {
      console.error("Error updating item:", err);
    }
  };

  const handleDeleteItem = async (id: string) => {
    if (window.confirm('Are you sure you want to delete this item?')) {
      const updatedInventory = inventory.filter(item => item.id !== id);
      setInventory(updatedInventory);
      persist('inventory', updatedInventory);

      if (!isOnline) {
          queueAction({ type: 'DELETE_ITEM', payload: { id } });
          return;
      }

      try {
        const { error } = await supabase.from('inventory').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting item:", err);
      }
    }
  };

  const handleCompleteSale = async (items: SaleItem[]) => {
    const totalAmount = items.reduce((sum, item) => sum + ((item.quantity * item.priceAtSale) - (item.discount || 0)), 0);
    const totalCost = items.reduce((sum, item) => sum + (item.quantity * item.costAtSale), 0);

    const newSale: SaleRecord = {
      id: crypto.randomUUID(),
      items,
      totalAmount,
      totalProfit: totalAmount - totalCost,
      timestamp: new Date().toISOString()
    };

    // Update Local Inventory & Sales
    const newInventory = [...inventory];
    items.forEach(saleItem => {
      const productIndex = newInventory.findIndex(p => p.id === saleItem.itemId);
      if (productIndex > -1) {
        const oldQty = newInventory[productIndex].quantity;
        const newQty = oldQty - saleItem.quantity;
        newInventory[productIndex] = { ...newInventory[productIndex], quantity: newQty, lastUpdated: new Date().toISOString() };
        logAction(saleItem.itemId, saleItem.name, 'sale', `Sold ${saleItem.quantity} units. Stock: ${oldQty} -> ${newQty}`);
      }
    });

    setInventory(newInventory);
    persist('inventory', newInventory);

    const newSales = [newSale, ...sales];
    setSales(newSales);
    persist('sales', newSales);

    if (!isOnline) {
        queueAction({ type: 'SALE', payload: { sale: newSale, items } });
        return;
    }

    try {
        const { error: saleError } = await supabase.from('sales').insert([newSale]);
        if (saleError) throw saleError;

        for (const item of items) {
             // Fetch current DB quantity to prevent race conditions
             const { data: curr } = await supabase.from('inventory').select('quantity').eq('id', item.itemId).single();
             if (curr) {
                 const newQty = curr.quantity - item.quantity;
                 await supabase.from('inventory').update({ 
                     quantity: newQty, 
                     lastUpdated: new Date().toISOString() 
                 }).eq('id', item.itemId);
             }
        }
    } catch (err) {
        console.error("Error processing sale:", err);
    }
  };

  const handleAddExpense = async (expense: Omit<ExpenseRecord, 'id' | 'recordedAt'>) => {
    const newExpense: ExpenseRecord = { ...expense, id: crypto.randomUUID(), recordedAt: new Date().toISOString() };

    const newExpenses = [newExpense, ...expenses];
    setExpenses(newExpenses);
    persist('expenses', newExpenses);

    if (!isOnline) {
        queueAction({ type: 'ADD_EXPENSE', payload: newExpense });
        return;
    }

    try {
      const { error } = await supabase.from('expenses').insert([newExpense]);
      if (error) throw error;
    } catch (err) {
      console.error("Error adding expense:", err);
    }
  };

  const handleDeleteExpense = async (id: string) => {
    if (window.confirm('Delete this expense record?')) {
      const newExpenses = expenses.filter(e => e.id !== id);
      setExpenses(newExpenses);
      persist('expenses', newExpenses);

      if (!isOnline) {
          queueAction({ type: 'DELETE_EXPENSE', payload: { id } });
          return;
      }

      try {
        const { error } = await supabase.from('expenses').delete().eq('id', id);
        if (error) throw error;
      } catch (err) {
        console.error("Error deleting expense:", err);
      }
    }
  };

  const handleCreatePO = async (po: Omit<PurchaseOrder, 'id'>) => {
    const newPO: PurchaseOrder = { ...po, id: crypto.randomUUID() };

    const newPOs = [newPO, ...purchaseOrders];
    setPurchaseOrders(newPOs);
    persist('purchaseOrders', newPOs);

    if (!isOnline) {
        queueAction({ type: 'CREATE_PO', payload: newPO });
        return;
    }

    try {
      const { error } = await supabase.from('purchase_orders').insert([newPO]);
      if (error) throw error;
    } catch (err) {
      console.error("Error creating PO:", err);
    }
  };

  const handleUpdatePOStatus = async (id: string, status: 'received' | 'cancelled') => {
    const po = purchaseOrders.find(p => p.id === id);
    if (!po) return;

    const newPOs = purchaseOrders.map(p => p.id === id ? { ...p, status } : p);
    setPurchaseOrders(newPOs);
    persist('purchaseOrders', newPOs);

    // Update Inventory Locally if Received
    if (status === 'received' && po.status !== 'received') {
        const updatedInventory = [...inventory];
        for (const item of po.items) {
           const invIndex = updatedInventory.findIndex(i => i.id === item.itemId);
           if (invIndex > -1) {
             updatedInventory[invIndex] = {
               ...updatedInventory[invIndex],
               quantity: updatedInventory[invIndex].quantity + item.quantity,
               lastUpdated: new Date().toISOString()
             };
             logAction(item.itemId, item.name, 'restock', `PO Received. Added ${item.quantity}.`);
           }
        }
        setInventory(updatedInventory);
        persist('inventory', updatedInventory);
    }

    if (!isOnline) {
        queueAction({ type: 'UPDATE_PO_STATUS', payload: { id, status, po } });
        return;
    }

    try {
      const { error } = await supabase.from('purchase_orders').update({ status }).eq('id', id);
      if (error) throw error;

      if (status === 'received' && po.status !== 'received') {
        for (const item of po.items) {
           const { data: curr } = await supabase.from('inventory').select('quantity').eq('id', item.itemId).single();
           if(curr) {
              await supabase.from('inventory').update({ quantity: curr.quantity + item.quantity, lastUpdated: new Date().toISOString() }).eq('id', item.itemId);
           }
        }
      }
    } catch (err) {
      console.error("Error updating PO status:", err);
    }
  };

  const handleSignOut = async () => {
    await supabase.auth.signOut();
  };

  const NavItem = ({ view, icon: Icon, label }: { view: ViewState, icon: any, label: string }) => (
    <button
      onClick={() => { setActiveView(view); setIsMobileMenuOpen(false); }}
      className={`w-full flex items-center space-x-3 px-6 py-4 transition-colors ${
        activeView === view 
          ? 'bg-blue-900 border-l-4 border-secondary text-white' 
          : 'text-blue-200 hover:bg-blue-800 hover:text-white'
      }`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  if (authLoading) {
      return (
          <div className="min-h-screen bg-slate-50 flex flex-col items-center justify-center text-primary">
              <Loader2 className="w-12 h-12 animate-spin mb-4" />
              <h1 className="text-2xl font-bold text-slate-800 mb-2">Raha Soldi Ent.</h1>
              <p className="text-slate-500 mt-2">Checking secure session...</p>
          </div>
      );
  }

  if (!session) {
    return <Auth />;
  }

  const userRole = (session.user.user_metadata?.role as UserRole) || 'cashier';

  // Special full-screen render for Deep Analytics
  if (activeView === 'analytics') {
    return (
      <div className="flex h-screen bg-slate-950 font-sans">
        <div className="fixed top-4 right-4 z-50">
           <button 
             onClick={() => setActiveView('dashboard')}
             className="px-4 py-2 bg-slate-800 border border-slate-700 text-slate-300 rounded hover:bg-slate-700 hover:text-white text-sm"
           >
             Exit War Room
           </button>
        </div>
        <DeepAnalytics inventory={inventory} sales={sales} currencySymbol="GH₵" />
      </div>
    );
  }

  return (
    <div className="flex min-h-screen bg-slate-50 font-sans">
      {/* Sidebar - Desktop */}
      <aside className="hidden lg:flex flex-col w-64 bg-primary text-white fixed h-full shadow-xl z-20">
        <div className="p-6 flex flex-col items-center border-b border-blue-800">
          <div className="flex items-center space-x-2 mb-2">
             <div className="bg-blue-800 p-2 rounded-lg">
               <LayoutDashboard className="w-6 h-6 text-white" />
             </div>
             <span className="text-lg font-bold">Raha Soldi Ent.</span>
          </div>
          <p className="text-xs text-blue-300 uppercase tracking-wider font-semibold">Inventory System</p>
        </div>
        <nav className="flex-1 mt-6 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={CediSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
              <div className="border-t border-blue-800 my-2 pt-2">
                <NavItem view="analytics" icon={Network} label="Deep Analytics" />
              </div>
            </>
          )}
        </nav>
        <div className="p-6 border-t border-blue-800">
             <div className="mb-4">
                 <div className="flex items-center space-x-2 mb-1">
                   <Shield className="w-3 h-3 text-secondary" />
                   <p className="text-xs text-blue-300 uppercase">{userRole}</p>
                 </div>
                 <p className="text-sm font-medium truncate" title={session.user.email}>{session.user.email}</p>
             </div>
            <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 hover:bg-blue-800 text-white py-2 rounded-lg transition-colors text-sm"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
            <div className="mt-4 space-y-2">
                <div className={`flex items-center justify-center text-xs px-3 py-2 rounded-lg ${isOnline ? 'bg-blue-800 text-blue-200' : 'bg-red-800 text-red-100'}`}>
                    {isOnline ? <Wifi className="w-3 h-3 mr-2" /> : <WifiOff className="w-3 h-3 mr-2" />}
                    {isOnline ? 'Online' : 'Offline Mode'}
                </div>
                {pendingActions > 0 && (
                    <div className="flex items-center justify-center text-xs px-3 py-2 rounded-lg bg-yellow-600 text-white animate-pulse">
                        <RefreshCw className={`w-3 h-3 mr-2 ${isSyncing ? 'animate-spin' : ''}`} />
                        {isSyncing ? 'Syncing...' : `${pendingActions} Pending`}
                    </div>
                )}
            </div>
        </div>
      </aside>

      {/* Mobile Header */}
      <div className="lg:hidden fixed top-0 w-full bg-primary text-white z-30 flex items-center justify-between p-4 shadow-md">
        <div className="flex items-center space-x-2">
            <div className="bg-blue-800 p-1.5 rounded-lg">
                <LayoutDashboard className="w-5 h-5 text-white" />
            </div>
            <span className="font-bold text-lg">Raha Soldi</span>
        </div>
        <button onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}>
          {isMobileMenuOpen ? <X /> : <Menu />}
        </button>
      </div>

      {/* Mobile Menu Overlay */}
      {isMobileMenuOpen && (
        <div className="lg:hidden fixed inset-0 bg-primary z-20 pt-20 overflow-y-auto">
          <NavItem view="dashboard" icon={LayoutDashboard} label="Dashboard" />
          <NavItem view="pos" icon={ShoppingCart} label="Point of Sale" />
          <NavItem view="history" icon={History} label="Sales History" />
          <NavItem view="inventory" icon={Package} label="Inventory" />

          {userRole === 'admin' && (
            <>
              <NavItem view="purchases" icon={Truck} label="Purchase Orders" />
              <NavItem view="expenses" icon={CediSign} label="Expenses" />
              <NavItem view="financials" icon={PieChart} label="Financial Reports" />
              <NavItem view="insights" icon={BrainCircuit} label="AI Insights" />
              <NavItem view="analytics" icon={Network} label="Deep Analytics" />
            </>
          )}

          <div className="p-4 border-t border-blue-800 mt-4">
             <button 
                onClick={handleSignOut}
                className="w-full flex items-center justify-center space-x-2 bg-blue-900 text-white py-3 rounded-lg"
            >
                <LogOut className="w-4 h-4" />
                <span>Sign Out</span>
            </button>
          </div>
        </div>
      )}

      {/* Main Content */}
      <main className="flex-1 lg:ml-64 p-4 lg:p-8 pt-20 lg:pt-8 transition-all duration-300">
        <div className="max-w-7xl mx-auto">
          <header className="mb-8 flex justify-between items-end">
            <div>
              <h2 className="text-2xl font-bold text-slate-800">
                {activeView === 'dashboard' && 'Business Overview'}
                {activeView === 'inventory' && 'Inventory Management'}
                {activeView === 'pos' && 'New Sale'}
                {activeView === 'history' && 'Transaction History'}
                {activeView === 'expenses' && 'Expense Management'}
                {activeView === 'financials' && 'Financial Health'}
                {activeView === 'insights' && 'Business Intelligence'}
                {activeView === 'purchases' && 'Supplier Purchase Orders'}
              </h2>
              <p className="text-slate-500 text-sm mt-1">
                {activeView === 'dashboard' && 'Welcome back.'}
                {activeView === 'inventory' && 'Manage your stock and pricing.'}
                {activeView === 'pos' && 'Process transactions quickly.'}
                {activeView === 'history' && 'Review past sales and performance.'}
                {activeView === 'expenses' && 'Track operational costs.'}
                {activeView === 'financials' && 'Analyze Profit & Loss and Balance Sheet.'}
                {activeView === 'insights' && 'AI-powered recommendations.'}
                {activeView === 'purchases' && 'Create orders and restock inventory.'}
              </p>
            </div>
            <div className="text-right hidden sm:block">
               <div className="text-sm font-bold text-slate-700">{new Date().toLocaleDateString('en-GB', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</div>
            </div>
          </header>

          <div className="fade-in">
             {loading ? (
                 <div className="flex flex-col items-center justify-center py-20 text-slate-400">
                     <Loader2 className="w-10 h-10 animate-spin mb-4" />
                     <p>Loading data...</p>
                 </div>
             ) : (
                <>
                    {activeView === 'dashboard' && <Dashboard inventory={inventory} sales={sales} currencySymbol="GH₵" userRole={userRole} />}
                    {activeView === 'inventory' && <InventoryManager inventory={inventory} onAdd={handleAddItem} onUpdate={handleUpdateItem} onDelete={handleDeleteItem} currencySymbol="GH₵" userRole={userRole} auditLogs={auditLogs} />}
                    {activeView === 'pos' && <SalesTerminal inventory={inventory} onCompleteSale={handleCompleteSale} currencySymbol="GH₵" />}
                    {activeView === 'history' && <SalesHistory sales={sales} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'expenses' && <ExpensesManager expenses={expenses} onAdd={handleAddExpense} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'financials' && <FinancialReport inventory={inventory} sales={sales} expenses={expenses} currencySymbol="GH₵" />}
                    {userRole === 'admin' && activeView === 'insights' && <AIInsights inventory={inventory} sales={sales} />}
                    {userRole === 'admin' && activeView === 'purchases' && (
                    <PurchaseOrdersManager 
                        inventory={inventory} 
                        purchaseOrders={purchaseOrders} 
                        onCreateOrder={handleCreatePO} 
                        onUpdateStatus={handleUpdatePOStatus} 
                        currencySymbol="GH₵" 
                    />
                    )}
                </>
             )}
          </div>
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { InventoryItem, SaleRecord } from '../types';
import { Search, Network, Zap, Activity, Filter, Maximize2, Share2, Target, Clock, AlertTriangle } from 'lucide-react';
import { ScatterChart, Scatter, XAxis, YAxis, ZAxis, Tooltip, ResponsiveContainer, Cell } from 'recharts';

interface DeepAnalyticsProps {
  inventory: InventoryItem[];
  sales: SaleRecord[];
  currencySymbol: string;
}

// Graph Types
interface Node {
  id: string;
  label: string;
  type: 'category' | 'product' | 'sale';
  value: number; // For sizing
  x?: number;
  y?: number;
  vx?: number;
  vy?: number;
  data?: any;
}

interface Link {
  source: string;
  target: string;
  value: number;
}

export const DeepAnalytics: React.FC<DeepAnalyticsProps> = ({ inventory, sales, currencySymbol }) => {
  const [selectedNode, setSelectedNode] = useState<Node | null>(null);
  const [searchTerm, setSearchTerm] = useState('');

  // --- SIGNAL DETECTION ---
  const signals = useMemo(() => {
    const alerts: { id: string; type: 'critical' | 'warning' | 'info'; message: string; timestamp: string }[] = [];

    // 1. High Discount Anomaly
    sales.forEach(sale => {
      const discountRatio = sale.items.reduce((acc, i) => acc + (i.discount || 0), 0) / (sale.totalAmount + 1); // +1 to avoid div0
      if (discountRatio > 0.25) {
        alerts.push({
          id: sale.id,
          type: 'warning',
          message: `High Discount detected (${(discountRatio * 100).toFixed(0)}%) on Sale ${sale.id.slice(-6)}`,
          timestamp: sale.timestamp
        });
      }
    });

    // 2. Stock Rapid Depletion (Mock logic: Low stock items that are selling fast)
    inventory.forEach(item => {
      if (item.quantity <= item.lowStockThreshold && item.quantity > 0) {
        alerts.push({
          id: item.id,
          type: 'critical',
          message: `Critical Stock Level: ${item.name} (${item.quantity} remaining)`,
          timestamp: new Date().toISOString()
        });
      }
    });

    return alerts.sort((a, b) => new Date(b.timestamp).getTime() - new Date(a.timestamp).getTime()).slice(0, 10);
  }, [sales, inventory]);

  // --- KNOWLEDGE GRAPH ENGINE ---
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [nodes, setNodes] = useState<Node[]>([]);
  const [links, setLinks] = useState<Link[]>([]);

  // Initialize Graph Data
  useEffect(() => {
    const newNodes: Node[] = [];
    const newLinks: Link[] = [];

    // 1. Category Nodes (Hubs)
    const categories = Array.from(new Set(inventory.map(i => i.category)));
    categories.forEach(cat => {
      newNodes.push({ id: `cat-${cat}`, label: String(cat), type: 'category', value: 20 });
    });

    // 2. Product Nodes
    // Limit to top 50 items by value to keep graph performant
    const topItems = [...inventory].sort((a, b) => (b.salesPrice * b.quantity) - (a.salesPrice * a.quantity)).slice(0, 50);
    topItems.forEach(item => {
      newNodes.push({ id: item.id, label: item.name, type: 'product', value: 10, data: item });
      // Link to Category
      newLinks.push({ source: item.id, target: `cat-${item.category}`, value: 1 });
    });

    // 3. Recent Big Sales (Context)
    // Find sales > avg value
    const avgSale = sales.reduce((acc, s) => acc + s.totalAmount, 0) / (sales.length || 1);
    const bigSales = sales.filter(s => s.totalAmount > avgSale * 1.5).slice(0, 10); // Top 10 recent big sales

    bigSales.forEach(sale => {
      newNodes.push({ id: sale.id, label: `Sale ${currencySymbol}${sale.totalAmount.toFixed(0)}`, type: 'sale', value: 15, data: sale });
      // Link Sale to Items involved
      sale.items.forEach(saleItem => {
        // Only link if item node exists in our graph
        if (newNodes.find(n => n.id === saleItem.itemId)) {
           newLinks.push({ source: sale.id, target: saleItem.itemId, value: 2 });
        }
      });
    });

    setNodes(newNodes.map(n => ({...n, x: Math.random() * 800, y: Math.random() * 600, vx: 0, vy: 0})));
    setLinks(newLinks);
  }, [inventory, sales, currencySymbol]);

  // Force Directed Simulation (Custom Implementation)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    let animationFrameId: number;

    const simulate = () => {
      const width = canvas.width;
      const height = canvas.height;
      const center = { x: width / 2, y: height / 2 };

      // Physics Constants
      const k = 0.05; // Spring constant
      const repulsion = 500;
      const damping = 0.9;

      // 1. Apply Forces
      for (let i = 0; i < nodes.length; i++) {
        const node = nodes[i];
        if (!node.x || !node.y) continue;

        let fx = 0, fy = 0;

        // Repulsion (Coulomb's Law-ish)
        for (let j = 0; j < nodes.length; j++) {
            if (i === j) continue;
            const other = nodes[j];
            const dx = node.x! - other.x!;
            const dy = node.y! - other.y!;
            const distSq = dx * dx + dy * dy;
            if (distSq > 0.1) {
                const force = repulsion / Math.sqrt(distSq);
                fx += (dx / Math.sqrt(distSq)) * force;
                fy += (dy / Math.sqrt(distSq)) * force;
            }
        }

        // Attraction (Springs)
        links.forEach(link => {
             // Find source and target objects (React state might have raw IDs, need to map)
             // Simplified: assumes indices or direct matching logic isn't needed if we loop links and find nodes
             // Optimization: Map links to indices once, but for < 100 nodes, find is okay
             const sourceNode = nodes.find(n => n.id === link.source);
             const targetNode = nodes.find(n => n.id === link.target);

             if (sourceNode && targetNode && sourceNode.id === node.id) {
                 const dx = targetNode.x! - node.x!;
                 const dy = targetNode.y! - node.y!;
                 fx += dx * k;
                 fy += dy * k;
             }
             if (sourceNode && targetNode && targetNode.id === node.id) {
                 const dx = sourceNode.x! - node.x!;
                 const dy = sourceNode.y! - node.y!;
                 fx += dx * k;
                 fy += dy * k;
             }
        });

        // Center Gravity
        fx += (center.x - node.x!) * 0.015;
        fy += (center.y - node.y!) * 0.015;

        // Update Velocity & Position
        node.vx = (node.vx || 0) + fx * 0.05;
        node.vy = (node.vy || 0) + fy * 0.05;
        node.vx *= damping;
        node.vy *= damping;

        node.x! += node.vx;
        node.y! += node.vy;
      }

      // 2. Render
      ctx.clearRect(0, 0, width, height);

      // Draw Links
      ctx.strokeStyle = '#334155'; // Slate 700
      ctx.lineWidth = 1;
      links.forEach(link => {
          const s = nodes.find(n => n.id === link.source);
          const t = nodes.find(n => n.id === link.target);
          if (s && t) {
              ctx.beginPath();
              ctx.moveTo(s.x!, s.y!);
              ctx.lineTo(t.x!, t.y!);
              ctx.stroke();
          }
      });

      // Draw Nodes
      nodes.forEach(node => {
          ctx.beginPath();
          ctx.arc(node.x!, node.y!, node.value * 0.8, 0, 2 * Math.PI);

          // Style based on type
          if (node.type === 'category') {
              ctx.fillStyle = '#0ea5e9'; // Sky Blue
              ctx.shadowColor = '#0ea5e9';
          } else if (node.type === 'product') {
              ctx.fillStyle = '#10b981'; // Emerald
              ctx.shadowColor = '#10b981';
          } else {
              ctx.fillStyle = '#f59e0b'; // Amber
              ctx.shadowColor = '#f59e0b';
          }

          // Glow effect for "War Room" feel
          ctx.shadowBlur = 10;
          ctx.fill();
          ctx.shadowBlur = 0; // Reset

          // Label (Conditional - only if large or selected)
          if (node.value > 12 || node === selectedNode) {
            ctx.fillStyle = '#94a3b8';
            ctx.font = '10px monospace';
            ctx.fillText(node.label, node.x! + 12, node.y! + 4);
          }

          // Selection Highlight
          if (node === selectedNode) {
              ctx.strokeStyle = '#fff';
              ctx.lineWidth = 2;
              ctx.stroke();
          }
      });

      animationFrameId = requestAnimationFrame(simulate);
    };

    simulate();
    return () => cancelAnimationFrame(animationFrameId);
  }, [nodes, links, selectedNode]);

  // Handle Canvas Click for Selection
  const handleCanvasClick = (e: React.MouseEvent) => {
      const rect = canvasRef.current?.getBoundingClientRect();
      if (!rect) return;
      const x = e.clientX - rect.left;
      const y = e.clientY - rect.top;

      // Find clicked node
      const clicked = nodes.find(node => {
          const dx = node.x! - x;
          const dy = node.y! - y;
          return Math.sqrt(dx*dx + dy*dy) < node.value + 5;
      });

      setSelectedNode(clicked || null);
  };

  // --- HEATMAP DATA ---
  const heatmapData = useMemo(() => {
    // 7x24 Grid. Days 0-6, Hours 0-23.
    const grid: { day: number; hour: number; count: number }[] = [];
    for(let d=0; d<7; d++) {
        for(let h=0; h<24; h++) {
            grid.push({ day: d, hour: h, count: 0 });
        }
    }

    sales.forEach(sale => {
        const date = new Date(sale.timestamp);
        const day = date.getDay();
        const hour = date.getHours();
        const cell = grid.find(c => c.day === day && c.hour === hour);
        if (cell) cell.count += sale.totalAmount; // Weight by volume
    });

    // Normalize for chart bubble size
    return grid.map(g => ({ ...g, dayName: ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'][g.day] }));
  }, [sales]);

  return (
    <div className="fixed inset-0 z-40 bg-slate-950 text-slate-200 font-mono overflow-hidden flex flex-col">
       {/* Top Bar */}
       <div className="h-16 border-b border-slate-800 flex items-center justify-between px-6 bg-slate-900/50 backdrop-blur-md">
          <div className="flex items-center space-x-3">
             <div className="p-2 bg-blue-500/10 rounded border border-blue-500/50">
                 <Target className="w-5 h-5 text-blue-400" />
             </div>
             <div>
                <h1 className="text-lg font-bold tracking-wider text-slate-100">DEEP ANALYTICS</h1>
                <p className="text-[10px] text-slate-500 uppercase tracking-[0.2em]">Raha Soldi Intelligence</p>
             </div>
          </div>

          <div className="flex-1 max-w-xl mx-8 relative group">
             <Search className="absolute left-3 top-2.5 h-4 w-4 text-slate-600 group-focus-within:text-blue-400 transition-colors" />
             <input 
                type="text" 
                placeholder="Search entities, transaction IDs, or SKU codes..." 
                className="w-full bg-slate-900 border border-slate-700 rounded-sm py-2 pl-10 pr-4 text-sm focus:outline-none focus:border-blue-500 focus:ring-1 focus:ring-blue-500 transition-all placeholder-slate-600 text-slate-300"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
             />
          </div>

          <div className="flex items-center space-x-4 text-xs">
             <div className="flex items-center text-green-400">
                <span className="w-2 h-2 bg-green-500 rounded-full mr-2 animate-pulse"></span>
                SYSTEM ONLINE
             </div>
             <div className="text-slate-500">
                {new Date().toLocaleTimeString()}
             </div>
          </div>
       </div>

       {/* Main Workspace */}
       <div className="flex-1 flex overflow-hidden">

          {/* Left Panel: Signal Feed */}
          <div className="w-80 border-r border-slate-800 bg-slate-900/30 flex flex-col">
             <div className="p-4 border-b border-slate-800 flex items-center justify-between">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center">
                    <Activity className="w-4 h-4 mr-2" /> Signals
                </h3>
                <span className="bg-red-500/20 text-red-400 text-[10px] px-2 py-0.5 rounded border border-red-500/30">{signals.length} Active</span>
             </div>
             <div className="flex-1 overflow-y-auto p-4 space-y-3 custom-scrollbar">
                {signals.map((signal, idx) => (
                    <div key={idx} className={`p-3 rounded border text-xs relative overflow-hidden transition-all hover:bg-slate-800 ${signal.type === 'critical' ? 'bg-red-950/30 border-red-900/50' : 'bg-amber-950/20 border-amber-900/30'}`}>
                        <div className={`absolute left-0 top-0 bottom-0 w-1 ${signal.type === 'critical' ? 'bg-red-500' : 'bg-amber-500'}`}></div>
                        <div className="flex justify-between items-start mb-1 pl-2">
                             <span className={`font-bold ${signal.type === 'critical' ? 'text-red-400' : 'text-amber-400'}`}>
                                {signal.type.toUpperCase()}
                             </span>
                             <span className="text-slate-600">{new Date(signal.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}</span>
                        </div>
                        <p className="pl-2 text-slate-400 leading-relaxed">
                            {signal.message}
                        </p>
                    </div>
                ))}
                {signals.length === 0 && (
                    <div className="text-center py-10 text-slate-600 text-sm">
                        No active anomalies detected.
                    </div>
                )}
             </div>
          </div>

          {/* Center Panel: Visualization */}
          <div className="flex-1 relative bg-slate-950 flex flex-col">
             {/* Graph Controls overlay */}
             <div className="absolute top-4 left-4 z-10 flex space-x-2">
                 <button className="p-2 bg-slate-900 border border-slate-700 rounded text-slate-400 hover:text-white hover:border-slate-500">
                     <Network className="w-4 h-4" />
                 </button>
                 <button className="p-2 bg-slate-900 border border-slate-700 rounded text-slate-400 hover:text-white hover:border-slate-500">
                     <Share2 className="w-4 h-4" />
                 </button>
             </div>

             {/* Canvas Container */}
             <div className="flex-1 overflow-hidden relative">
                 <canvas 
                    ref={canvasRef} 
                    width={800} 
                    height={600} 
                    className="w-full h-full cursor-crosshair"
                    onClick={handleCanvasClick}
                 />

                 {/* Empty State / Legend */}
                 <div className="absolute bottom-4 left-4 pointer-events-none">
                     <div className="flex items-center space-x-4 text-[10px] text-slate-500">
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-sky-500 mr-1 shadow shadow-sky-500"></span> Category</div>
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-emerald-500 mr-1 shadow shadow-emerald-500"></span> Product</div>
                         <div className="flex items-center"><span className="w-2 h-2 rounded-full bg-amber-500 mr-1 shadow shadow-amber-500"></span> Sale</div>
                     </div>
                 </div>
             </div>

             {/* Bottom Panel: Temporal Analysis (Heatmap) */}
             <div className="h-64 border-t border-slate-800 bg-slate-900/50 p-4">
                 <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider mb-4 flex items-center">
                    <Clock className="w-4 h-4 mr-2" /> Temporal Distribution (Volume by Hour/Day)
                 </h3>
                 <div className="w-full h-full pb-6">
                    <ResponsiveContainer width="100%" height="100%">
                        <ScatterChart
                            margin={{ top: 0, right: 0, bottom: 0, left: 0 }}
                        >
                            <XAxis 
                                type="number" 
                                dataKey="hour" 
                                name="Hour" 
                                domain={[0, 23]} 
                                tickCount={24} 
                                tick={{fontSize: 10, fill: '#475569'}} 
                                tickLine={false}
                                axisLine={{stroke: '#334155'}}
                            />
                            <YAxis 
                                type="category" 
                                dataKey="dayName" 
                                name="Day" 
                                allowDuplicatedCategory={false} 
                                tick={{fontSize: 10, fill: '#475569'}}
                                tickLine={false}
                                axisLine={{stroke: '#334155'}}
                            />
                            <ZAxis type="number" dataKey="count" range={[0, 400]} />
                            <Tooltip 
                                cursor={{ strokeDasharray: '3 3' }} 
                                contentStyle={{ backgroundColor: '#0f172a', borderColor: '#334155', color: '#e2e8f0', fontSize: '12px' }}
                                itemStyle={{ color: '#94a3b8' }}
                                formatter={(value: any, name: any) => [name === 'count' ? `${currencySymbol}${value}` : value, name === 'count' ? 'Volume' : name]}
                            />
                            <Scatter name="Sales" data={heatmapData} shape="circle">
                                {heatmapData.map((entry, index) => (
                                    <Cell key={`cell-${index}`} fill={`rgba(14, 165, 233, ${Math.min(0.8, Math.max(0.2, entry.count / 1000))})`} />
                                ))}
                            </Scatter>
                        </ScatterChart>
                    </ResponsiveContainer>
                 </div>
             </div>
          </div>

          {/* Right Panel: Object Inspector */}
          <div className="w-80 border-l border-slate-800 bg-slate-900/30 flex flex-col">
             <div className="p-4 border-b border-slate-800">
                <h3 className="text-xs font-bold text-slate-400 uppercase tracking-wider flex items-center">
                    <Maximize2 className="w-4 h-4 mr-2" /> Entity Inspector
                </h3>
             </div>

             <div className="p-6 flex-1 overflow-y-auto">
                 {selectedNode ? (
                     <div className="space-y-6 animate-fade-in">
                         <div className="flex items-start justify-between">
                            <div>
                                <div className="text-[10px] uppercase text-blue-500 font-bold mb-1 tracking-wider">{selectedNode.type}</div>
                                <h2 className="text-xl font-bold text-white leading-tight">{selectedNode.label}</h2>
                                <div className="text-slate-500 text-xs mt-1 font-mono">{selectedNode.id}</div>
                            </div>
                            {/* Icon based on type */}
                            <div className="p-3 bg-slate-800 rounded-lg border border-slate-700">
                                {selectedNode.type === 'category' && <Network className="w-6 h-6 text-sky-500" />}
                                {selectedNode.type === 'product' && <Target className="w-6 h-6 text-emerald-500" />}
                                {selectedNode.type === 'sale' && <Zap className="w-6 h-6 text-amber-500" />}
                            </div>
                         </div>

                         {/* Properties Table */}
                         <div className="border border-slate-700 rounded-lg overflow-hidden">
                             <table className="w-full text-xs">
                                 <tbody className="divide-y divide-slate-800">
                                     {selectedNode.data && Object.entries(selectedNode.data).map(([key, value]) => {
                                         if (key === 'items' || typeof value === 'object') return null; // Skip complex objects
                                         return (
                                             <tr key={key}>
                                                 <td className="px-3 py-2 bg-slate-900 text-slate-500 capitalize">{key.replace(/([A-Z])/g, ' $1').trim()}</td>
                                                 <td className="px-3 py-2 text-slate-300 font-mono text-right">{String(value)}</td>
                                             </tr>
                                         );
                                     })}
                                     {!selectedNode.data && (
                                         <tr><td className="p-3 text-center text-slate-500">No additional metadata</td></tr>
                                     )}
                                 </tbody>
                             </table>
                         </div>

                         {/* Connected Actions */}
                         {selectedNode.type === 'product' && selectedNode.data && (
                             <div className="p-4 bg-emerald-950/20 border border-emerald-900/50 rounded-lg">
                                 <div className="text-xs text-emerald-400 mb-2 font-bold uppercase">Stock Status</div>
                                 <div className="text-2xl font-mono text-emerald-300">{selectedNode.data.quantity} <span className="text-sm text-emerald-600">units</span></div>
                                 <div className="w-full bg-slate-800 h-1 mt-2 rounded-full overflow-hidden">
                                     <div className="h-full bg-emerald-500" style={{ width: `${Math.min(100, (selectedNode.data.quantity / 50) * 100)}%` }}></div>
                                 </div>
                             </div>
                         )}

                         {selectedNode.type === 'sale' && selectedNode.data && (
                             <div>
                                 <h4 className="text-xs font-bold text-slate-400 uppercase mb-2">Items in Transaction</h4>
                                 <div className="space-y-1">
                                     {(selectedNode.data.items as any[]).map((item, i) => (
                                         <div key={i} className="flex justify-between items-center text-xs p-2 bg-slate-800/50 rounded border border-slate-800">
                                             <span className="text-slate-300">{item.name}</span>
                                             <span className="font-mono text-slate-500">x{item.quantity}</span>
                                         </div>
                                     ))}
                                 </div>
                             </div>
                         )}
                     </div>
                 ) : (
                     <div className="h-full flex flex-col items-center justify-center text-slate-600 opacity-50">
                         <Target className="w-12 h-12 mb-4" />
                         <p className="text-sm text-center px-4">Select a node in the network graph to inspect details.</p>
                     </div>
                 )}
             </div>
          </div>
       </div>
    </div>
  );
};

